const COLUMN_BINDINGS = ['app', 'readerMinimap', 'readerLoading'];


let leftColumn = null;
let rightColumn = null;

let keyedColumn = null;

let freshColumnState = null;


function makeColumn(side, reader, rail, loading, fade) {
  return { side, reader, rail, loading, fade, held: null };
}


function freshColumnRecord() {
  const held = {};
  for (const name of COLUMN_STATE_NAMES) held[name] = freshColumnState[name];
  return held;
}


function enterColumn(column) {
  saveColumnState(keyedColumn);
  keyedColumn = column;
  loadColumnState(column);
  app = column.reader;
  readerMinimap = column.rail;
  readerLoading = column.loading;
}


function focusColumn(column) {
  if (!column || column === keyedColumn) return;
  keyedColumn.reader.classList.remove('is-keyed');
  enterColumn(column);
  column.reader.classList.add('is-keyed');
  
  if (readerToolbar) readerToolbar.classList.toggle('is-keyed-right', column === rightColumn);
  
  writeViewFades();
  
  scheduleLibraryOutline();
}


let workingTheCardBeside = false;
function renderIsForTheCardBeside() {
  return workingTheCardBeside;
}


function withColumn(column, work) {
  if (!column || column === keyedColumn) return work();
  const held = keyedColumn;
  const wasBeside = workingTheCardBeside;
  workingTheCardBeside = true;
  enterColumn(column);
  try {
    return work();
  } finally {
    enterColumn(held);
    workingTheCardBeside = wasBeside;
  }
}


function writeReaderClasses(extra) {
  const own = ['reader-shell', 'reader-column'];
  if (keyedColumn === rightColumn) own.push('reader-column-right');
  if (app.classList.contains('is-keyed')) own.push('is-keyed');
  
  if (splitOpen()) own.push('is-split');
  app.className = own.concat(extra).join(' ');
}


function writeViewFades() {
  const underMap = document.documentElement.dataset.graphView === 'true';
  for (const column of [leftColumn, rightColumn]) {
    if (!column || !column.fade) continue;
    const mine = column === keyedColumn;
    column.fade.classList.toggle('is-code-view', mine && codeViewActive);
    column.fade.classList.toggle('is-under-map', mine && underMap);
  }
}


function splitOpen() {
  return !!rightColumn && !rightColumn.reader.hidden;
}


function besideColumn() {
  if (!splitOpen()) return null;
  return keyedColumn === leftColumn ? rightColumn : leftColumn;
}


function onColumn(type, handler, options) {
  for (const column of [leftColumn, rightColumn]) {
    if (!column || !column.reader) continue;
    column.reader.addEventListener(type, (event) => withColumn(column, () => handler(event)), options);
  }
}


function besideTabIndex() {
  const beside = currentState && currentState.beside;
  return beside && typeof beside.tab === 'number' ? beside.tab : null;
}


function rightCardTabIndex() {
  const index = besideTabIndex();
  if (index === null) return null;
  return currentState.beside.side === 'left' ? currentState.active : index;
}


function besideIsTheSameTab() {
  const index = besideTabIndex();
  return index !== null && !!currentState && index === currentState.active;
}


function pressIntoColumn(column) {
  if (!splitOpen() || column === keyedColumn) return;
  
  if (besideIsTheSameTab()) return;
  const index = besideTabIndex();
  
  if (codeViewActive) toggleCodeView();
  focusColumn(column);
  if (index === null) return;
  send({
    command: 'switchTab',
    index,
    scroll_anchor: { section: null, block: 0, offsetY: 0 },
    code_scroll: null,
  });
}


function startColumns() {
  
  const saved = window.__leafSettings;
  splitFraction = clampSplitFraction(saved && Number(saved.splitFraction));
  leftColumn = makeColumn('left', app, readerMinimap, readerLoading, readerLeftEdgeFade);
  rightColumn = makeColumn(
    'right',
    rightColumnShell,
    document.querySelector('.reader-minimap-right'),
    document.querySelector('.reader-loading-right'),
    document.querySelector('.reader-edge-fade-second')
  );
  keyedColumn = leftColumn;
  for (const column of [leftColumn, rightColumn]) {
    if (!column.reader) continue;
    
    column.reader.addEventListener('pointerdown', () => pressIntoColumn(column), true);
  }
}


function settleColumnState() {
  freshColumnState = {};
  saveColumnState({ held: freshColumnState });
  leftColumn.held = freshColumnRecord();
  rightColumn.held = freshColumnRecord();
}






function columnFrame(work) {
  if (!splitOpen()) return window.requestAnimationFrame(work);
  const column = keyedColumn;
  return window.requestAnimationFrame(() => withColumn(column, work));
}
function columnTimer(work, delay) {
  if (!splitOpen()) return window.setTimeout(work, delay);
  const column = keyedColumn;
  return window.setTimeout(() => withColumn(column, work), delay);
}

function inThisColumn(work) {
  const column = keyedColumn;
  return function columnBound(...args) {
    return withColumn(column, () => work.apply(this, args));
  };
}


let besideAwaitingPage = false;
let besideInLastPayload = false;
let splitDrawnOpen = false;
function besideWaitingForPage() {
  return besideAwaitingPage && !!besideColumn();
}


function applySplit(beside) {
  if (!rightColumn || !rightColumn.reader) return;
  
  if (!!beside !== besideInLastPayload) besideAwaitingPage = !!beside;
  besideInLastPayload = !!beside;
  const line = readerSplitLine;
  const seam = readerSeamBand;
  const open = !!beside && !splitTooNarrow();
  rightColumn.reader.hidden = !open;
  if (rightColumn.rail) rightColumn.rail.hidden = !open;
  if (rightColumn.loading) rightColumn.loading.hidden = true;
  if (rightColumn.fade) rightColumn.fade.hidden = !open;
  if (line) line.hidden = !open;
  if (seam) seam.hidden = !open;
  document.body.classList.toggle('has-split', open);
  
  leftColumn.reader.classList.toggle('is-split', open);
  rightColumn.reader.classList.toggle('is-split', open);
  writeSplitColumns(open);
  
  const keyed = !open || !beside || beside.side === 'right' ? leftColumn : rightColumn;
  focusColumn(keyed);
  
  if (open !== splitDrawnOpen) {
    splitDrawnOpen = open;
    scheduleLibraryOutline();
  }
  
  writeStripShares();
}


function refitSplit() {
  if (!currentState || !currentState.beside) return;
  applySplit(currentState.beside);
}


function splitTooNarrow() {
  return leafShellWidth() < SNAP_SHUT + MIN_READER_WIDTH * 2;
}


function drawBesideColumn(state, anchor) {
  const column = besideColumn();
  if (!column) return;
  withColumn(column, () => {
    
    currentState = Object.assign({}, state);
    renderState(true, anchor || null);
    if (anchor) restoreReaderScrollAnchor(anchor);
    else resetReaderScrollToContentStart();
    updateMinimapViewport();
    
    clearReaderLoading();
  });
  
  const laidOutWithRail = drawnBesideMinimapColumn !== '0px';
  besideAwaitingPage = false;
  if (splitColumnsOpen && besideRailColumnOpen() !== laidOutWithRail) writeSplitColumns(true);
}


window.addEventListener('keydown', (event) => {
  if (!(event.ctrlKey || event.metaKey) || event.altKey || event.shiftKey) return;
  if (event.key !== '\\') return;
  event.preventDefault();
  if (splitOpen()) {
    send({ command: 'closeBeside' });
    return;
  }
  
  if (currentState && typeof currentState.active === 'number') send({ command: 'openBeside', index: currentState.active });
});



const SPLIT_FRACTION_FLOOR = 0.2;
const SPLIT_FRACTION_CEILING = 0.8;
function clampSplitFraction(value) {
  if (!Number.isFinite(value)) return 0.5;
  return Math.min(SPLIT_FRACTION_CEILING, Math.max(SPLIT_FRACTION_FLOOR, value));
}

let splitFraction = 0.5;

function splitShares() {
  return { left: splitFraction, right: 1 - splitFraction };
}

function drawSplitFraction(fraction) {
  splitFraction = clampSplitFraction(fraction);
  writeRestingPaneWidth();
}






function writeStripShares() {
  if (!tabBar) return;
  
  document.body.classList.toggle('beside-on-the-left', splitColumnsOpen && keyedColumn === rightColumn);
  if (!splitColumnsOpen || !leftColumn || !rightColumn) {
    tabBar.style.removeProperty('--strip-part-left');
    return;
  }
  const box = tabBar.getBoundingClientRect();
  const style = getComputedStyle(tabBar);
  const inset = Number.parseFloat(style.paddingLeft) || 0;
  const gap = Number.parseFloat(style.columnGap) || 0;
  const second = rightColumn.reader.getBoundingClientRect().left;
  
  const width = Math.max(0, Math.min(box.width - inset * 2, second - (box.left + inset) - gap));
  tabBar.style.setProperty('--strip-part-left', `${width}px`);
}



let splitDrag = null;
function applyPendingSplitFraction() {
  if (!splitDrag) return;
  splitDrag.frame = 0;
  if (splitDrag.pending != null) drawSplitFraction(splitDrag.pending);
}
function endSplitDrag(flushPending) {
  if (!splitDrag) return;
  const frame = splitDrag.frame;
  if (flushPending) applyPendingSplitFraction();
  if (frame) cancelAnimationFrame(frame);
  leafReleasePointer(splitDrag.line, splitDrag.pointerId);
  splitDrag = null;
  document.body.classList.remove('split-resizing');
}
function startSplitDrag(event) {
  const line = readerSplitLine;
  if (!line || event.button !== 0 || !splitOpen()) return;
  const leftBox = leftColumn.reader.getBoundingClientRect();
  const rightBox = rightColumn.reader.getBoundingClientRect();
  const room = leftBox.width + rightBox.width;
  if (room <= 0) return;
  event.preventDefault();
  splitDrag = { line, pointerId: event.pointerId, frame: 0, pending: null, startX: event.clientX, startLeft: leftBox.width, room };
  leafHoldPointer(line, event.pointerId);
  document.body.classList.add('split-resizing');
}
function moveSplitDrag(event) {
  if (!splitDrag || event.pointerId !== splitDrag.pointerId) return;
  const leftWidth = splitDrag.startLeft + (event.clientX - splitDrag.startX);
  
  if (leftWidth < MIN_READER_WIDTH || splitDrag.room - leftWidth < MIN_READER_WIDTH) {
    endSplitDrag(false);
    send({ command: 'closeBeside' });
    return;
  }
  splitDrag.pending = leftWidth / splitDrag.room;
  if (!splitDrag.frame) splitDrag.frame = requestAnimationFrame(applyPendingSplitFraction);
}
function releaseSplitDrag(event) {
  if (!splitDrag || event.pointerId !== splitDrag.pointerId) return;
  endSplitDrag(true);
  send({ command: 'setSplitLayout', fraction: splitFraction });
}



function overSplitDropHalf(clientX, clientY) {
  if (splitOpen() || !keyedColumn || !keyedColumn.reader) return false;
  const box = keyedColumn.reader.getBoundingClientRect();
  if (box.width <= 0 || box.height <= 0) return false;
  return clientY >= box.top && clientY <= box.bottom && clientX >= box.left + box.width / 2 && clientX <= Math.max(box.right, window.innerWidth);
}

function outsideEveryReader(element) {
  if (!element) return false;
  for (const column of [leftColumn, rightColumn]) {
    if (column && column.reader && column.reader.contains(element)) return false;
  }
  return true;
}


function splitCloseSideUnder(clientX, clientY, from) {
  if (!splitOpen() || !(currentState && currentState.beside) || !from || !stripRightGroup || !stripRightGroup.contains(from)) return null;
  for (const element of [leftColumn && leftColumn.reader, stripLeftGroup]) {
    if (!element || element.hidden) continue;
    const box = element.getBoundingClientRect();
    if (box.width > 0 && clientX >= box.left && clientX <= box.right && clientY >= box.top && clientY <= box.bottom) return 'right';
  }
  return null;
}

function drawSplitDropZone(showing, name, closes) {
  if (!readerDropZone) return;
  const mark = closes ? 'closes-' + closes : '';
  const drawnMark = ['closes-left', 'closes-right'].find((one) => readerDropZone.classList.contains(one)) || '';
  if (showing && (readerDropZone.hidden || drawnMark !== mark)) {
    readerDropZone.classList.toggle('closes-left', mark === 'closes-left');
    readerDropZone.classList.toggle('closes-right', mark === 'closes-right');
    if (!mark) readerDropZone.style.setProperty('--drop-beside-share', String(splitShares().right));
    if (readerDropZoneName) readerDropZoneName.textContent = mark ? '' : name || '';
  }
  readerDropZone.hidden = !showing;
}


