const COLUMN_PICTURE_SOURCES = 'img[src], source[src], source[srcset], video[src], video[poster], audio[src]';
function resolveColumnPictures(reader, layout) {
  if (!layout || !rightColumn || reader !== rightColumn.reader) return;
  const base = layout.querySelector('base[href]');
  if (!base) return;
  const folder = base.getAttribute('href');
  base.remove();
  if (!folder) return;
  const absolute = (value) => {
    try {
      return new URL(value, folder).href;
    } catch (_) {
      return value;
    }
  };
  for (const element of layout.querySelectorAll(COLUMN_PICTURE_SOURCES)) {
    for (const name of ['src', 'poster']) {
      const value = element.getAttribute(name);
      if (value) element.setAttribute(name, absolute(value));
    }
    const set = element.getAttribute('srcset');
    
    if (set) element.setAttribute('srcset', set.split(',').map((one) => {
      const parts = one.trim().split(/\s+/);
      if (!parts[0]) return one;
      parts[0] = absolute(parts[0]);
      return parts.join(' ');
    }).join(', '));
  }
}




function escapeText(value) {
  return String(value).replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
}
function escapeAttr(value) {
  return escapeText(value).replace(/`/g, '&#96;');
}

function formatCount(value) {
  const number = Number(value);
  return Number.isFinite(number) ? number.toLocaleString('en-US') : String(value);
}

function formatCountLabel(value, singular, plural) {
  return `${formatCount(value)} ${Number(value) === 1 ? singular : plural}`;
}















