const FLOW_EDGE_LINES = [
  { id: 'solid', label: 'Solid', unit: '-', least: 2, open: '', shut: '', plainTail: '-', labelOpen: '--', labelBody: '--' },
  { id: 'dotted', label: 'Dotted', unit: '.', least: 1, open: '-', shut: '-', plainTail: '', labelOpen: '-.', labelBody: '.-' },
  { id: 'thick', label: 'Thick', unit: '=', least: 2, open: '', shut: '', plainTail: '=', labelOpen: '==', labelBody: '==' },
  { id: 'invisible', label: 'Invisible', unit: '~', least: 3, open: '', shut: '', plainTail: '', only: 'none' },
];


const FLOW_EDGE_ENDS = [
  { id: 'arrow', label: 'Arrow', head: '', tail: '>' },
  { id: 'none', label: 'Plain', head: '', tail: '' },
  { id: 'circle', label: 'Circle', head: '', tail: 'o' },
  { id: 'cross', label: 'Cross', head: '', tail: 'x' },
  { id: 'both', label: 'Both ways', head: '<', tail: '>' },
  { id: 'both-circle', label: 'Circles', head: 'o', tail: 'o' },
  { id: 'both-cross', label: 'Crosses', head: 'x', tail: 'x' },
];


function flowEndMark(mark) {
  if (mark === '>' || mark === '<') return 'arrow';
  if (mark === 'o') return 'circle';
  if (mark === 'x') return 'cross';
  return null;
}


function flowEndsFor(line) {
  return line.only ? FLOW_EDGE_ENDS.filter((end) => end.id === line.only) : FLOW_EDGE_ENDS;
}


function flowEdgeToken(line, end, stretch) {
  const run = line.unit.repeat(line.least + Math.max(0, stretch || 0));
  return end.head + line.open + run + line.shut + (end.tail || line.plainTail);
}


const FLOW_EDGE_TOKENS = [];
for (const line of FLOW_EDGE_LINES) {
  for (const end of flowEndsFor(line)) {
    const before = end.head + line.open;
    const after = line.shut + (end.tail || line.plainTail);
    FLOW_EDGE_TOKENS.push({
      re: new RegExp(
        '^' + flowEscapeRe(before) + '(' + flowEscapeRe(line.unit) + '{' + line.least + ',})' + flowEscapeRe(after),
      ),
      least: line.least,
      weight: before.length + after.length,
      line: line.id,
      ends: end.id,
    });
  }
}
FLOW_EDGE_TOKENS.sort((a, b) => b.weight - a.weight);


const FLOW_EDGE_LABELED = [];
for (const line of FLOW_EDGE_LINES) {
  if (!line.labelOpen) continue;
  for (const end of flowEndsFor(line)) {
    const open = end.head + line.labelOpen;
    const close = line.labelBody + (end.tail || line.plainTail);
    FLOW_EDGE_LABELED.push({
      re: new RegExp('^' + flowEscapeRe(open) + '[ \\t]*([^-<>|=\\n]+?)[ \\t]*' + flowEscapeRe(close)),
      weight: open.length * 10 + close.length,
      line: line.id,
      ends: end.id,
    });
  }
}
FLOW_EDGE_LABELED.sort((a, b) => b.weight - a.weight);

function flowEscapeRe(text) {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

const FLOW_DIRECTIONS = [
  { id: 'TD', label: 'Top down' },
  { id: 'LR', label: 'Left to right' },
  { id: 'BT', label: 'Bottom up' },
  { id: 'RL', label: 'Right to left' },
];


const FLOW_HEADER_RE = /^[ \t]*(?:flowchart|graph)(?:[ \t]+(TD|TB|BT|LR|RL))?[ \t]*$/i;

const FLOW_COMMENT_RE = /^[ \t]*%%/;
const FLOW_ACC_RE = /^[ \t]*acc(?:Title|Descr)[ \t]*:/;

const FLOW_ID_RE = /^[A-Za-z0-9_][A-Za-z0-9_.]*(?:-[A-Za-z0-9_][A-Za-z0-9_.]*)*/;

const FLOW_CLASSDEF_RE = /^[ \t]*classDef[ \t]+\S[\s\S]*$/;
const FLOW_CLASS_RE = /^[ \t]*class[ \t]+([A-Za-z0-9_.,\- \t]+?)[ \t]+([A-Za-z0-9_-]+)[ \t]*;?[ \t]*$/;
const FLOW_STYLE_RE = /^[ \t]*style[ \t]+([A-Za-z0-9_.-]+)[ \t]+(\S.*?)[ \t]*;?[ \t]*$/;
const FLOW_LINKSTYLE_RE = /^[ \t]*linkStyle[ \t]+(default|[0-9][0-9, \t]*?)[ \t]+(\S.*?)[ \t]*;?[ \t]*$/;

const FLOW_CLICK_RE = /^click[ \t]+([A-Za-z0-9_][A-Za-z0-9_.-]*)[ \t]+(?:href[ \t]+)?"([^"]*)"(?:[ \t]+"([^"]*)")?[ \t]*;?[ \t]*$/;

const FLOW_CLICK_CALL_RE = /^click[ \t]+[A-Za-z0-9_][A-Za-z0-9_.-]*[ \t]+call(?:back)?\b/;

const FLOW_NODE_CLASS_RE = /^:::([A-Za-z0-9_-]+)/;

const FLOW_EDGE_NAME_RE = /^([A-Za-z0-9_][A-Za-z0-9_.-]*)@(?!\{)/;
const FLOW_EDGE_ATTR_RE = /^[ \t]*([A-Za-z0-9_][A-Za-z0-9_.-]*)@\{(.*)\}[ \t]*$/;
const FLOW_ANIMATION_KEYS = ['animate', 'animation'];

const FLOW_SUBGRAPH_RE = /^[ \t]*subgraph[ \t]+(\S[\s\S]*?)[ \t]*$/;
const FLOW_END_RE = /^[ \t]*end[ \t]*;?[ \t]*$/i;
const FLOW_DIRECTION_RE = /^[ \t]*direction[ \t]+(TD|TB|BT|LR|RL)[ \t]*$/i;
const FLOW_SUBGRAPH_TITLED_RE = /^([A-Za-z0-9_][A-Za-z0-9_.-]*)[ \t]*\[(.*)\]$/;
const FLOW_INDENT = '    ';

const FLOW_QUOTE_ENTITY = '#quot;';


const FLOW_STARTER = 'flowchart TD\n' + FLOW_INDENT + 'n1(["Start"])';

function flowShape(id) {
  return FLOW_SHAPES.find((shape) => shape.id === id) || FLOW_SHAPES[0];
}

function flowEdgeLine(id) {
  return FLOW_EDGE_LINES.find((line) => line.id === id) || FLOW_EDGE_LINES[0];
}

function flowEdgeEnd(id) {
  return FLOW_EDGE_ENDS.find((end) => end.id === id) || FLOW_EDGE_ENDS[0];
}

function decodeFlowLabel(raw) {
  return String(raw).split(FLOW_QUOTE_ENTITY).join('"');
}

function encodeFlowLabel(text) {
  return String(text == null ? '' : text).split('"').join(FLOW_QUOTE_ENTITY);
}


function flowBareLabelOk(raw) {
  const text = raw.trim();
  if (!text) return false;
  if (/[[\]{}()<>"'|;#&`]/.test(text)) return false;
  if (/^[/\\]/.test(text) || /[/\\]$/.test(text)) return false;
  return true;
}


function takeFlowLabel(rest, close) {
  if (rest.startsWith('"')) {
    const end = rest.indexOf('"', 1);
    if (end < 0) return null;
    const raw = rest.slice(1, end);
    if (!rest.slice(end + 1).startsWith(close)) return null;
    return { text: decodeFlowLabel(raw), rest: rest.slice(end + 1 + close.length) };
  }
  const end = rest.indexOf(close);
  if (end < 0) return null;
  const raw = rest.slice(0, end);
  if (!flowBareLabelOk(raw)) return null;
  return { text: raw.trim(), rest: rest.slice(end + close.length) };
}


function flowTypedParts(body) {
  const parts = [];
  let at = 0;
  let quoted = false;
  for (let i = 0; i < body.length; i += 1) {
    const char = body[i];
    if (char === '"') quoted = !quoted;
    else if (char === ',' && !quoted) {
      parts.push(body.slice(at, i));
      at = i + 1;
    }
  }
  parts.push(body.slice(at));
  return parts;
}


function takeFlowTyped(rest) {
  if (!rest.startsWith('@{')) return null;
  
  let close = -1;
  let quoted = false;
  for (let at = 2; at < rest.length; at += 1) {
    const char = rest[at];
    if (char === '"') quoted = !quoted;
    else if (char === '}' && !quoted) {
      close = at;
      break;
    }
  }
  if (close < 0) return null;
  const body = rest.slice(2, close);
  const typed = { shape: null, text: null, icon: null, img: null };
  for (const part of flowTypedParts(body)) {
    if (!part.trim()) continue;
    const at = part.indexOf(':');
    if (at < 0) return null;
    const key = part.slice(0, at).trim();
    let value = part.slice(at + 1).trim();
    const quoted = value.length >= 2 && value.startsWith('"') && value.endsWith('"');
    if (quoted) value = value.slice(1, -1);
    if (value.includes('"') || value.includes('`')) return null;
    if (key === 'shape') {
      const shape = FLOW_SHAPES_BY_NAME.get(value);
      if (!shape) return null;
      typed.shape = shape.id;
      continue;
    }
    if (key === 'label') {
      
      if (!quoted && !flowBareLabelOk(value) && value !== '') return null;
      typed.text = decodeFlowLabel(value);
      continue;
    }
    
    if (key === 'icon' || key === 'img') {
      if (!quoted && !flowBareLabelOk(value)) return null;
      typed[key] = value;
      continue;
    }
    return null;
  }
  return { typed, rest: rest.slice(close + 1) };
}


function takeFlowNode(rest) {
  const id = FLOW_ID_RE.exec(rest);
  if (!id) return null;
  const after = rest.slice(id[0].length);
  
  const withClass = (node, left) => {
    const marked = FLOW_NODE_CLASS_RE.exec(left);
    if (marked) node.className = marked[1];
    return { node, rest: marked ? left.slice(marked[0].length) : left };
  };
  if (after.startsWith('@{')) {
    const taken = takeFlowTyped(after);
    if (!taken) return null;
    return withClass(
      {
        id: id[0],
        shape: taken.typed.shape,
        text: taken.typed.text,
        icon: taken.typed.icon,
        img: taken.typed.img,
        typed: true,
      },
      taken.rest,
    );
  }
  for (const shape of FLOW_SHAPES_BY_OPENER) {
    if (!after.startsWith(shape.open)) continue;
    const label = takeFlowLabel(after.slice(shape.open.length), shape.close);
    if (!label) continue;
    return withClass({ id: id[0], shape: shape.id, text: label.text }, label.rest);
  }
  return withClass({ id: id[0], shape: null, text: null }, after);
}


function takeFlowNodeGroup(rest) {
  const nodes = [];
  let at = rest;
  for (;;) {
    const taken = takeFlowNode(at);
    if (!taken) return null;
    nodes.push(taken.node);
    at = taken.rest.replace(/^[ \t]+/, '');
    if (!at.startsWith('&')) return { nodes, rest: at };
    at = at.slice(1).replace(/^[ \t]+/, '');
  }
}


function takeFlowLink(rest) {
  
  let name = null;
  const named = FLOW_EDGE_NAME_RE.exec(rest);
  if (named) {
    name = named[1];
    rest = rest.slice(named[0].length);
  }
  const found = takeFlowConnector(rest);
  if (!found) return null;
  found.link.name = name;
  return found;
}

function takeFlowConnector(rest) {
  for (const form of FLOW_EDGE_LABELED) {
    const match = form.re.exec(rest);
    if (!match) continue;
    
    if (!/[^\s.]/.test(match[1])) continue;
    const label = flowLinkLabel(match[1]);
    if (label === false) return null;
    return { link: { label, line: form.line, ends: form.ends, stretch: 0 }, rest: rest.slice(match[0].length) };
  }
  for (const spelling of FLOW_EDGE_TOKENS) {
    const match = spelling.re.exec(rest);
    if (!match) continue;
    let after = rest.slice(match[0].length);
    let label = null;
    if (after.startsWith('|')) {
      const end = after.indexOf('|', 1);
      if (end < 0) return null;
      label = flowLinkLabel(after.slice(1, end));
      if (label === false) return null;
      after = after.slice(end + 1);
    }
    return {
      link: { label, line: spelling.line, ends: spelling.ends, stretch: match[1].length - spelling.least },
      rest: after,
    };
  }
  return null;
}


function flowLinkLabel(raw) {
  let label = String(raw).trim();
  if (label.length >= 2 && label.startsWith('"') && label.endsWith('"')) label = label.slice(1, -1);
  if (label.includes('"')) return false;
  return decodeFlowLabel(label) || null;
}


function parseFlowStatement(line) {
  let rest = line.trim();
  const declared = [];
  const links = [];
  let previous = null;
  let pending = null;
  for (;;) {
    const group = takeFlowNodeGroup(rest);
    if (!group) return null;
    for (const node of group.nodes) declared.push(node);
    if (previous) {
      for (const from of previous) {
        for (const node of group.nodes) {
          links.push({
            from,
            to: node.id,
            label: pending.label,
            line: pending.line,
            ends: pending.ends,
            stretch: pending.stretch,
            name: pending.name,
          });
        }
      }
    }
    previous = group.nodes.map((node) => node.id);
    rest = group.rest;
    if (!rest) return { declared, links };
    const link = takeFlowLink(rest);
    if (!link) return null;
    pending = link.link;
    rest = link.rest.replace(/^[ \t]+/, '');
  }
}


const FLOW_REFUSALS = [
  { re: /^click\b/, what: 'a click written a way we cannot read' },
  { re: /@\{[^}]*\b(?:w|h|pos|constraint)\b/, what: 'a typed box with a size or a place of its own' },
  { re: /@\{/, what: 'a shape name mermaid doesn’t have' },
  { re: /~~~/, what: 'an invisible line' },
  { re: /`/, what: 'a markdown label with no quotes around it' },
  { re: /;/, what: 'a semicolon between statements' },
  
  { re: /-{3,}[>ox]|-{4,}|={3,}[>ox]|={4,}|-\.{2,}/, what: 'a longer arrow' },
];

function flowFeatureIn(line) {
  const text = line.trim();
  if (flowQuoteLeftOpen(text)) return 'a label whose quote never closes';
  for (const probe of FLOW_REFUSALS) if (probe.re.test(text)) return probe.what;
  return '';
}


function flowLineRefusal(line, number, what) {
  const named = what || flowFeatureIn(line);
  return named
    ? 'Line ' + number + ' uses ' + named + ', which the canvas doesn’t model yet.'
    : 'Line ' + number + ' is more than the canvas models yet.';
}

function flowRefused(why) {
  return { graph: null, refusal: why };
}


function flowQuoteLeftOpen(text) {
  return (String(text).split('"').length - 1) % 2 === 1;
}


function flowIsAnimation(body) {
  const parts = flowTypedParts(body).filter((part) => part.trim());
  if (!parts.length) return false;
  return parts.every((part) => {
    const at = part.indexOf(':');
    return at > 0 && FLOW_ANIMATION_KEYS.includes(part.slice(0, at).trim());
  });
}


function flowGroupFromHeading(heading, parent) {
  const group = { id: '', text: '', direction: null, parent, classes: [], style: null };
  const titled = FLOW_SUBGRAPH_TITLED_RE.exec(heading);
  if (titled) {
    const label = takeFlowLabel(titled[2] + ']', ']');
    if (!label || label.rest) return null;
    group.id = titled[1];
    group.text = label.text;
    return group;
  }
  if (heading.startsWith('"')) {
    const label = takeFlowLabel(heading, '');
    if (!label || label.rest) return null;
    group.id = label.text;
    group.text = label.text;
    return group;
  }
  const id = FLOW_ID_RE.exec(heading);
  if (!id || id[0] !== heading) return null;
  group.id = heading;
  group.text = heading;
  return group;
}


function parseFlow(text) {
  return walkFlow(text).graph;
}


function flowRefusal(text) {
  return walkFlow(text).refusal;
}


function walkFlow(text) {
  if (typeof text !== 'string') return flowRefused('There is nothing here to read.');
  const lines = text.replace(/\r\n/g, '\n').split('\n');
  const prelude = [];
  let at = 0;
  if (lines.length && lines[0].trim() === '---') {
    let close = -1;
    for (let i = 1; i < lines.length; i += 1) {
      if (lines[i].trim() === '---') {
        close = i;
        break;
      }
    }
    if (close < 0) return flowRefused('The front matter above it never closes.');
    for (let i = 0; i <= close; i += 1) prelude.push(lines[i]);
    at = close + 1;
  }
  while (at < lines.length && (FLOW_COMMENT_RE.test(lines[at]) || !lines[at].trim())) {
    prelude.push(lines[at]);
    at += 1;
  }
  const header = FLOW_HEADER_RE.exec(at < lines.length ? lines[at] : '');
  if (!header) {
    
    const word = /^[A-Za-z0-9_-]+/.exec(at < lines.length ? lines[at].trim() : '');
    return flowRefused(
      word
        ? 'Only flowcharts open on the canvas, and this one starts with “' + word[0] + '”.'
        : 'This has no flowchart line to start it.',
    );
  }
  at += 1;
  const graph = {
    prelude,
    direction: (header[1] || 'TD').toUpperCase(),
    
    notes: [],
    
    classDefs: [],
    linkStyleDefault: null,
    
    deadClicks: [],
    
    groups: [],
    nodes: [],
    edges: [],
  };
  const byId = new Map();
  const byGroup = new Map();
  
  const open = [];
  const inside = () => (open.length ? open[open.length - 1] : null);
  
  const painting = [];
  for (; at < lines.length; at += 1) {
    
    const began = at;
    let line = lines[at];
    while (flowQuoteLeftOpen(line) && at + 1 < lines.length) {
      at += 1;
      line += '\n' + lines[at];
    }
    if (!line.trim()) continue;
    if (FLOW_COMMENT_RE.test(line) || FLOW_ACC_RE.test(line)) {
      graph.notes.push(line.trim());
      continue;
    }
    if (FLOW_CLASSDEF_RE.test(line)) {
      graph.classDefs.push(line.trim());
      continue;
    }
    const opened = FLOW_SUBGRAPH_RE.exec(line);
    if (opened) {
      const group = flowGroupFromHeading(opened[1], inside());
      if (!group) return flowRefused(flowLineRefusal(line, began + 1, 'a subgraph we can’t read the name of'));
      
      if (byGroup.has(group.id)) {
        return flowRefused(flowLineRefusal(line, began + 1, 'a name another subgraph already has'));
      }
      byGroup.set(group.id, group);
      graph.groups.push(group);
      open.push(group.id);
      continue;
    }
    if (FLOW_END_RE.test(line)) {
      if (!open.length) return flowRefused(flowLineRefusal(line, began + 1, 'an `end` with no subgraph above it'));
      open.pop();
      continue;
    }
    const turned = FLOW_DIRECTION_RE.exec(line);
    if (turned) {
      const group = byGroup.get(inside());
      
      if (!group) return flowRefused(flowLineRefusal(line, began + 1, 'a direction outside a subgraph'));
      group.direction = turned[1].toUpperCase();
      continue;
    }
    const named = FLOW_CLASS_RE.exec(line);
    if (named) {
      const ids = named[1]
        .split(',')
        .map((id) => id.trim())
        .filter(Boolean);
      painting.push({ kind: 'class', ids, name: named[2], line, number: began + 1 });
      continue;
    }
    const styled = FLOW_STYLE_RE.exec(line);
    if (styled) {
      painting.push({ kind: 'style', ids: [styled[1]], rule: styled[2], line, number: began + 1 });
      continue;
    }
    const linked = FLOW_LINKSTYLE_RE.exec(line);
    if (linked) {
      painting.push({ kind: 'linkStyle', which: linked[1], rule: linked[2], line, number: began + 1 });
      continue;
    }
    
    const clicked = FLOW_CLICK_RE.exec(line.trim());
    if (clicked) {
      painting.push({ kind: 'click', ids: [clicked[1]], href: clicked[2], tip: clicked[3] || null, line, number: began + 1 });
      continue;
    }
    if (FLOW_CLICK_CALL_RE.test(line.trim())) {
      graph.deadClicks.push(line.trim());
      continue;
    }
    const attributed = FLOW_EDGE_ATTR_RE.exec(line);
    if (attributed && flowIsAnimation(attributed[2])) {
      painting.push({ kind: 'animate', name: attributed[1], rule: attributed[2].trim(), line, number: began + 1 });
      continue;
    }
    const statement = parseFlowStatement(line);
    if (!statement) return flowRefused(flowLineRefusal(line, began + 1));
    for (const found of statement.declared) {
      let node = byId.get(found.id);
      if (!node) {
        
        node = {
          id: found.id,
          shape: FLOW_SHAPES[0].id,
          text: found.id,
          group: inside(),
          classes: [],
          style: null,
          icon: null,
          img: null,
          href: null,
          hrefTip: null,
          shapedBy: '',
        };
        byId.set(node.id, node);
        graph.nodes.push(node);
      } else if (!node.shapedBy && node.group === null && found.shape) {
        
        node.group = inside();
      }
      if (found.className && !node.classes.includes(found.className)) node.classes.push(found.className);
      if (found.typed) {
        
        if (found.shape) {
          if (node.shapedBy === 'typed') {
            return flowRefused(flowLineRefusal(line, began + 1, 'a box given a second shape'));
          }
          node.shapedBy = 'typed';
          node.shape = found.shape;
        }
        if (found.text != null) node.text = found.text;
        if (found.icon != null) node.icon = found.icon;
        if (found.img != null) node.img = found.img;
      } else if (found.shape) {
        
        if (node.shapedBy) return flowRefused(flowLineRefusal(line, began + 1, 'a box given a second shape'));
        node.shapedBy = 'bracket';
        node.shape = found.shape;
        node.text = found.text;
      }
    }
    for (const link of statement.links) {
      graph.edges.push({
        id: 'e' + (graph.edges.length + 1),
        from: link.from,
        to: link.to,
        label: link.label,
        line: link.line,
        ends: link.ends,
        stretch: link.stretch || 0,
        name: link.name || null,
        animate: null,
        style: null,
      });
    }
  }
  if (open.length) return flowRefused('A subgraph in it never ends.');
  
  for (const [id, node] of byId) {
    if (!byGroup.has(id)) continue;
    if (node.shapedBy || node.classes.length || node.style) {
      return flowRefused('“' + id + '” is a subgraph and a box at once.');
    }
    byId.delete(id);
    graph.nodes = graph.nodes.filter((other) => other !== node);
  }
  
  for (const item of painting) {
    if (item.kind === 'animate') {
      const edge = graph.edges.find((other) => other.name === item.name);
      if (!edge) return flowRefused(flowLineRefusal(item.line, item.number, 'a line no arrow is named after'));
      edge.animate = item.rule;
      continue;
    }
    if (item.kind === 'linkStyle') {
      if (item.which === 'default') {
        graph.linkStyleDefault = item.rule;
        continue;
      }
      for (const raw of item.which.split(',')) {
        const which = raw.trim();
        if (!which) continue;
        const edge = graph.edges[Number(which)];
        if (!edge) return flowRefused(flowLineRefusal(item.line, item.number, 'a style for a line that isn’t there'));
        edge.style = item.rule;
      }
      continue;
    }
    for (const id of item.ids) {
      
      const painted = byId.get(id) || byGroup.get(id);
      if (!painted) return flowRefused(flowLineRefusal(item.line, item.number, 'a box that isn’t there'));
      if (item.kind === 'style') painted.style = item.rule;
      else if (item.kind === 'click') {
        painted.href = item.href;
        painted.hrefTip = item.tip;
      } else if (!painted.classes.includes(item.name)) painted.classes.push(item.name);
    }
  }
  if (!graph.nodes.length) return flowRefused('There are no boxes in it yet.');
  for (const node of graph.nodes) delete node.shapedBy;
  return { graph, refusal: '' };
}


function flowNodeText(node) {
  const shape = flowShape(node.shape);
  const label = '"' + encodeFlowLabel(node.text) + '"';
  
  const extra = [];
  if (node.icon) extra.push('icon: "' + node.icon + '"');
  if (node.img) extra.push('img: "' + node.img + '"');
  if (!extra.length && shape.open) return node.id + shape.open + label + shape.close;
  return node.id + '@{ shape: ' + shape.id + ', label: ' + label + (extra.length ? ', ' + extra.join(', ') : '') + ' }';
}


function flowClickText(node) {
  const tip = node.hrefTip ? ' "' + node.hrefTip + '"' : '';
  return 'click ' + node.id + ' "' + node.href + '"' + tip;
}


function flowWriteGroups(graph, parent, depth, lines) {
  const pad = FLOW_INDENT.repeat(depth);
  for (const group of graph.groups || []) {
    if (group.parent !== parent) continue;
    lines.push(pad + 'subgraph ' + group.id + '["' + encodeFlowLabel(group.text) + '"]');
    if (group.direction) lines.push(pad + FLOW_INDENT + 'direction ' + group.direction);
    for (const node of graph.nodes) {
      if (node.group === group.id) lines.push(pad + FLOW_INDENT + flowNodeText(node));
    }
    flowWriteGroups(graph, group.id, depth + 1, lines);
    lines.push(pad + 'end');
  }
}


function renderFlow(graph) {
  if (!graph) return '';
  const lines = graph.prelude.slice();
  lines.push('flowchart ' + graph.direction);
  for (const note of graph.notes) lines.push(FLOW_INDENT + note);
  for (const raw of graph.classDefs || []) lines.push(FLOW_INDENT + raw);
  
  for (const node of graph.nodes) {
    if (!node.group) lines.push(FLOW_INDENT + flowNodeText(node));
  }
  flowWriteGroups(graph, null, 1, lines);
  for (const edge of graph.edges) {
    const token = flowEdgeToken(flowEdgeLine(edge.line), flowEdgeEnd(edge.ends), edge.stretch);
    const label = edge.label ? '|"' + encodeFlowLabel(edge.label) + '"|' : '';
    const name = edge.name ? edge.name + '@' : '';
    lines.push(FLOW_INDENT + edge.from + ' ' + name + token + label + ' ' + edge.to);
  }
  
  for (const edge of graph.edges) {
    if (edge.animate && edge.name) lines.push(FLOW_INDENT + edge.name + '@{ ' + edge.animate + ' }');
  }
  
  const wearing = new Map();
  const painted = graph.nodes.concat(graph.groups || []);
  for (const thing of painted) {
    for (const name of thing.classes || []) {
      if (!wearing.has(name)) wearing.set(name, []);
      wearing.get(name).push(thing.id);
    }
  }
  
  for (const name of [...wearing.keys()].sort()) {
    lines.push(FLOW_INDENT + 'class ' + wearing.get(name).join(',') + ' ' + name);
  }
  for (const thing of painted) {
    if (thing.style) lines.push(FLOW_INDENT + 'style ' + thing.id + ' ' + thing.style);
  }
  if (graph.linkStyleDefault) lines.push(FLOW_INDENT + 'linkStyle default ' + graph.linkStyleDefault);
  
  graph.edges.forEach((edge, index) => {
    if (edge.style) lines.push(FLOW_INDENT + 'linkStyle ' + index + ' ' + edge.style);
  });
  for (const node of graph.nodes) {
    if (node.href) lines.push(FLOW_INDENT + flowClickText(node));
  }
  for (const raw of graph.deadClicks || []) lines.push(FLOW_INDENT + raw);
  return lines.join('\n');
}




function flowNextId(graph, prefix) {
  const taken = new Set(graph.nodes.map((node) => node.id).concat(graph.edges.map((edge) => edge.id)));
  let n = 1;
  while (taken.has(prefix + n)) n += 1;
  return prefix + n;
}

function flowAddNode(graph, type, text) {
  const node = {
    id: flowNextId(graph, 'n'),
    shape: flowShape(type).id,
    text: text || 'Step',
    group: null,
    classes: [],
    style: null,
    icon: null,
    img: null,
    href: null,
    hrefTip: null,
  };
  graph.nodes.push(node);
  return node;
}

function flowFindNode(graph, id) {
  return graph.nodes.find((node) => node.id === id) || null;
}

function flowFindEdge(graph, id) {
  return graph.edges.find((edge) => edge.id === id) || null;
}

function flowFindGroup(graph, id) {
  return (graph.groups || []).find((group) => group.id === id) || null;
}




function flowNextGroupId(graph) {
  const taken = new Set(
    graph.nodes
      .map((node) => node.id)
      .concat((graph.groups || []).map((group) => group.id))
      .concat(graph.edges.map((edge) => edge.name).filter(Boolean)),
  );
  let n = 1;
  while (taken.has('g' + n)) n += 1;
  return 'g' + n;
}


function flowGroupNodes(graph, ids, text) {
  if (!graph.groups) graph.groups = [];
  const nodes = ids.map((id) => flowFindNode(graph, id)).filter(Boolean);
  if (!nodes.length) return null;
  const parents = new Set(nodes.map((node) => node.group));
  if (parents.size > 1) return null;
  const group = {
    id: flowNextGroupId(graph),
    text: text || 'Group',
    direction: null,
    parent: nodes[0].group,
    classes: [],
    style: null,
  };
  graph.groups.push(group);
  for (const node of nodes) node.group = group.id;
  return group;
}


function flowUngroup(graph, id) {
  const group = flowFindGroup(graph, id);
  if (!group) return;
  for (const node of graph.nodes) if (node.group === id) node.group = group.parent;
  for (const other of graph.groups) if (other.parent === id) other.parent = group.parent;
  graph.groups = graph.groups.filter((other) => other.id !== id);
  
  graph.edges = graph.edges.filter((edge) => edge.from !== id && edge.to !== id);
}


function flowMoveNodeToGroup(graph, id, groupId) {
  const node = flowFindNode(graph, id);
  if (!node) return;
  if (groupId !== null && !flowFindGroup(graph, groupId)) return;
  node.group = groupId;
}


function flowConnect(graph, from, to) {
  if (!flowFindNode(graph, from) || !flowFindNode(graph, to)) return null;
  const existing = graph.edges.find((edge) => edge.from === from && edge.to === to);
  if (existing) return existing;
  const edge = {
    id: flowNextId(graph, 'e'),
    from,
    to,
    label: null,
    line: 'solid',
    ends: 'arrow',
    stretch: 0,
    name: null,
    animate: null,
    style: null,
  };
  graph.edges.push(edge);
  return edge;
}


function flowSpliceIntoEdge(graph, id, edgeId) {
  const edge = flowFindEdge(graph, edgeId);
  if (!edge || !flowFindNode(graph, id)) return null;
  if (edge.from === id || edge.to === id) return null;
  const rest = {
    id: flowNextId(graph, 'e'),
    from: id,
    to: edge.to,
    label: null,
    line: edge.line,
    ends: edge.ends,
    stretch: edge.stretch,
    name: null,
    animate: null,
    style: edge.style,
  };
  edge.to = id;
  graph.edges.splice(graph.edges.indexOf(edge) + 1, 0, rest);
  return rest;
}


function flowDetachNode(graph, id) {
  graph.edges = graph.edges.filter((edge) => edge.from !== id && edge.to !== id);
}


function flowExtractNode(graph, id) {
  const incoming = graph.edges.filter((edge) => edge.to === id && edge.from !== id);
  const outgoing = graph.edges.filter((edge) => edge.from === id && edge.to !== id);
  for (const into of incoming) {
    for (const out of outgoing) {
      if (into.from !== out.to) flowConnect(graph, into.from, out.to);
    }
  }
  flowDetachNode(graph, id);
}


function flowDuplicateNode(graph, id) {
  const node = flowFindNode(graph, id);
  if (!node) return null;
  const copy = {
    id: flowNextId(graph, 'n'),
    shape: node.shape,
    text: node.text,
    group: node.group,
    classes: (node.classes || []).slice(),
    style: node.style,
  };
  graph.nodes.splice(graph.nodes.indexOf(node) + 1, 0, copy);
  return copy;
}


function flowFlipEdge(graph, id) {
  const edge = flowFindEdge(graph, id);
  if (!edge) return;
  const from = edge.from;
  edge.from = edge.to;
  edge.to = from;
}

function flowDeleteNode(graph, id) {
  graph.nodes = graph.nodes.filter((node) => node.id !== id);
  graph.edges = graph.edges.filter((edge) => edge.from !== id && edge.to !== id);
}

function flowDeleteEdge(graph, id) {
  graph.edges = graph.edges.filter((edge) => edge.id !== id);
}


function flowMoveNode(graph, id, beforeId) {
  const from = graph.nodes.findIndex((node) => node.id === id);
  if (from < 0) return;
  const [node] = graph.nodes.splice(from, 1);
  const at = beforeId == null ? graph.nodes.length : graph.nodes.findIndex((other) => other.id === beforeId);
  graph.nodes.splice(at < 0 ? graph.nodes.length : at, 0, node);
}








const flowBackdrop = document.getElementById('flowBackdrop');
const flowSheet = document.getElementById('flowSheet');
const flowSheetTitle = document.getElementById('flowSheetTitle');
const flowSheetCancel = document.getElementById('flowSheetCancel');
const flowSheetSave = document.getElementById('flowSheetSave');
const flowSheetExport = document.getElementById('flowSheetExport');
const flowUndoButton = document.getElementById('flowUndo');
const flowRedoButton = document.getElementById('flowRedo');
const flowDirectionPicker = document.getElementById('flowDirection');
const flowHint = document.getElementById('flowHint');
const flowCanvas = document.getElementById('flowCanvas');
const flowZoomIn = document.getElementById('flowZoomIn');
const flowZoomOut = document.getElementById('flowZoomOut');
const flowZoomFit = document.getElementById('flowZoomFit');
const flowSplit = document.getElementById('flowSplit');
const flowPicker = document.getElementById('flowPicker');
const flowPickerHead = document.getElementById('flowPickerHead');
const flowPickerBody = document.getElementById('flowPickerBody');
const flowPickerClose = document.getElementById('flowPickerClose');
const flowPickerBackdrop = document.getElementById('flowPickerBackdrop');
const flowNotice = document.getElementById('flowNotice');
const flowCode = document.getElementById('flowCode');


let flowSession = null;
let flowCodeTimer = 0;

let flowDrawTimer = 0;
let flowDrawError = '';

let flowLostBoxes = false;
let flowLastFocus = null;

let flowSize = null;
let flowZoom = 1;
let flowPlaced = null;


let flowNatural = null;

const flowHistory = { past: [], future: [] };
let flowBefore = null;
const FLOW_HISTORY_CAP = 100;


const FLOW_UNMODELED = 'The canvas can’t model this diagram yet.';
const FLOW_AS_TEXT = ' Edit it as text below; the picture follows what you type.';
const FLOW_LOST_BOXES = 'Drawn, but the canvas can’t find its boxes to put handles on — edit it as text below.';
const FLOW_NOTHING_YET = 'Nothing here yet. Double-click anywhere to add the first box.';

const FLOW_TIP_IDLE =
  'Double-click empty space to add a box · point at a box for the + handles that add the next one · double-click a box to rename it · right-click anything for more.';

const FLOW_TIP_NODE =
  'Its + handles add the step before or after it · drag it onto a line to put it in that line · right-click to put it in a group · Delete removes it.';

const FLOW_TIP_FIRST = 'Its four + handles start the chart running that way. After that, Flow up top turns it.';
const FLOW_TIP_EDGE = 'Drag either end onto another box to reconnect it · Delete removes it.';

const FLOW_SAVE_REWRITES = 'Save rewrites the whole block: one box to a line, every label quoted.';

const FLOW_SAVE_GONE =
  'The document changed underneath this diagram, so there is nowhere left to save it. Copy the text below before closing.';

const FLOW_TIP_PREVIEW = 'Drag to move the picture · Ctrl-scroll to zoom · type below to change it.';

const FLOW_TIP_MOVING =
  'Drop on a line to put this box in it · on another box to move it beside that one · in a group to join it, outside to leave it.';
const FLOW_TIP_BUD = 'Let go on empty space for a new box · on another box to connect to it.';




let flowSaveWaiting = null;


function insertEditToken(option) {
  return option && option.answered ? nextEditToken() : undefined;
}


function dropFlowSaveWait() {
  if (flowSaveWaiting !== null) leafDropEditWait(flowSaveWaiting);
  flowSaveWaiting = null;
}


function onFlowSaveAnswered(held, why) {
  flowSaveWaiting = null;
  if (held) {
    closeFlowSheet();
    return;
  }
  leafToast(why || FLOW_SAVE_GONE, 'error');
}


function openFlowSheet({ title, text, save }) {
  if (!flowSheet || !flowBackdrop) return;
  
  suspendHintForSheet(flowSheet);
  dropFlowSaveWait();
  flowLastFocus = document.activeElement;
  flowSession = { save, text: typeof text === 'string' ? text : '', graph: null };
  flowSelection = null;
  flowDrawn = null;
  
  flowLastDrawCost = 0;
  flowZoom = 1;
  if (flowSheetTitle) flowSheetTitle.textContent = title || 'Flowchart';
  readyFlowPicker();
  buildFlowControls();
  loadFlowChips();
  flowHistory.past.length = 0;
  flowHistory.future.length = 0;
  flowBefore = null;
  setFlowText(flowSession.text, 'open');
  flowBackdrop.hidden = false;
  flowSheet.hidden = false;
  requestAnimationFrame(() => {
    flowBackdrop.classList.add('open');
    flowSheet.classList.add('open');
    
    fitFlowCanvas();
    centerFlowCanvas();
  });
  document.addEventListener('keydown', onFlowSheetKey);
  if (flowCanvas) flowCanvas.focus({ preventScroll: true });
}

function closeFlowSheet() {
  if (!flowSession) return;
  dropFlowSaveWait();
  closeFlowMenu();
  closeFlowLabelBox(false);
  flowSession = null;
  flowSelection = null;
  flowDrawn = null;
  flowDrag = null;
  
  flowPickerAdd = null;
  flowPickerName = '';
  if (flowPicker) {
    
    cancelSheetLegs(flowPicker);
    dropSheetMotion(flowPicker);
    flowPicker.classList.remove('open');
    flowPicker.hidden = true;
  }
  window.clearTimeout(flowCodeTimer);
  window.clearTimeout(flowDrawTimer);
  document.removeEventListener('keydown', onFlowSheetKey);
  flowBackdrop.classList.remove('open');
  flowSheet.classList.remove('open');
  const hide = () => {
    flowSheet.hidden = true;
    flowBackdrop.hidden = true;
    flowSheet.removeEventListener('transitionend', hide);
    
    restoreHintAfterSheet(flowSheet);
  };
  flowSheet.addEventListener('transitionend', hide);
  window.setTimeout(hide, 320);
  leafFocusForKeyboard(flowLastFocus);
}

function saveFlowSheet() {
  if (!flowSession) return;
  closeFlowLabelBox(true);
  
  flushFlowCode();
  if (flowSheetSave && flowSheetSave.disabled) return;
  const save = flowSession.save;
  const text = flowSession.text;
  
  const answer = typeof save === 'function' ? save(text) : undefined;
  if (answer === false) {
    leafToast(FLOW_SAVE_GONE, 'error');
    return;
  }
  
  if (typeof answer === 'number') {
    flowSaveWaiting = leafHoldEdit(answer, onFlowSaveAnswered);
    return;
  }
  closeFlowSheet();
}


function onFlowSheetKey(event) {
  if (!flowSession) return;
  if (event.key === 'Escape') {
    event.preventDefault();
    
    if (flowMenu) {
      closeFlowMenu();
      return;
    }
    if (flowPickerAdd) {
      closeFlowAddPicker();
      return;
    }
    closeFlowSheet();
    return;
  }
  
  const inField = document.activeElement && /^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement.tagName);
  if (inField) return;
  const key = String(event.key).toLowerCase();
  if ((event.ctrlKey || event.metaKey) && (key === 'z' || key === 'y')) {
    event.preventDefault();
    if (key === 'y' || event.shiftKey) redoFlow();
    else undoFlow();
    return;
  }
  if (!flowSelection || !flowSession.graph) return;
  if (event.key === 'Delete' || event.key === 'Backspace') {
    event.preventDefault();
    deleteFlowSelection();
    return;
  }
  
  if (event.key === 'Enter') {
    event.preventDefault();
    openFlowLabelBox(flowSelection.kind, flowSelection.id);
  }
}




function setFlowText(text, from) {
  if (!flowSession) return;
  if (from === 'code') recordFlowStep();
  flowSession.text = text;
  flowSession.graph = parseFlow(text);
  if (flowSelection && !flowSelectionStillThere()) flowSelection = null;
  if (from !== 'code' && flowCode) flowCode.value = text;
  redrawFlowSheet();
  flowBefore = flowSnapshot();
}


function flowGraphChanged() {
  if (!flowSession || !flowSession.graph) return;
  recordFlowStep();
  flowSession.text = renderFlow(flowSession.graph);
  if (flowCode) flowCode.value = flowSession.text;
  if (flowSelection && !flowSelectionStillThere()) flowSelection = null;
  redrawFlowSheet();
  flowBefore = flowSnapshot();
}





function flowSnapshot() {
  if (!flowSession) return null;
  return {
    text: flowSession.text,
    graph: flowSession.graph ? JSON.parse(JSON.stringify(flowSession.graph)) : null,
    selection: flowSelection ? { kind: flowSelection.kind, id: flowSelection.id } : null,
  };
}

function recordFlowStep() {
  if (!flowBefore) return;
  flowHistory.past.push(flowBefore);
  if (flowHistory.past.length > FLOW_HISTORY_CAP) flowHistory.past.shift();
  flowHistory.future.length = 0;
}

function applyFlowState(state) {
  if (!state || !flowSession) return;
  closeFlowLabelBox(false);
  flowSession.text = state.text;
  flowSession.graph = state.graph ? JSON.parse(JSON.stringify(state.graph)) : null;
  flowSelection = state.selection ? { kind: state.selection.kind, id: state.selection.id } : null;
  if (flowCode) flowCode.value = state.text;
  redrawFlowSheet();
  flowBefore = flowSnapshot();
}

function undoFlow() {
  if (!flowSession || !flowHistory.past.length) return;
  const now = flowSnapshot();
  const back = flowHistory.past.pop();
  applyFlowState(back);
  flowHistory.future.push(now);
  updateFlowHistoryButtons();
}

function redoFlow() {
  if (!flowSession || !flowHistory.future.length) return;
  const now = flowSnapshot();
  const forward = flowHistory.future.pop();
  applyFlowState(forward);
  flowHistory.past.push(now);
  updateFlowHistoryButtons();
}

function updateFlowHistoryButtons() {
  if (flowUndoButton) flowUndoButton.disabled = !flowHistory.past.length;
  if (flowRedoButton) flowRedoButton.disabled = !flowHistory.future.length;
}

if (flowUndoButton) flowUndoButton.addEventListener('click', undoFlow);
if (flowRedoButton) flowRedoButton.addEventListener('click', redoFlow);


function updateFlowSaveState() {
  const graph = flowSession && flowSession.graph;
  const empty = !!graph && !graph.nodes.length;
  if (flowSheetSave) {
    flowSheetSave.disabled = empty;
    flowSheetSave.title = empty ? 'Add a box before saving' : FLOW_SAVE_REWRITES;
  }
  if (flowSheetExport) {
    flowSheetExport.disabled = empty;
    flowSheetExport.title = empty ? 'Add a box before exporting' : 'Save this diagram as its own file';
  }
}

function flowSelectionStillThere() {
  const graph = flowSession && flowSession.graph;
  if (!graph || !flowSelection) return false;
  if (flowSelection.kind === 'node') return !!flowFindNode(graph, flowSelection.id);
  if (flowSelection.kind === 'group') return !!flowFindGroup(graph, flowSelection.id);
  return !!flowFindEdge(graph, flowSelection.id);
}


function flushFlowCode() {
  window.clearTimeout(flowCodeTimer);
  if (!flowSession || !flowCode || flowCode.value === flowSession.text) return;
  setFlowText(flowCode.value, 'code');
}

if (flowCode) {
  flowCode.addEventListener('input', () => {
    if (!flowSession) return;
    window.clearTimeout(flowCodeTimer);
    flowCodeTimer = window.setTimeout(() => setFlowText(flowCode.value, 'code'), 180);
  });
  flowCode.addEventListener('blur', flushFlowCode);
}
if (flowSheetCancel) flowSheetCancel.addEventListener('click', closeFlowSheet);
if (flowSheetSave) flowSheetSave.addEventListener('click', saveFlowSheet);
if (flowBackdrop) flowBackdrop.addEventListener('click', closeFlowSheet);




function setFlowHint(text) {
  if (flowHint) flowHint.textContent = text;
}

function restoreFlowHint() {
  const graph = flowSession && flowSession.graph;
  
  if (!graph) {
    setFlowHint(FLOW_TIP_PREVIEW);
    return;
  }
  if (!flowSelection) {
    setFlowHint(FLOW_TIP_IDLE);
    return;
  }
  if (flowSelection.kind === 'edge') {
    setFlowHint(FLOW_TIP_EDGE);
    return;
  }
  setFlowHint(flowNodeTip(graph, flowSelection.id) || FLOW_TIP_IDLE);
}


function flowNodeTip(graph, id) {
  const node = flowFindNode(graph, id);
  const shape = node && flowShape(node.shape);
  if (!shape) return null;
  const tip = graph.nodes.length <= 1 ? FLOW_TIP_FIRST : FLOW_TIP_NODE;
  return shape.label + ' — ' + shape.hint + ' ' + tip;
}




const FLOW_CHIP_W = 42;
const FLOW_CHIP_H = 26;



function flowEndChipGlyph(mark, x, y, facing) {
  if (!mark) return '';
  if (mark === 'arrow') {
    const back = x - 6 * facing;
    return '<path class="flow-end-mark" d="M' + back + ' ' + (y - 4) + ' L' + x + ' ' + y + ' L' + back + ' ' + (y + 4) + ' Z"/>';
  }
  if (mark === 'circle') return '<circle class="flow-end-mark" cx="' + x + '" cy="' + y + '" r="3.5"/>';
  return (
    '<path class="flow-end-mark is-open" d="M' + (x - 3) + ' ' + (y - 3) + ' L' + (x + 3) + ' ' + (y + 3) +
    ' M' + (x + 3) + ' ' + (y - 3) + ' L' + (x - 3) + ' ' + (y + 3) + '"/>'
  );
}


function flowEdgeChip(lineId, endId) {
  const ends = flowEdgeEnd(endId);
  const y = FLOW_CHIP_H / 2;
  return (
    '<svg class="flow-chip" viewBox="0 0 ' + FLOW_CHIP_W + ' ' + FLOW_CHIP_H + '" aria-hidden="true">' +
    '<line class="flow-chip-line is-' + flowEdgeLine(lineId).id + '" x1="7" y1="' + y + '" x2="' + (FLOW_CHIP_W - 7) + '" y2="' + y + '"/>' +
    flowEndChipGlyph(flowEndMark(ends.head), 7, y, -1) +
    flowEndChipGlyph(flowEndMark(ends.tail), FLOW_CHIP_W - 7, y, 1) +
    '</svg>'
  );
}

function buildFlowControls() {
  if (flowDirectionPicker && !flowDirectionPicker.childElementCount) {
    for (const direction of FLOW_DIRECTIONS) {
      const option = document.createElement('option');
      option.value = direction.id;
      option.textContent = direction.label;
      flowDirectionPicker.appendChild(option);
    }
    flowDirectionPicker.addEventListener('change', () => {
      if (!flowSession || !flowSession.graph) return;
      flowSession.graph.direction = flowDirectionPicker.value;
      flowGraphChanged();
    });
  }
}


function addFlowNode(shapeId, options) {
  const graph = flowSession && flowSession.graph;
  if (!graph) return null;
  const { before, connectFrom, connectTo, turn, intoEdge, text } = options || {};
  
  if (turn) graph.direction = turn;
  
  const named = (text || '').trim();
  const node = flowAddNode(graph, shapeId, named || flowShape(shapeId).label);
  if (before !== undefined) flowMoveNode(graph, node.id, before);
  if (connectFrom) flowConnect(graph, connectFrom, node.id);
  if (connectTo) flowConnect(graph, node.id, connectTo);
  if (intoEdge) flowSpliceIntoEdge(graph, node.id, intoEdge);
  flowSelection = { kind: 'node', id: node.id };
  flowGraphChanged();
  
  if (!named) openFlowLabelBox('node', node.id);
  return node;
}


function flowSlotAt(point) {
  const graph = flowSession && flowSession.graph;
  if (!graph || !flowPlaced || !flowPlaced.nodes.length) return undefined;
  let best = null;
  let nearest = Infinity;
  for (const node of flowPlaced.nodes) {
    const dx = point.x - (node.x + node.width / 2);
    const dy = point.y - (node.y + node.height / 2);
    const away = dx * dx + dy * dy;
    if (away < nearest) {
      nearest = away;
      best = node;
    }
  }
  if (!best) return undefined;
  const ids = graph.nodes.map((node) => node.id);
  const at = ids.indexOf(best.id);
  const horizontal = graph.direction === 'LR' || graph.direction === 'RL';
  const past = horizontal ? point.x > best.x + best.width / 2 : point.y > best.y + best.height / 2;
  return past ? ids[at + 1] || null : best.id;
}













const FLOW_BUD_SIDES = ['up', 'down', 'left', 'right'];
const FLOW_BUD_WORDS = { up: 'above', down: 'below', left: 'to the left', right: 'to the right' };

const FLOW_DIRECTION_WAY = { TD: 'down', TB: 'down', BT: 'up', LR: 'right', RL: 'left' };
const FLOW_WAY_DIRECTION = { down: 'TD', up: 'BT', right: 'LR', left: 'RL' };
const FLOW_OPPOSITE_WAY = { up: 'down', down: 'up', left: 'right', right: 'left' };



function flowBudIntent(direction, side) {
  const way = FLOW_DIRECTION_WAY[direction] || 'down';
  if (side === way) return { step: 'next' };
  if (side === FLOW_OPPOSITE_WAY[way]) return { step: 'previous' };
  return { step: 'next', turn: FLOW_WAY_DIRECTION[side] };
}

function flowBudTitle(direction, side) {
  const intent = flowBudIntent(direction, side);
  if (intent.step === 'previous') return 'Add the step before this';
  if (!intent.turn) return 'Add the next step';
  return 'Start the chart running ' + FLOW_BUD_WORDS[side];
}


function flowBudSidesFor(graph) {
  if (graph.nodes.length <= 1) return FLOW_BUD_SIDES;
  const way = FLOW_DIRECTION_WAY[graph.direction] || 'down';
  return [way, FLOW_OPPOSITE_WAY[way]];
}



function flowBudRelation(graph, id, side) {
  const intent = flowBudIntent(graph.direction, side);
  const relation = intent.step === 'previous' ? { connectTo: id } : { connectFrom: id };
  if (intent.turn) relation.turn = intent.turn;
  return relation;
}






const FLOW_ZOOM_MIN = 0.25;
const FLOW_ZOOM_MAX = 2.5;

function setFlowZoom(next) {
  const clamped = Math.max(FLOW_ZOOM_MIN, Math.min(FLOW_ZOOM_MAX, next));
  if (Math.abs(clamped - flowZoom) < 0.001) return;
  closeFlowLabelBox(true);
  flowZoom = clamped;
  
  sizeFlowStage();
  placeFlowDiagram();
  placeFlowOverlay();
}


function fitFlowCanvas() {
  if (!flowCanvas || !flowSize) return;
  setFlowPan(0, 0);
  const room = flowCanvas.clientWidth - 24;
  const tall = flowCanvas.clientHeight - 24;
  if (room <= 0 || tall <= 0) return;
  setFlowZoom(Math.min(1, room / flowSize.width, tall / flowSize.height));
}


const flowPan = { x: 0, y: 0 };

function setFlowPan(x, y) {
  flowPan.x = x;
  flowPan.y = y;
  if (!flowCanvas) return;
  flowCanvas.style.setProperty('--flow-pan-x', Math.round(x) + 'px');
  flowCanvas.style.setProperty('--flow-pan-y', Math.round(y) + 'px');
}


function centerFlowCanvas() {
  if (!flowCanvas) return;
  setFlowPan(0, 0);
  flowCanvas.scrollLeft = Math.max(0, (flowCanvas.scrollWidth - flowCanvas.clientWidth) / 2);
  flowCanvas.scrollTop = Math.max(0, (flowCanvas.scrollHeight - flowCanvas.clientHeight) / 2);
}




const FLOW_CODE_MIN = 180;


function flowRoom() {
  const room = (flowSheet && flowSheet.clientWidth) || 900;
  const floor = flowSheet
    ? parseFloat(getComputedStyle(flowSheet).getPropertyValue('--flow-picture-floor'))
    : NaN;
  return { room, floor };
}


function setFlowCodeWidth(pixels, held) {
  if (!flowSheet) return;
  const { room, floor } = held || flowRoom();
  const ceiling = Number.isFinite(floor) ? room - floor : Infinity;
  const width = Math.round(Math.max(FLOW_CODE_MIN, Math.min(ceiling, pixels)));
  flowSheet.style.setProperty('--flow-code-width', width + 'px');
}

function flowCodeWidth() {
  return flowCode ? flowCode.getBoundingClientRect().width : 340;
}

if (flowSplit) {
  flowSplit.addEventListener('pointerdown', (event) => {
    if (event.button !== 0) return;
    event.preventDefault();
    const start = event.clientX;
    const was = flowCodeWidth();
    
    const held = flowRoom();
    const move = (moved) => setFlowCodeWidth(was - (moved.clientX - start), held);
    const done = () => {
      document.removeEventListener('pointermove', move);
      document.removeEventListener('pointerup', done);
    };
    document.addEventListener('pointermove', move);
    document.addEventListener('pointerup', done);
  });
  flowSplit.addEventListener('keydown', (event) => {
    if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return;
    event.preventDefault();
    setFlowCodeWidth(flowCodeWidth() + (event.key === 'ArrowLeft' ? 24 : -24));
  });
  flowSplit.addEventListener('dblclick', () => setFlowCodeWidth(340));
}

if (flowZoomIn) flowZoomIn.addEventListener('click', () => setFlowZoom(flowZoom * 1.2));
if (flowZoomOut) flowZoomOut.addEventListener('click', () => setFlowZoom(flowZoom / 1.2));
if (flowZoomFit) flowZoomFit.addEventListener('click', fitFlowCanvas);
if (flowCanvas) {
  flowCanvas.addEventListener(
    'wheel',
    (event) => {
      if (!event.ctrlKey || !flowSession) return;
      event.preventDefault();
      setFlowZoom(flowZoom * (event.deltaY < 0 ? 1.1 : 1 / 1.1));
    },
    { passive: false },
  );
}








function flowEdgeDomId(from, to, nth) {
  return 'L_' + from + '_' + to + '_' + nth;
}


function flowEdgePathIn(svg, edge, nth) {
  const named = (name) =>
    svg.querySelector('path[data-id="' + name + '"]') || svg.querySelector('path[id="' + name + '"]');
  const straight = named(flowEdgeDomId(edge.from, edge.to, nth));
  if (straight || edge.from !== edge.to) return straight;
  return named(edge.from + '-cyclic-special-mid') || named(edge.from + '-cyclic-special-1');
}


function flowNodeIdFromDom(raw, known) {
  if (!raw) return null;
  if (known.has(raw)) return raw;
  const stripped = /^flowchart-(.+)-\d+$/.exec(raw);
  return stripped && known.has(stripped[1]) ? stripped[1] : null;
}

let flowRenderSeq = 0;

let flowDiagramThemeVersion = 0;

const FLOW_DRAW_FLOOR = 120;
let flowLastDrawCost = 0;

let flowDrawn = null;

const FLOW_DRAWING_STORE_CAP = 4 * 1024 * 1024;
const flowDrawingStore = new Map();
let flowDrawingStoreHeld = 0;

const flowDrawingKey = (text, themeVersion) => themeVersion + '\n' + text;


const flowDrawIsComing = (text, themeVersion) =>
  !(flowDrawn && flowDrawn.text === text && flowDrawn.themeVersion === themeVersion)
  && !flowDrawingStore.has(flowDrawingKey(text, themeVersion));

function keepFlowDrawing(text, themeVersion, svg) {
  const key = flowDrawingKey(text, themeVersion);
  
  if (flowDrawingStore.has(key) || svg.length > FLOW_DRAWING_STORE_CAP) return;
  flowDrawingStore.set(key, svg);
  flowDrawingStoreHeld += svg.length;
  
  while (flowDrawingStoreHeld > FLOW_DRAWING_STORE_CAP) {
    const [oldest, drawing] = flowDrawingStore.entries().next().value;
    flowDrawingStore.delete(oldest);
    flowDrawingStoreHeld -= drawing.length;
  }
}


function paintFlowDrawing(svg, text, themeVersion) {
  const left = flowCanvas.scrollLeft;
  const top = flowCanvas.scrollTop;
  flowCanvas.innerHTML = '<div class="flow-stage">' + svg + '<div class="flow-overlay"></div></div>';
  flowDrawn = { text, themeVersion };
  sizeFlowStage();
  measureFlowDiagram();
  drawFlowOverlay();
  flowCanvas.scrollLeft = left;
  flowCanvas.scrollTop = top;
  drawFlowNotice();
}

function redrawFlowSheet() {
  drawFlowNotice();
  queueFlowDiagram();
  drawFlowOverlay();
  drawFlowPicker();
  updateFlowSaveState();
  updateFlowHistoryButtons();
}

function drawFlowNotice() {
  if (!flowNotice) return;
  const graph = flowSession && flowSession.graph;
  
  const problem = flowDrawError || (graph && flowLostBoxes ? FLOW_LOST_BOXES : '');
  const message = !graph
    ? problem || (flowRefusal(flowSession ? flowSession.text : '') || FLOW_UNMODELED) + FLOW_AS_TEXT
    : !graph.nodes.length
      ? FLOW_NOTHING_YET
      : problem;
  flowNotice.hidden = !message;
  flowNotice.textContent = message || '';
  flowNotice.classList.toggle('is-error', !!problem);
  if (flowCanvas) flowCanvas.classList.toggle('is-disabled', !graph);
  if (flowDirectionPicker) {
    flowDirectionPicker.disabled = !graph;
    if (graph) flowDirectionPicker.value = graph.direction === 'TB' ? 'TD' : graph.direction;
  }
  restoreFlowHint();
}


function queueFlowDiagram() {
  window.clearTimeout(flowDrawTimer);
  
  const coming = !flowSession || flowDrawIsComing(flowSession.text, flowDiagramThemeVersion);
  flowDrawTimer = window.setTimeout(drawFlowDiagram, coming ? Math.max(FLOW_DRAW_FLOOR, flowLastDrawCost) : FLOW_DRAW_FLOOR);
}

function drawFlowDiagram() {
  if (!flowSession || !flowCanvas) return;
  const graph = flowSession.graph;
  const text = flowSession.text;
  const attempt = (flowRenderSeq += 1);
  const themeVersion = flowDiagramThemeVersion;
  
  if ((graph && !graph.nodes.length) || !text.trim()) {
    flowCanvas.innerHTML = '';
    flowDrawn = null;
    flowPlaced = null;
    flowNatural = null;
    flowSize = null;
    flowDrawError = '';
    drawFlowNotice();
    return;
  }
  
  if (flowDrawn && flowDrawn.text === text && flowDrawn.themeVersion === themeVersion) return;
  const kept = flowDrawingStore.get(flowDrawingKey(text, themeVersion));
  if (kept) {
    flowDrawError = '';
    paintFlowDrawing(kept, text, themeVersion);
    return;
  }
  loadMermaid()
    .then(async (mermaid) => {
      mermaid.initialize(mermaidRuntimeConfig());
      const started = performance.now();
      const { svg } = await mermaid.render('leafFlowDraw' + attempt, text);
      
      flowLastDrawCost = performance.now() - started;
      if (!flowSession || attempt !== flowRenderSeq || themeVersion !== flowDiagramThemeVersion) return;
      flowDrawError = '';
      keepFlowDrawing(text, themeVersion, svg);
      paintFlowDrawing(svg, text, themeVersion);
    })
    .catch((error) => {
      if (!flowSession || attempt !== flowRenderSeq || themeVersion !== flowDiagramThemeVersion) return;
      
      const orphan = document.getElementById('dleafFlowDraw' + attempt);
      if (orphan && orphan.remove && outsideEveryReader(orphan)) orphan.remove();
      flowDrawError = (error && error.message) || 'This diagram cannot be drawn.';
      drawFlowNotice();
    });
}


function sizeFlowStage() {
  const stage = flowCanvas && flowCanvas.querySelector('.flow-stage');
  const svg = stage && stage.querySelector('svg');
  if (!svg) return;
  const box = (svg.getAttribute('viewBox') || '').split(/[\s,]+/).map(Number);
  const natural = box.length === 4 && box[2] > 0 ? { width: box[2], height: box[3] } : null;
  if (natural) flowSize = natural;
  if (!flowSize) return;
  const width = Math.max(1, Math.round(flowSize.width * flowZoom));
  const height = Math.max(1, Math.round(flowSize.height * flowZoom));
  svg.setAttribute('width', width);
  svg.setAttribute('height', height);
  svg.style.maxWidth = 'none';
  stage.style.width = width + 'px';
  stage.style.height = height + 'px';
}


function flowDrawEdgeTarget(path, id) {
  const copy = path.cloneNode(false);
  copy.removeAttribute('id');
  copy.removeAttribute('data-id');
  
  copy.removeAttribute('style');
  copy.removeAttribute('marker-end');
  copy.removeAttribute('marker-start');
  copy.setAttribute('class', 'flow-edge-hit');
  copy.setAttribute('data-flow-hit', id);
  if (path.parentElement) path.parentElement.appendChild(copy);
}

function measureFlowDiagram() {
  const graph = flowSession && flowSession.graph;
  const stage = flowCanvas && flowCanvas.querySelector('.flow-stage');
  const svg = stage && stage.querySelector('svg');
  if (!graph || !svg) {
    flowNatural = null;
    flowPlaced = null;
    return;
  }
  const origin = stage.getBoundingClientRect();
  
  const shown = flowZoom;
  const known = new Set(graph.nodes.map((node) => node.id));
  const nodes = [];
  
  svg.querySelectorAll('g.node, g[data-id]').forEach((group) => {
    const id = flowNodeIdFromDom(group.id, known) || flowNodeIdFromDom(group.dataset.id, known);
    if (!id) return;
    const rect = group.getBoundingClientRect();
    if (!rect.width && !rect.height) return;
    nodes.push({
      id,
      x: (rect.left - origin.left) / shown,
      y: (rect.top - origin.top) / shown,
      width: rect.width / shown,
      height: rect.height / shown,
      radius: flowDrawnRadius(group, rect.width / shown, rect.height / shown),
    });
  });
  
  const groups = [];
  const knownGroups = new Set((graph.groups || []).map((group) => group.id));
  svg.querySelectorAll('g.cluster').forEach((drawn) => {
    const id = flowNodeIdFromDom(drawn.id, knownGroups) || flowNodeIdFromDom(drawn.dataset.id, knownGroups);
    if (!id) return;
    const rect = drawn.getBoundingClientRect();
    if (!rect.width && !rect.height) return;
    groups.push({
      id,
      x: (rect.left - origin.left) / shown,
      y: (rect.top - origin.top) / shown,
      width: rect.width / shown,
      height: rect.height / shown,
    });
  });
  const edges = [];
  const seen = new Map();
  
  svg.querySelectorAll('path[data-flow-hit]').forEach((stale) => stale.remove());
  
  for (const edge of graph.edges) {
    const pair = edge.from + '_' + edge.to;
    const nth = seen.get(pair) || 0;
    seen.set(pair, nth + 1);
    const path = flowEdgePathIn(svg, edge, nth);
    if (!path || typeof path.getTotalLength !== 'function') continue;
    const matrix = path.getScreenCTM();
    const at = (length) => {
      const point = path.getPointAtLength(length).matrixTransform(matrix);
      return { x: (point.x - origin.left) / shown, y: (point.y - origin.top) / shown };
    };
    const total = path.getTotalLength();
    edges.push({ id: edge.id, path, from: at(0), to: at(total), at: at(total / 2) });
  }
  
  for (const edge of edges) flowDrawEdgeTarget(edge.path, edge.id);
  flowNatural = { nodes, edges, groups };
  flowLostBoxes = graph.nodes.length && !nodes.length;
  placeFlowDiagram();
}


function placeFlowDiagram() {
  if (!flowNatural) {
    flowPlaced = null;
    return;
  }
  const shown = flowZoom;
  const point = (at) => ({ x: at.x * shown, y: at.y * shown });
  const box = (drawn) => ({
    id: drawn.id,
    x: drawn.x * shown,
    y: drawn.y * shown,
    width: drawn.width * shown,
    height: drawn.height * shown,
  });
  flowPlaced = {
    nodes: flowNatural.nodes.map((node) => ({ ...box(node), radius: node.radius * shown })),
    
    edges: flowNatural.edges.map((edge) => ({
      id: edge.id,
      path: edge.path,
      from: point(edge.from),
      to: point(edge.to),
      at: point(edge.at),
    })),
    groups: flowNatural.groups.map(box),
  };
}


function flowCornerRadiusFrom(inset) {
  return inset / (1 - Math.SQRT1_2);
}


const flowProbedRadii = new WeakMap();


function flowDrawnRadius(group, width, height) {
  let radius = flowProbedRadii.get(group);
  if (radius === undefined) {
    radius = flowProbeDrawnRadius(group);
    flowProbedRadii.set(group, radius);
  }
  
  return Number.isFinite(radius) ? Math.max(0, Math.min(radius, Math.min(width, height) / 2)) : 0;
}


function flowProbeDrawnRadius(group) {
  
  let outline = null;
  let widest = 0;
  group.querySelectorAll('rect, circle, ellipse, polygon, path').forEach((drawn) => {
    let box;
    try {
      box = drawn.getBBox();
    } catch (error) {
      return;
    }
    const area = box.width * box.height;
    if (area > widest) {
      widest = area;
      outline = drawn;
    }
  });
  const svg = outline && outline.ownerSVGElement;
  if (!outline || !svg || typeof outline.isPointInFill !== 'function') return 0;
  let box;
  try {
    box = outline.getBBox();
  } catch (error) {
    return 0;
  }
  const reach = Math.min(box.width, box.height) / 2;
  if (!(reach > 0)) return 0;

  
  const probe = svg.createSVGPoint();
  const filled = (x, y) => {
    probe.x = x;
    probe.y = y;
    try {
      return outline.isPointInFill(probe);
    } catch (error) {
      return false;
    }
  };
  if (filled(box.x + 0.5, box.y + 0.5)) return 0; 
  let inside = reach;
  let outside = 0;
  for (let step = 0; step < 14; step += 1) {
    const mid = (inside + outside) / 2;
    if (filled(box.x + mid, box.y + mid)) inside = mid;
    else outside = mid;
  }
  return flowCornerRadiusFrom(inside);
}




const FLOW_RING_GAP = 8;


function placeFlowOverlay() {
  const stage = flowCanvas && flowCanvas.querySelector('.flow-stage');
  const layer = stage && stage.querySelector('.flow-overlay');
  if (!layer) return;
  const graph = flowSession && flowSession.graph;
  if (!graph || !flowPlaced) return;
  
  for (const placed of flowPlaced.edges) {
    placed.path.classList.toggle('is-selected', !!flowSelection && flowSelection.id === placed.id);
  }
  const sides = flowBudSidesFor(graph);
  for (const box of flowPlaced.nodes) {
    const chosen = flowSelection && flowSelection.kind === 'node' && flowSelection.id === box.id;
    const tools = Array.from(layer.children).find((child) => child.dataset.node === box.id);
    if (!tools) continue;
    tools.classList.toggle('is-selected', !!chosen);
    tools.style.left = box.x - FLOW_RING_GAP + 'px';
    tools.style.top = box.y - FLOW_RING_GAP + 'px';
    tools.style.width = box.width + FLOW_RING_GAP * 2 + 'px';
    tools.style.height = box.height + FLOW_RING_GAP * 2 + 'px';
    const ring = tools.querySelector('.flow-ring');
    if (!ring) continue;
    
    ring.style.borderRadius = Math.round(box.radius + FLOW_RING_GAP) + 'px';
  }
  
  const chosenEdge = flowSelection && flowSelection.kind === 'edge' ? flowSelection.id : null;
  for (const placed of flowPlaced.edges) {
    if (placed.id !== chosenEdge) continue;
    for (const which of ['from', 'to']) {
      const grip = Array.from(layer.children).find((child) => child.dataset.edge === placed.id && child.dataset.endpoint === which);
      if (!grip) continue;
      grip.style.left = placed[which].x + 'px';
      grip.style.top = placed[which].y + 'px';
    }
  }
}


function drawFlowOverlay() {
  const stage = flowCanvas && flowCanvas.querySelector('.flow-stage');
  const layer = stage && stage.querySelector('.flow-overlay');
  if (!layer) return;
  layer.textContent = '';
  const graph = flowSession && flowSession.graph;
  if (!graph || !flowPlaced) return;
  const sides = flowBudSidesFor(graph);
  for (const box of flowPlaced.nodes) {
    const tools = document.createElement('div');
    tools.className = 'flow-node-tools';
    tools.dataset.node = box.id;
    const node = flowFindNode(graph, box.id);
    const ring = document.createElement('div');
    
    ring.className = 'flow-ring' + (node && node.href ? ' is-linked' : '');
    if (node && node.href) ring.title = 'Clicking this box opens ' + node.href;
    ring.dataset.node = box.id;
    tools.appendChild(ring);
    
    for (const side of sides) {
      const bud = document.createElement('button');
      bud.type = 'button';
      bud.className = 'flow-bud is-' + side;
      bud.dataset.bud = side;
      bud.dataset.node = box.id;
      bud.title = flowBudTitle(graph.direction, side);
      bud.textContent = '+';
      tools.appendChild(bud);
    }
    layer.appendChild(tools);
  }
  const chosenEdge = flowSelection && flowSelection.kind === 'edge' ? flowSelection.id : null;
  for (const placed of flowPlaced.edges) {
    if (placed.id !== chosenEdge) continue;
    for (const which of ['from', 'to']) {
      const grip = document.createElement('button');
      grip.type = 'button';
      grip.className = 'flow-edge-end';
      grip.dataset.endpoint = which;
      grip.dataset.edge = placed.id;
      grip.title = 'Drag onto another box to move this end';
      layer.appendChild(grip);
    }
  }
  placeFlowOverlay();
}





const flowChipCache = new Map();
let flowChipsAsked = false;
let flowChipThemeVersion = 0;

function flowShapeChip(id) {
  return flowChipCache.get(id) || '';
}


function flowChipPicture(svg) {
  const holder = document.createElement('div');
  holder.innerHTML = svg;
  const root = holder.firstElementChild;
  if (!root) return '';
  root.setAttribute('preserveAspectRatio', 'xMidYMid meet');
  root.style.maxWidth = 'none';
  return '<img class="flow-chip" alt="" src="data:image/svg+xml;base64,' + diagramBase64(root.outerHTML) + '">';
}

function loadFlowChips() {
  if (flowChipsAsked) return;
  flowChipsAsked = true;
  const themeVersion = flowChipThemeVersion;
  loadMermaid()
    .then(async (mermaid) => {
      mermaid.initialize(mermaidRuntimeConfig());
      for (const shape of FLOW_SHAPES) {
        const label = '" "';
        const body = shape.open ? shape.open + label + shape.close : '@{ shape: ' + shape.id + ', label: " " }';
        try {
          const { svg } = await mermaid.render('leafFlowChip-' + shape.id, 'flowchart LR\n  c' + body);
          if (themeVersion !== flowChipThemeVersion) return;
          flowChipCache.set(shape.id, flowChipPicture(svg));
        } catch (error) {
          if (themeVersion !== flowChipThemeVersion) return;
          
          flowChipCache.set(shape.id, '');
        }
      }
      if (themeVersion !== flowChipThemeVersion) return;
      
      forgetFlowShapeGrid();
      
      flowShapeGridPrepared();
      if (flowSession) drawFlowPicker();
    })
    .catch(() => {});
}


function refreshFlowChipsForTheme() {
  flowChipThemeVersion += 1;
  flowDiagramThemeVersion += 1;
  flowChipCache.clear();
  flowChipsAsked = false;
  flowDrawingStore.clear();
  flowDrawingStoreHeld = 0;
  forgetFlowShapeGrid();
  if (!flowSession) return;
  loadFlowChips();
  drawFlowDiagram();
}






function openBlockFlowSheet(write, place) {
  collapseBlockInsertRow();
  openFlowSheet({
    title: 'New flowchart',
    text: FLOW_STARTER,
    save: (text) => {
      if (!blockInsertPlaceStanding(place)) return false;
      
      return write({ id: 'flow', text: '```mermaid\n' + text + '\n```', kind: 'flowchart', answered: true });
    },
  });
}


function openMermaidBlockSheet(block) {
  const span = flowBlockSpan(block);
  if (!span) return;
  openFlowSheet({
    title: 'Flowchart',
    text: span.text,
    
    save: (text) => {
      const now = flowBlockSpan(block);
      if (!now) return false;
      const token = nextEditToken();
      sendEditCommand({ command: 'editBlock', start: now.start, end: now.end, text, token, kind: 'flowchart' });
      return token;
    },
  });
}


function flowBlockSpan(block) {
  if (!block || !block.isConnected) return null;
  const { start: blockStart, end: blockEnd } = rangeOf(block, 'block');
  if (!Number.isFinite(blockStart) || !Number.isFinite(blockEnd)) return null;
  const source = sliceSourceBytes(blockStart, blockEnd);
  const span = fencedCodeInnerSpan(source);
  if (!span) return null;
  return {
    start: blockStart + utf8ByteLength(source.slice(0, span.from)),
    end: blockStart + utf8ByteLength(source.slice(0, span.to)),
    text: source.slice(span.from, span.to),
  };
}




const FLOW_SVG_NS = 'http://www.w3.org/2000/svg';

function flowNodeAt(x, y) {
  const found = flowTargetAt(x, y);
  return found && found.kind === 'node' ? found.id : null;
}


function flowTargetAt(x, y) {
  if (!flowCanvas) return null;
  const found = document.elementFromPoint(x, y);
  if (!found || !found.closest || !flowCanvas.contains(found)) return null;
  const ring = found.closest('.flow-ring');
  if (ring) return { kind: 'node', id: ring.dataset.node };
  const bud = found.closest('.flow-bud');
  if (bud) return { kind: 'node', id: bud.dataset.node };
  const edge = flowEdgeUnder(found);
  if (edge) return { kind: 'edge', id: edge };
  
  const inside = flowGroupAt(x, y);
  if (inside) return { kind: 'group', id: inside };
  return { kind: 'canvas', id: null };
}


function flowGroupAt(x, y) {
  const stage = flowCanvas && flowCanvas.querySelector('.flow-stage');
  if (!stage || !flowPlaced || !flowPlaced.groups) return null;
  const origin = stage.getBoundingClientRect();
  const at = { x: x - origin.left, y: y - origin.top };
  let best = null;
  let smallest = Infinity;
  for (const box of flowPlaced.groups) {
    if (at.x < box.x || at.x > box.x + box.width || at.y < box.y || at.y > box.y + box.height) continue;
    const area = box.width * box.height;
    if (area < smallest) {
      smallest = area;
      best = box.id;
    }
  }
  return best;
}


function flowPointIsBare(target) {
  if (!target || !target.closest) return false;
  if (target === flowCanvas) return true;
  if (target.classList && (target.classList.contains('flow-stage') || target.classList.contains('flow-overlay'))) {
    return true;
  }
  return target.tagName === 'svg' || target.tagName === 'SVG';
}


function flowPointAt(x, y) {
  const stage = flowCanvas && flowCanvas.querySelector('.flow-stage');
  if (!stage) return { x: 0, y: 0 };
  const rect = stage.getBoundingClientRect();
  return { x: x - rect.left, y: y - rect.top };
}

function flowPointIn(event) {
  return flowPointAt(event.clientX, event.clientY);
}


function flowEdgeUnder(element) {
  if (!flowPlaced || !element) return null;
  const path = element.closest ? element.closest('path[data-flow-hit], path[data-id], g[data-id]') : null;
  if (!path) return null;
  if (path.dataset.flowHit) return path.dataset.flowHit;
  const found = flowPlaced.edges.find((edge) => edge.path === path || edge.path.dataset.id === path.dataset.id);
  return found ? found.id : null;
}


let flowHovered = null;

function markFlowHover(target) {
  const over = target && (target.kind === 'node' || target.kind === 'edge') ? target : null;
  
  const key = over ? over.kind + ':' + over.id : null;
  if (flowHovered === key) return;
  flowHovered = key;
  if (!flowCanvas) return;
  flowCanvas.querySelectorAll('.is-hover').forEach((found) => found.classList.remove('is-hover'));
  
  if (!over) {
    restoreFlowHint();
    return;
  }
  if (over.kind === 'edge') {
    const placed = flowPlaced ? flowPlaced.edges.find((edge) => edge.id === over.id) : null;
    if (placed) placed.path.classList.add('is-hover');
    setFlowHint(FLOW_TIP_EDGE);
    return;
  }
  
  const graph = flowSession && flowSession.graph;
  setFlowHint((graph && flowNodeTip(graph, over.id)) || FLOW_TIP_IDLE);
}


function flowGroupFor(id) {
  return flowCanvas ? flowCanvas.querySelector('.flow-node-tools[data-node="' + id + '"]') : null;
}


function flowClusterFor(id) {
  const stage = flowCanvas && flowCanvas.querySelector('.flow-stage');
  if (!stage) return null;
  const wanted = new Set([id]);
  let found = null;
  stage.querySelectorAll('svg g.cluster').forEach((drawn) => {
    if (found) return;
    if (flowNodeIdFromDom(drawn.id, wanted) || flowNodeIdFromDom(drawn.dataset.id, wanted)) found = drawn;
  });
  return found;
}


function drawFlowRubber(from, to) {
  const layer = flowCanvas && flowCanvas.querySelector('.flow-overlay');
  if (!layer) return;
  let band = layer.querySelector('.flow-rubber-band');
  if (!band) {
    band = document.createElementNS(FLOW_SVG_NS, 'svg');
    band.setAttribute('class', 'flow-rubber-band');
    band.appendChild(document.createElementNS(FLOW_SVG_NS, 'line'));
    layer.appendChild(band);
  }
  const line = band.firstChild;
  line.setAttribute('class', 'flow-rubber');
  line.setAttribute('x1', from.x);
  line.setAttribute('y1', from.y);
  line.setAttribute('x2', to.x);
  line.setAttribute('y2', to.y);
}

function clearFlowRubber() {
  const band = flowCanvas && flowCanvas.querySelector('.flow-rubber-band');
  if (band) band.remove();
}


function markFlowDropTarget(target) {
  if (!flowCanvas) return;
  flowCanvas.querySelectorAll('.is-drop').forEach((found) => found.classList.remove('is-drop'));
  if (!target) return;
  const spot = typeof target === 'string' ? { kind: 'node', id: target } : target;
  if (spot.kind === 'node') {
    const group = flowGroupFor(spot.id);
    if (group) group.classList.add('is-drop');
    return;
  }
  if (spot.kind === 'group') {
    const drawn = flowClusterFor(spot.id);
    if (drawn) drawn.classList.add('is-drop');
    return;
  }
  if (spot.kind !== 'edge') return;
  const placed = flowPlaced && flowPlaced.edges.find((edge) => edge.id === spot.id);
  if (placed) placed.path.classList.add('is-drop');
}


function flowFixedEnd(edgeId, moving) {
  const placed = flowPlaced && flowPlaced.edges.find((edge) => edge.id === edgeId);
  if (!placed) return { x: 0, y: 0 };
  return moving === 'from' ? placed.to : placed.from;
}


function beginFlowPan(event) {
  flowDrag = {
    kind: 'pan',
    startX: event.clientX,
    startY: event.clientY,
    panX: flowPan.x,
    panY: flowPan.y,
    moved: false,
  };
  leafHoldPointer(flowCanvas, event.pointerId);
}

if (flowCanvas) {
  flowCanvas.addEventListener('pointerdown', (event) => {
    if (!flowSession || event.button !== 0) return;
    const graph = flowSession.graph;
    if (!graph) {
      beginFlowPan(event);
      return;
    }
    const target = event.target;
    const near = (selector) => (target && target.closest ? target.closest(selector) : null);
    const endpoint = near('.flow-edge-end');
    const bud = near('.flow-bud');
    const node = near('.flow-ring');
    const edge = flowEdgeUnder(target);
    
    const grab = () => leafHoldPointer(flowCanvas, event.pointerId);
    closeFlowLabelBox(true);
    if (endpoint) {
      flowDrag = { kind: 'retarget', edge: endpoint.dataset.edge, end: endpoint.dataset.endpoint, moved: false };
      grab();
      return;
    }
    if (bud) {
      selectFlow('node', bud.dataset.node);
      flowDrag = { kind: 'bud', from: bud.dataset.node, side: bud.dataset.bud, moved: false };
      grab();
      return;
    }
    if (node) {
      selectFlow('node', node.dataset.node);
      flowDrag = {
        kind: 'reorder',
        from: node.dataset.node,
        startX: event.clientX,
        startY: event.clientY,
        moved: false,
      };
      grab();
      return;
    }
    if (edge) {
      selectFlow('edge', edge);
      return;
    }
    
    dismissFlowPicker();
    beginFlowPan(event);
  });

  flowCanvas.addEventListener('pointermove', (event) => {
    if (!flowDrag) {
      markFlowHover(flowTargetAt(event.clientX, event.clientY));
      return;
    }
    if (flowDrag.kind === 'pan') {
      flowDrag.moved = true;
      setFlowPan(
        flowDrag.panX + (event.clientX - flowDrag.startX),
        flowDrag.panY + (event.clientY - flowDrag.startY),
      );
      flowCanvas.classList.add('is-panning');
      return;
    }
    if (flowDrag.kind === 'reorder') {
      const far = Math.abs(event.clientX - flowDrag.startX) + Math.abs(event.clientY - flowDrag.startY);
      if (!flowDrag.moved && far <= 4) return;
      flowDrag.moved = true;
      flowCanvas.classList.add('is-dragging');
      setFlowHint(FLOW_TIP_MOVING);
      
      const group = flowGroupFor(flowDrag.from);
      if (group) {
        group.classList.add('is-dragging');
        const dx = event.clientX - flowDrag.startX;
        const dy = event.clientY - flowDrag.startY;
        group.style.transform = 'translate(' + Math.round(dx) + 'px,' + Math.round(dy) + 'px)';
      }
      markFlowDropTarget(flowTargetAt(event.clientX, event.clientY));
      return;
    }
    flowDrag.moved = true;
    flowCanvas.classList.add('is-connecting');
    if (flowDrag.kind === 'bud') setFlowHint(FLOW_TIP_BUD);
    const anchor =
      flowDrag.kind === 'retarget'
        ? flowFixedEnd(flowDrag.edge, flowDrag.end)
        : flowBudAnchor(flowDrag.from, flowDrag.side);
    drawFlowRubber(anchor, flowPointIn(event));
    markFlowDropTarget(flowNodeAt(event.clientX, event.clientY));
  });

  
  flowCanvas.addEventListener('pointerleave', () => markFlowHover(null));

  flowCanvas.addEventListener('pointerup', (event) => {
    const drag = flowDrag;
    flowDrag = null;
    flowCanvas.classList.remove('is-dragging');
    flowCanvas.classList.remove('is-connecting');
    flowCanvas.classList.remove('is-panning');
    clearFlowRubber();
    markFlowDropTarget(null);
    const graph = flowSession && flowSession.graph;
    restoreFlowHint();
    if (!drag || !graph || drag.kind === 'pan') return;
    const spot = flowTargetAt(event.clientX, event.clientY);
    const over = spot && spot.kind === 'node' ? spot.id : null;

    
    if (drag.kind === 'bud' && !drag.moved) {
      openFlowAddPicker((shape, named) =>
        addFlowNode(shape, { ...flowBudRelation(graph, drag.from, drag.side), text: named }),
      );
      return;
    }
    if (!drag.moved) return;
    if (drag.kind === 'retarget') {
      const edge = flowFindEdge(graph, drag.edge);
      if (!edge || !over) {
        drawFlowOverlay();
        return;
      }
      if (drag.end === 'from') edge.from = over;
      else edge.to = over;
      flowGraphChanged();
      return;
    }
    if (drag.kind === 'bud') {
      
      if (over) {
        const edge =
          flowBudIntent(graph.direction, drag.side).step === 'previous'
            ? flowConnect(graph, over, drag.from)
            : flowConnect(graph, drag.from, over);
        if (edge) flowSelection = { kind: 'edge', id: edge.id };
        flowGraphChanged();
        return;
      }
      if (!spot) {
        drawFlowOverlay();
        return;
      }
      const where = flowSlotAt(flowPointIn(event));
      openFlowAddPicker((shape, named) =>
        addFlowNode(shape, { ...flowBudRelation(graph, drag.from, drag.side), before: where, text: named }),
      );
      return;
    }
    
    if (spot && spot.kind === 'edge') {
      const edge = flowFindEdge(graph, spot.id);
      if (edge && edge.from !== drag.from && edge.to !== drag.from) {
        
        flowExtractNode(graph, drag.from);
        flowSpliceIntoEdge(graph, drag.from, spot.id);
        flowGraphChanged();
        return;
      }
    }
    
    const moving = flowFindNode(graph, drag.from);
    if (spot && spot.kind === 'group') {
      
      if (moving && moving.group === spot.id) {
        drawFlowOverlay();
        return;
      }
      flowMoveNodeToGroup(graph, drag.from, spot.id);
      flowGraphChanged();
      return;
    }
    if (spot && spot.kind === 'canvas' && moving && moving.group) {
      flowMoveNodeToGroup(graph, drag.from, null);
      flowGraphChanged();
      return;
    }
    if (!over || over === drag.from) {
      
      drawFlowOverlay();
      return;
    }
    
    const order = graph.nodes.map((node) => node.id);
    const was = order.indexOf(drag.from);
    const onto = order.indexOf(over);
    flowMoveNode(graph, drag.from, was < onto ? order[onto + 1] || null : over);
    flowGraphChanged();
  });

  flowCanvas.addEventListener('dblclick', (event) => {
    if (!flowSession || !flowSession.graph) return;
    const near = (selector) => (event.target && event.target.closest ? event.target.closest(selector) : null);
    const node = near('.flow-ring');
    const edge = flowEdgeUnder(event.target);
    if (node) {
      openFlowLabelBox('node', node.dataset.node);
      return;
    }
    if (edge) {
      openFlowLabelBox('edge', edge);
      return;
    }
    
    if (!flowPointIsBare(event.target)) return;
    
    const where = flowSlotAt(flowPointIn(event));
    openFlowAddPicker((shape, named) => addFlowNode(shape, { before: where, text: named }));
  });

  flowCanvas.addEventListener('contextmenu', (event) => {
    if (!flowSession || !flowSession.graph) return;
    event.preventDefault();
    const spot = flowTargetAt(event.clientX, event.clientY) || { kind: 'canvas', id: null };
    
    if (spot.kind === 'canvas' || spot.kind === 'group') {
      const where = flowSlotAt(flowPointIn(event));
      openFlowAddPicker((shape, named) => addFlowNode(shape, { before: where, text: named }));
      return;
    }
    selectFlow(spot.kind, spot.id);
    openFlowMenu(event.clientX, event.clientY, spot);
  });
}





let flowMenu = null;

function flowMenuItems(spot) {
  const graph = flowSession.graph;
  if (spot.kind === 'node') {
    return [
      { label: 'Rename', run: () => openFlowLabelBox('node', spot.id) },
      {
        label: 'Add box after this',
        run: () => addFlowNode(flowNewNodeShape(graph, spot.id), { connectFrom: spot.id }),
      },
      {
        label: 'Add box before this',
        run: () => addFlowNode(flowNewNodeShape(graph, spot.id), { connectTo: spot.id }),
      },
      {
        label: 'Duplicate',
        run: () => {
          const copy = flowDuplicateNode(graph, spot.id);
          if (copy) flowSelection = { kind: 'node', id: copy.id };
          flowGraphChanged();
        },
      },
      {
        label: 'Take it out of the chain',
        run: () => {
          flowExtractNode(graph, spot.id);
          flowGraphChanged();
        },
      },
      ...flowGroupItems(graph, spot.id),
      { label: 'Delete box', run: deleteFlowSelection },
    ];
  }
  if (spot.kind === 'edge') {
    return [
      { label: 'Label this line', run: () => openFlowLabelBox('edge', spot.id) },
      {
        label: 'Point it the other way',
        run: () => {
          flowFlipEdge(graph, spot.id);
          flowGraphChanged();
        },
      },
      { label: 'Delete line', run: deleteFlowSelection },
    ];
  }
  return [];
}


function flowGroupItems(graph, id) {
  const node = flowFindNode(graph, id);
  if (!node) return [];
  const items = [];
  
  const rename = (groupId) => {
    window.setTimeout(() => openFlowLabelBox('group', groupId), 160);
  };
  items.push({
    label: 'Put it in a new group',
    run: () => {
      const group = flowGroupNodes(graph, [id], 'Group');
      flowGraphChanged();
      if (group) rename(group.id);
    },
  });
  
  for (const group of graph.groups || []) {
    if (group.id === node.group) continue;
    items.push({
      label: 'Move it into ' + (group.text || group.id),
      run: () => {
        flowMoveNodeToGroup(graph, id, group.id);
        flowGraphChanged();
      },
    });
  }
  if (node.group) {
    const group = flowFindGroup(graph, node.group);
    items.push({
      label: 'Take it out of ' + (group.text || node.group),
      run: () => {
        flowMoveNodeToGroup(graph, id, group ? group.parent : null);
        flowGraphChanged();
      },
    });
    items.push({ label: 'Rename the group', run: () => openFlowLabelBox('group', node.group) });
    items.push({
      label: 'Remove the group, keep the boxes',
      run: () => {
        flowUngroup(graph, node.group);
        flowGraphChanged();
      },
    });
  }
  return items;
}

function openFlowMenu(x, y, spot) {
  openFlowMenuWith(x, y, flowMenuItems(spot));
}


function openFlowMenuWith(x, y, items, host) {
  closeFlowMenu();
  const menu = document.createElement('div');
  menu.className = 'flow-menu';
  menu.setAttribute('role', 'menu');
  for (const item of items) {
    
    if (item.heading) {
      const caption = document.createElement('div');
      caption.className = 'flow-menu-heading';
      caption.textContent = item.heading;
      menu.appendChild(caption);
      continue;
    }
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'flow-menu-item';
    button.setAttribute('role', 'menuitem');
    if (item.hint) button.title = item.hint;
    const text = document.createElement('span');
    text.textContent = item.label;
    button.appendChild(text);
    button.addEventListener('click', () => {
      closeFlowMenu();
      item.run();
    });
    menu.appendChild(button);
  }
  const holder = host || flowSheet;
  holder.appendChild(menu);
  
  const sheet = holder.getBoundingClientRect();
  const size = menu.getBoundingClientRect();
  const left = Math.min(x - sheet.left, sheet.width - size.width - 8);
  const top = Math.min(y - sheet.top, sheet.height - size.height - 8);
  menu.style.left = Math.max(8, left) + 'px';
  menu.style.top = Math.max(8, top) + 'px';
  flowMenu = menu;
  document.addEventListener('pointerdown', onFlowMenuOutside, true);
}

function closeFlowMenu() {
  if (!flowMenu) return;
  document.removeEventListener('pointerdown', onFlowMenuOutside, true);
  if (flowMenu.parentNode) flowMenu.parentNode.removeChild(flowMenu);
  flowMenu = null;
}

function onFlowMenuOutside(event) {
  if (flowMenu && event.target && event.target.closest && event.target.closest('.flow-menu')) return;
  closeFlowMenu();
}


function flowBudAnchor(id, side) {
  const box = flowPlaced && flowPlaced.nodes.find((node) => node.id === id);
  if (!box) return { x: 0, y: 0 };
  const cx = box.x + box.width / 2;
  const cy = box.y + box.height / 2;
  if (side === 'up') return { x: cx, y: box.y - FLOW_RING_GAP };
  if (side === 'left') return { x: box.x - FLOW_RING_GAP, y: cy };
  if (side === 'right') return { x: box.x + box.width + FLOW_RING_GAP, y: cy };
  return { x: cx, y: box.y + box.height + FLOW_RING_GAP };
}


function flowNewNodeShape(graph, fromId) {
  const node = flowFindNode(graph, fromId);
  if (!node) return FLOW_SHAPES[0].id;
  
  if (node.shape === 'diam' || node.shape === 'stadium') return 'rect';
  return node.shape;
}

function selectFlow(kind, id) {
  flowSelection = kind ? { kind, id } : null;
  drawFlowOverlay();
  drawFlowPicker();
}

function deleteFlowSelection() {
  const graph = flowSession && flowSession.graph;
  if (!graph || !flowSelection) return;
  if (flowSelection.kind === 'node') flowDeleteNode(graph, flowSelection.id);
  
  else if (flowSelection.kind === 'group') flowUngroup(graph, flowSelection.id);
  else flowDeleteEdge(graph, flowSelection.id);
  flowSelection = null;
  flowGraphChanged();
}





let flowLabelBox = null;


function openFlowLabelBox(kind, id) {
  const graph = flowSession && flowSession.graph;
  if (!graph || !flowPlaced) return;
  closeFlowLabelBox(true);
  const stage = flowCanvas.querySelector('.flow-stage');
  if (!stage) return;
  const find = {
    node: () => flowFindNode(graph, id),
    edge: () => flowFindEdge(graph, id),
    group: () => flowFindGroup(graph, id),
  };
  const where = {
    node: () => flowPlaced.nodes.find((entry) => entry.id === id),
    edge: () => flowPlaced.edges.find((entry) => entry.id === id),
    group: () => (flowPlaced.groups || []).find((entry) => entry.id === id),
  };
  const subject = find[kind] && find[kind]();
  const placed = where[kind] && where[kind]();
  if (!subject || !placed) return;
  const field = document.createElement('input');
  field.type = 'text';
  field.className = 'flow-label-box';
  field.spellcheck = false;
  field.value = (kind === 'edge' ? subject.label : subject.text) || '';
  field.placeholder =
    kind === 'node' ? 'Name this box' : kind === 'group' ? 'Name this group' : 'Label this line';
  field.setAttribute('aria-label', field.placeholder);
  const tall = Math.max(20, Math.round(26 * flowZoom));
  const width =
    kind === 'edge' ? Math.max(90, 140 * flowZoom) : Math.max(70, placed.width - 10);
  const left = kind === 'edge' ? placed.at.x - width / 2 : placed.x + (placed.width - width) / 2;
  
  const middle =
    kind === 'edge' ? placed.at.y : kind === 'group' ? placed.y + tall / 2 + 2 : placed.y + placed.height / 2;
  const top = middle - tall / 2;
  field.style.left = Math.round(left) + 'px';
  field.style.top = Math.round(top) + 'px';
  field.style.width = Math.round(width) + 'px';
  field.style.height = tall + 'px';
  field.style.fontSize = Math.max(9, Math.round(13 * flowZoom)) + 'px';
  
  field.addEventListener('pointerdown', (event) => event.stopPropagation());
  field.addEventListener('dblclick', (event) => event.stopPropagation());
  field.addEventListener('keydown', (event) => {
    
    if (event.key === 'Escape') {
      event.preventDefault();
      event.stopPropagation();
      closeFlowLabelBox(false);
      return;
    }
    if (event.key === 'Enter') {
      event.preventDefault();
      event.stopPropagation();
      closeFlowLabelBox(true);
    }
  });
  field.addEventListener('blur', () => closeFlowLabelBox(true));
  stage.appendChild(field);
  flowLabelBox = { kind, id, field, was: field.value };
  flowSelection = { kind, id };
  field.focus();
  field.select();
}


function closeFlowLabelBox(keep) {
  const box = flowLabelBox;
  if (!box) return;
  flowLabelBox = null;
  const value = box.field.value;
  if (box.field.parentNode) box.field.parentNode.removeChild(box.field);
  if (!keep || value === box.was) return;
  const graph = flowSession && flowSession.graph;
  if (!graph) return;
  if (box.kind === 'node') {
    const node = flowFindNode(graph, box.id);
    if (!node) return;
    node.text = value.trim() || node.id;
  } else if (box.kind === 'group') {
    const group = flowFindGroup(graph, box.id);
    if (!group) return;
    group.text = value.trim() || group.id;
  } else {
    const edge = flowFindEdge(graph, box.id);
    if (!edge) return;
    edge.label = value.trim() || null;
  }
  flowGraphChanged();
}






let flowPickerReady = false;


function readyFlowPicker() {
  if (flowPickerReady || !flowPicker) return;
  flowPickerReady = true;
  const grip = flowPicker.querySelector('.leaf-sheet-grip');
  if (typeof makeSheetDraggable === 'function' && grip) {
    makeSheetDraggable(flowPicker, grip, dismissFlowPicker, { tallerOnPullUp: true });
  }
  
  if (flowPickerClose) flowPickerClose.addEventListener('click', () => dismissFlowPicker());
  
  if (flowSheet) flowSheet.addEventListener('pointerdown', pressOutsideFlowPicker, true);
}


const FLOW_PICKER_KEEPS_ITS_PRESS = '#flowPicker, #flowCanvas, #flowSheetHead, #flowSplit';


function pressOutsideFlowPicker(event) {
  if (!flowPicker || flowPicker.hidden || event.button !== 0) return;
  const target = event.target;
  if (target && target.closest && target.closest(FLOW_PICKER_KEEPS_ITS_PRESS)) return;
  dismissFlowPicker();
}

function openFlowAddPicker(make) {
  flowPickerAdd = make;
  flowPickerName = '';
  selectFlow(null, null);
  drawFlowPicker();
  
  window.setTimeout(() => {
    const field = flowPickerHead && flowPickerHead.querySelector('.flow-field');
    if (field && flowPickerAdd) field.focus();
  }, 60);
}

function closeFlowAddPicker() {
  if (!flowPickerAdd) return;
  flowPickerAdd = null;
  flowPickerName = '';
  drawFlowPicker();
}


function dismissFlowPicker(options) {
  flowPickerAdd = null;
  flowPickerName = '';
  selectFlow(null, null);
  drawFlowPicker(options);
}

function drawFlowPicker(options) {
  if (!flowPicker || !flowPickerBody || !flowPickerHead) return;
  const graph = flowSession && flowSession.graph;
  const selection = flowSelection;
  flowPickerHead.textContent = '';
  
  for (const child of [...flowPickerBody.children]) {
    if (child !== flowShapeWrap) child.remove();
  }
  const node = graph && selection && selection.kind === 'node' ? flowFindNode(graph, selection.id) : null;
  const edge = graph && selection && selection.kind === 'edge' ? flowFindEdge(graph, selection.id) : null;
  const adding = !!flowPickerAdd && !!graph;
  if (!node && !edge && !adding) {
    
    closeSheet(flowPicker, flowPickerBackdrop, options);
    return;
  }
  
  openSheet(flowPicker, flowPickerBackdrop, { keepParked: true });

  
  const form = document.createElement('div');
  form.className = 'flow-form';
  form.appendChild(
    flowPickerRow(
      adding || node ? 'Name' : 'Label',
      adding ? flowPickerNameField() : flowPickerField(graph, node, edge)
    )
  );
  if (node) for (const extra of FLOW_NODE_EXTRAS) form.appendChild(flowPickerRow(extra.label, flowPickerExtraField(graph, node, extra)));
  flowPickerHead.appendChild(form);

  
  if (adding || node) {
    
    flowShapePress = adding
      ? (id) => {
          const make = flowPickerAdd;
          const named = flowPickerName;
          flowPickerAdd = null;
          flowPickerName = '';
          if (make) make(id, named);
        }
      : (id) => {
          node.shape = id;
          flowGraphChanged();
        };
    flowShapeGridStands();
    markFlowShape(node ? node.shape : null);
  } else {
    
    flowShapePress = null;
    flowShapeGridStandsDown();
    
    flowPickerChoices('Line', FLOW_EDGE_LINES, edge.line, (id) => flowEdgeChip(id, 'none'), (id) => {
      edge.line = id;
      if (flowEdgeLine(id).only) edge.ends = flowEdgeLine(id).only;
      flowGraphChanged();
    });
    flowPickerChoices('Ends', FLOW_EDGE_ENDS, edge.ends, (id) => flowEdgeChip(edge.line, id), (id) => {
      edge.ends = id;
      const line = flowEdgeLine(edge.line);
      if (line.only && line.only !== id) edge.line = FLOW_EDGE_LINES[0].id;
      flowGraphChanged();
    });
  }

  if (!node && !edge) return;
  const remove = document.createElement('button');
  remove.type = 'button';
  remove.className = 'flow-delete';
  remove.textContent = node ? 'Delete box' : 'Delete line';
  remove.title = 'Or press Delete';
  remove.addEventListener('click', deleteFlowSelection);
  flowPickerBody.appendChild(remove);
}


function flowPickerNameField() {
  const field = document.createElement('input');
  field.type = 'text';
  field.className = 'flow-field';
  field.spellcheck = false;
  field.placeholder = 'Name this box, then pick its shape';
  field.value = flowPickerName;
  field.setAttribute('aria-label', 'Name this box');
  field.addEventListener('input', () => {
    flowPickerName = field.value;
  });
  return field;
}


function flowPickerField(graph, node, edge) {
  const field = document.createElement('input');
  field.type = 'text';
  field.className = 'flow-field';
  field.spellcheck = false;
  field.placeholder = node ? 'Name this box' : 'Label this line';
  field.value = (node ? node.text : edge.label) || '';
  field.setAttribute('aria-label', node ? 'Box name' : 'Line label');
  field.addEventListener('input', () => {
    if (node) node.text = field.value;
    else edge.label = field.value.trim() || null;
    
    flowSession.text = renderFlow(graph);
    if (flowCode) flowCode.value = flowSession.text;
    queueFlowDiagram();
  });
  field.addEventListener('change', () => flowGraphChanged());
  return field;
}


const FLOW_NODE_EXTRAS = [
  { key: 'href', label: 'Link', placeholder: 'Where clicking this box goes' },
  { key: 'icon', label: 'Icon', placeholder: 'leaf:back' },
  { key: 'img', label: 'Picture', placeholder: 'A picture beside this document, or its address' },
];


function flowPickerRow(label, field) {
  const row = document.createElement('label');
  row.className = 'flow-form-row';
  const caption = document.createElement('span');
  caption.className = 'flow-form-label';
  caption.textContent = label;
  row.appendChild(caption);
  row.appendChild(field);
  return row;
}


function flowPickerExtraField(graph, node, extra) {
  const field = document.createElement('input');
  field.type = 'text';
  field.className = 'flow-field';
  field.spellcheck = false;
  field.placeholder = extra.placeholder;
  field.value = node[extra.key] || '';
  field.setAttribute('aria-label', extra.label);
  field.addEventListener('input', () => {
    node[extra.key] = field.value.trim() || null;
    
    if (extra.key === 'href' && !node.href) node.hrefTip = null;
    flowSession.text = renderFlow(graph);
    if (flowCode) flowCode.value = flowSession.text;
    queueFlowDiagram();
  });
  field.addEventListener('change', () => flowGraphChanged());
  return field;
}


function flowPickerChoices(caption, options, current, chip, apply) {
  if (!options.length) return;
  flowPickerPlace(flowPickerHeading(caption));
  for (const option of options) {
    const button = flowPickerChoice(caption, option, chip(option.id), apply);
    if (option.id === current) button.classList.add('is-current');
    flowPickerPlace(button);
  }
}

function flowPickerHeading(caption) {
  const heading = document.createElement('div');
  heading.className = 'flow-menu-heading';
  heading.textContent = caption;
  return heading;
}

function flowPickerChoice(caption, option, chip, apply) {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'flow-menu-item';
  button.title = option.hint ? option.label + ' — ' + option.hint : option.label;
  button.setAttribute('aria-label', caption + ': ' + option.label);
  button.innerHTML = chip;
  const text = document.createElement('span');
  text.textContent = option.label;
  button.appendChild(text);
  button.addEventListener('click', () => apply(option.id));
  if (option.hint) {
    button.addEventListener('pointerenter', () => setFlowHint(option.label + ' — ' + option.hint));
    button.addEventListener('pointerleave', restoreFlowHint);
  }
  return button;
}


function flowPickerPlace(element) {
  if (flowShapeWrap && flowShapeWrap.parentElement === flowPickerBody) flowPickerBody.insertBefore(element, flowShapeWrap);
  else flowPickerBody.appendChild(element);
}






let flowShapeGrid = null;
let flowShapeWrap = null;
let flowShapeButtons = null;
let flowShapeMarked = null;
let flowShapePress = null;


function flowShapeGridPrepared() {
  if (flowShapeGrid) return;
  flowShapeGrid = [];
  flowShapeButtons = new Map();
  
  flowShapeWrap = document.createElement('div');
  flowShapeWrap.className = 'flow-shape-grid';
  for (const family of flowShapeFamilies()) {
    if (!family.shapes.length) continue;
    flowShapeGrid.push(flowPickerHeading(family.name));
    for (const shape of family.shapes) {
      const button = flowPickerChoice(family.name, shape, flowShapeChip(shape.id), (id) => {
        if (flowShapePress) flowShapePress(id);
      });
      button.tabIndex = 0;
      flowShapeButtons.set(shape.id, button);
      flowShapeGrid.push(button);
    }
  }
  for (const element of flowShapeGrid) flowShapeWrap.appendChild(element);
  flowShapeMarked = null;
}

function flowShapeGridStands() {
  
  flowShapeGridPrepared();
  if (flowShapeWrap.parentElement !== flowPickerBody) flowPickerBody.appendChild(flowShapeWrap);
  if (!flowShapeWrap.classList.contains('is-collapsed')) return;
  flowShapeWrap.classList.remove('is-collapsed');
  flowShapeWrap.removeAttribute('aria-hidden');
  for (const button of flowShapeButtons.values()) button.tabIndex = 0;
}


function flowShapeGridStandsDown() {
  if (!flowShapeWrap || flowShapeWrap.classList.contains('is-collapsed')) return;
  flowShapeWrap.classList.add('is-collapsed');
  flowShapeWrap.setAttribute('aria-hidden', 'true');
  for (const button of flowShapeButtons.values()) button.tabIndex = -1;
}


function markFlowShape(id) {
  const button = (id && flowShapeButtons && flowShapeButtons.get(id)) || null;
  if (flowShapeMarked === button) return;
  if (flowShapeMarked) flowShapeMarked.classList.remove('is-current');
  if (button) button.classList.add('is-current');
  flowShapeMarked = button;
}


function forgetFlowShapeGrid() {
  if (flowShapeWrap) flowShapeWrap.remove();
  flowShapeWrap = null;
  flowShapeGrid = null;
  flowShapeButtons = null;
  flowShapeMarked = null;
}











const DIAGRAM_PNG_SCALE = 2;


const DIAGRAM_EXPORTS = [
  
  { id: 'md', endings: ['md', 'markdown', 'mdown'], label: 'Markdown', hint: 'The mermaid text, in a document of its own' },
  { id: 'png', endings: ['png'], label: 'PNG', hint: 'The drawing as a picture, to paste anywhere' },
  { id: 'webp', endings: ['webp'], label: 'WebP', hint: 'The same picture, about half the file' },
  { id: 'pdf', endings: ['pdf'], label: 'PDF', hint: 'The drawing on one page, sharp at any size' },
  { id: 'jpg', endings: ['jpg', 'jpeg'], label: 'JPEG', hint: 'For anything that will not take a WebP' },
];

let diagramExportSeq = 0;


function diagramBase64(text) {
  const bytes = new TextEncoder().encode(text);
  let binary = '';
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return window.btoa(binary);
}


const DIAGRAM_EXPORT_MARGIN = 24;


function diagramSubgraphTitleOverlap(root) {
  const view = (root.getAttribute('viewBox') || '').split(/[\s,]+/).map(Number);
  if (view.length === 4 && view[2] > 0 && view[3] > 0) {
    root.setAttribute('width', view[2]);
    root.setAttribute('height', view[3]);
    root.style.maxWidth = 'none';
  }
  const measuring = document.createElement('div');
  measuring.setAttribute('style', 'position: fixed; left: -10000px; top: 0; visibility: hidden; pointer-events: none;');
  measuring.appendChild(root);
  appSurface.appendChild(measuring);
  try {
    const nodes = Array.from(root.querySelectorAll('.node')).map((node) => node.getBoundingClientRect());
    let largest = 0;
    for (const cluster of root.querySelectorAll('.cluster')) {
      const frame = cluster.querySelector('rect');
      const title = cluster.querySelector('.cluster-label');
      if (!frame || !title) continue;
      const bounds = frame.getBoundingClientRect();
      const titleBox = title.getBoundingClientRect();
      const firstTop = nodes
        .filter((node) => {
          const x = node.left + node.width / 2;
          const y = node.top + node.height / 2;
          return x >= bounds.left && x <= bounds.right && y >= bounds.top && y <= bounds.bottom;
        })
        .reduce((top, node) => Math.min(top, node.top), Infinity);
      if (Number.isFinite(firstTop)) largest = Math.max(largest, titleBox.bottom - firstTop);
    }
    return Math.max(0, largest);
  } finally {
    measuring.remove();
  }
}

function finishDiagramDrawingSvg(drawn, root, box) {
  
  if (root.tagName !== 'svg' || box.length !== 4 || !(box[2] > 0)) return drawn;
  standBarSeriesSideBySide(root);
  paintChartValueLabels(root);
  
  const left = box[0] - DIAGRAM_EXPORT_MARGIN;
  const top = box[1] - DIAGRAM_EXPORT_MARGIN;
  const width = box[2] + DIAGRAM_EXPORT_MARGIN * 2;
  const height = box[3] + DIAGRAM_EXPORT_MARGIN * 2;
  root.setAttribute('viewBox', left + ' ' + top + ' ' + width + ' ' + height);
  root.setAttribute('width', width);
  root.setAttribute('height', height);
  root.style.maxWidth = 'none';
  const behind = root.ownerDocument.createElementNS(FLOW_SVG_NS, 'rect');
  behind.setAttribute('x', left);
  behind.setAttribute('y', top);
  behind.setAttribute('width', width);
  behind.setAttribute('height', height);
  behind.setAttribute('fill', leafExportBackground());
  root.insertBefore(behind, root.firstChild);
  return new XMLSerializer().serializeToString(root);
}


async function diagramDrawingSvg(source) {
  if (!source) return null;
  const mermaid = await loadMermaid();
  const config = mermaidRuntimeConfig({ htmlLabels: false });
  const draw = async () => {
    const name = 'leafFlowExport' + (diagramExportSeq += 1);
    try {
      return (await mermaid.render(name, source)).svg;
    } catch (error) {
      
      const orphan = document.getElementById('d' + name);
      if (orphan && orphan.remove && outsideEveryReader(orphan)) orphan.remove();
      throw error;
    }
  };
  mermaid.initialize(config);
  let drawn = await draw();
  let root = new DOMParser().parseFromString(drawn, 'image/svg+xml').documentElement;
  let box = (root.getAttribute('viewBox') || '').split(/[\s,]+/).map(Number);
  if (root.tagName !== 'svg' || box.length !== 4 || !(box[2] > 0)) return drawn;
  
  const titleOverlap = diagramSubgraphTitleOverlap(root);
  if (titleOverlap <= 0) {
    labelBarSeriesFromOwnData(root, await chartPlotsFromSource(mermaid, source));
    return finishDiagramDrawingSvg(drawn, root, box);
  }
  const titleGap = config.flowchart.subGraphTitleMargin.bottom;
  config.flowchart.subGraphTitleMargin.bottom = titleOverlap + titleGap;
  mermaid.initialize(config);
  drawn = await draw();
  root = new DOMParser().parseFromString(drawn, 'image/svg+xml').documentElement;
  box = (root.getAttribute('viewBox') || '').split(/[\s,]+/).map(Number);
  labelBarSeriesFromOwnData(root, await chartPlotsFromSource(mermaid, source));
  return finishDiagramDrawingSvg(drawn, root, box);
}


function diagramCanvas(svgText) {
  return new Promise((resolve, reject) => {
    const picture = new Image();
    picture.onload = () => {
      const canvas = document.createElement('canvas');
      canvas.width = Math.max(1, Math.round(picture.naturalWidth * DIAGRAM_PNG_SCALE));
      canvas.height = Math.max(1, Math.round(picture.naturalHeight * DIAGRAM_PNG_SCALE));
      const ink = canvas.getContext('2d');
      if (!ink) {
        reject(new Error('This window cannot make a picture.'));
        return;
      }
      
      ink.fillStyle = leafExportBackground();
      ink.fillRect(0, 0, canvas.width, canvas.height);
      ink.drawImage(picture, 0, 0, canvas.width, canvas.height);
      resolve(canvas);
    };
    picture.onerror = () => reject(new Error('The drawing could not be turned into a picture.'));
    picture.src = 'data:image/svg+xml;base64,' + diagramBase64(svgText);
  });
}


async function diagramPngPixels(svgText) {
  const canvas = await diagramCanvas(svgText);
  const pixels = canvas.getContext('2d').getImageData(0, 0, canvas.width, canvas.height).data;
  return { width: canvas.width, height: canvas.height, pixels };
}


const DIAGRAM_WEBP_LIMIT = 16383;


async function diagramWebpFile(svgText) {
  const canvas = await diagramCanvas(svgText);
  if (canvas.width > DIAGRAM_WEBP_LIMIT || canvas.height > DIAGRAM_WEBP_LIMIT) {
    throw new Error('This diagram is too big for WebP to hold. Export it as PNG instead.');
  }
  const file = await new Promise((answer) => canvas.toBlob(answer, 'image/webp'));
  
  if (!file || file.type !== 'image/webp') {
    throw new Error('This window cannot write WebP. Export it as PNG instead.');
  }
  return file;
}


const DIAGRAM_JPEG_LIMIT = 65500;


const DIAGRAM_JPEG_QUALITY = 0.92;


async function diagramJpegFile(svgText) {
  const canvas = await diagramCanvas(svgText);
  if (canvas.width > DIAGRAM_JPEG_LIMIT || canvas.height > DIAGRAM_JPEG_LIMIT) {
    throw new Error('This diagram is too big for JPEG to hold. Export it as PNG instead.');
  }
  const file = await new Promise((answer) => canvas.toBlob(answer, 'image/jpeg', DIAGRAM_JPEG_QUALITY));
  
  if (!file || file.type !== 'image/jpeg') {
    throw new Error('This window cannot write JPEG. Export it as PNG instead.');
  }
  return file;
}


const diagramPrint = document.getElementById('diagramPrint');


let diagramPrinting = false;


function clearDiagramPrint() {
  if (diagramPrint) diagramPrint.innerHTML = '';
  document.body.classList.remove('leaf-paper-diagram');
  if (!diagramPrinting) return;
  diagramPrinting = false;
  if (window.leafHoldAppearance) window.leafHoldAppearance(false);
}


window.leafDiagramPrinted = () => clearDiagramPrint();




function printDiagramAsPdf(drawing, path) {
  if (!diagramPrint) throw new Error('This window cannot print a diagram.');
  diagramPrint.innerHTML = drawing;
  const drawn = diagramPrint.firstElementChild;
  if (!drawn) {
    clearDiagramPrint();
    throw new Error('That diagram could not be printed.');
  }
  document.body.classList.add('leaf-paper-diagram');
  
  diagramPrinting = true;
  if (window.leafHoldAppearance) window.leafHoldAppearance(true);
  const box = drawn.getBoundingClientRect();
  send({
    command: 'printDiagramPdf',
    path,
    width: Math.max(Math.round(box.width), 1),
    height: Math.max(box.height, 1),
  });
}


const diagramExportsWaiting = new Map();
let diagramExportToken = 0;


function exportDiagram(source, format) {
  if (!source) return;
  closeFlowMenu();
  diagramExportToken += 1;
  diagramExportsWaiting.set(diagramExportToken, source);
  const ask = { command: 'pickDiagramPath', token: diagramExportToken };
  if (format) ask.format = format;
  send(ask);
}


function openDiagramExportMenu(x, y, source, host) {
  openFlowMenuWith(
    x,
    y,
    DIAGRAM_EXPORTS.map((kind) => ({
      label: kind.label,
      hint: kind.hint,
      run: () => exportDiagram(source, kind.id),
    })),
    host,
  );
}


function openSaveFormatMenu(button, pick) {
  const formats = window.__leafDocumentFormats || [];
  if (!formats.length) return false;
  const spot = button.getBoundingClientRect();
  openFlowMenuWith(
    spot.left,
    spot.bottom + 6,
    formats.map((format) => ({ label: format.label, run: () => pick(format.ext) })),
    appSurface,
  );
  return true;
}


function beginDiagramExport(source, button, host) {
  if (!source) return;
  if (!isMacPlatform) {
    exportDiagram(source);
    return;
  }
  const spot = button.getBoundingClientRect();
  openDiagramExportMenu(spot.left, spot.bottom + 6, source, host);
}


window.leafDiagramPathPicked = (token, path) => {
  const source = diagramExportsWaiting.get(token);
  if (source === undefined) return;
  diagramExportsWaiting.delete(token);
  const text = String(path);
  const dot = text.lastIndexOf('.');
  const kind = dot < 0 ? '' : text.slice(dot + 1).toLowerCase();
  
  const row = DIAGRAM_EXPORTS.find((one) => one.endings.includes(kind));
  if (!row) {
    const names = DIAGRAM_EXPORTS.map((one) => one.label).join(', ');
    leafToast('A diagram is written as ' + names + '. Nothing was written.', 'error');
    return;
  }
  exportDiagramAs(row.id, source, path);
};


async function postDiagramExport(kind, type, path, body, width, height) {
  
  if ((body.size === undefined ? body.length : body.size) > MAX_DIAGRAM_BODY_BYTES) {
    throw new Error('That diagram is too big to export.');
  }
  
  if (!window.__leafDiagramExportEndpoint) throw new Error('That diagram could not be exported.');
  let query = 'format=' + encodeURIComponent(kind) + '&target=' + encodeURIComponent(path);
  if (kind === 'png') query += '&width=' + width + '&height=' + height;
  const response = await fetch(window.__leafDiagramExportEndpoint + '?' + query, {
    method: 'POST',
    headers: { 'Content-Type': type },
    body,
  });
  if (!response.ok) throw new Error('That diagram could not be exported.');
}


const MAX_DIAGRAM_BODY_BYTES = 128 * 1024 * 1024;


async function exportDiagramAs(kind, source, path) {
  try {
    if (kind === 'md') {
      send({ command: 'exportDiagram', format: 'md', path, data: '```mermaid\n' + source + '\n```\n' });
      return;
    }
    const drawing = await diagramDrawingSvg(source);
    if (!drawing) return;
    if (kind === 'pdf') {
      printDiagramAsPdf(drawing, path);
      return;
    }
    if (kind === 'webp') {
      await postDiagramExport(kind, 'image/webp', path, await diagramWebpFile(drawing));
      return;
    }
    if (kind === 'jpg') {
      await postDiagramExport(kind, 'image/jpeg', path, await diagramJpegFile(drawing));
      return;
    }
    
    const picture = await diagramPngPixels(drawing);
    await postDiagramExport(kind, 'application/octet-stream', path, picture.pixels, picture.width, picture.height);
  } catch (error) {
    leafToast((error && error.message) || 'That diagram could not be exported.', 'error');
  }
}

