let windowDragPressedAtX = null;
let windowDragPressedAtY = null;
function dragWindowFrom(bar) {
  if (!bar) return;
  bar.addEventListener('mousedown', (event) => {
    const wasX = windowDragPressedAtX;
    const wasY = windowDragPressedAtY;
    windowDragPressedAtX = null;
    windowDragPressedAtY = null;
    if (event.button !== 0 || !event.target || event.target.closest('button, a, input, select, textarea, [role="tab"], .tab, .window-controls, .update-menu')) return;
    windowDragPressedAtX = window.screenX;
    windowDragPressedAtY = window.screenY;
    const windowStayedPut = window.screenX === wasX && window.screenY === wasY;
    send({ command: event.detail === 2 && windowStayedPut ? 'windowToggleMaximize' : 'windowDrag' });
  });
}


const winMinimizeButton = document.getElementById('winMinimize');
const winMaximizeButton = document.getElementById('winMaximize');
const winCloseButton = document.getElementById('winClose');

if (window.__leafFrameless || window.__leafMacFrame) {
  document.body.classList.add('frameless');
  
  if (window.__leafMacFrame) document.body.classList.add('mac-frame');
  const windowControls = document.getElementById('windowControls');
  if (windowControls) {
    windowControls.hidden = false;
    windowControls.setAttribute('aria-hidden', 'false');
    
    const lead = window.__leafMacFrame && document.querySelector('.app-bar-lead');
    if (lead) lead.prepend(windowControls);
  }
  const winButton = (el, command) => {
    if (el) el.addEventListener('click', (event) => send({ command: typeof command === 'function' ? command(event) : command }));
  };
  winButton(winMinimizeButton, 'windowMinimize');
  
  winButton(winMaximizeButton, (event) =>
    document.body.classList.contains('is-fullscreen') || (window.__leafMacFrame && !event.altKey)
      ? 'windowToggleFullscreen'
      : 'windowToggleMaximize');
  winButton(winCloseButton, 'windowClose');
  
  if (window.__leafFrameless) document.addEventListener('keydown', (event) => {
    if (event.key !== 'F11') return;
    event.preventDefault();
    send({ command: 'windowToggleFullscreen' });
  });
  
  document.addEventListener('keydown', (event) => {
    if (event.isComposing || String(event.key || '').toLowerCase() !== 'q' || event.shiftKey || event.altKey) return;
    const quits = window.__leafMacFrame ? event.metaKey && !event.ctrlKey : event.ctrlKey && !event.metaKey;
    if (!quits) return;
    event.preventDefault();
    send({ command: 'windowClose' });
  });
  
  if (window.__leafMacFrame) leafWinMaxLabel('Enter Full Screen');
  
  dragWindowFrom(appBar);
  
  dragWindowFrom(document.getElementById('flowSheetHead'));
}

if (window.__leafFrameless || window.__leafMacFrame) {
  
  const resizeEdgeAt = (x, y) => {
    if (document.body.classList.contains('is-maximized') || document.body.classList.contains('is-fullscreen')) return null;
    const box = leafAppRect();
    
    const line = appSurface.clientTop || 0;
    const northSouth = y < box.top + line ? 'n' : y >= box.bottom - line ? 's' : '';
    const eastWest = x < box.left + line ? 'w' : x >= box.right - line ? 'e' : '';
    return northSouth + eastWest || null;
  };
  const resizeDrag = (direction, phase, event) =>
    send({ command: 'windowResizeDrag', direction, phase, x: event.screenX, y: event.screenY });
  
  if (window.__leafFrameless) {
    
    document.addEventListener('mousedown', (event) => {
      if (event.button !== 0) return;
      const direction = resizeEdgeAt(event.clientX, event.clientY);
      if (!direction) return;
      
      event.preventDefault();
      resizeDrag(direction, 'start', event);
    });
  } else {
    
    let dragging = null;
    document.addEventListener('pointerdown', (event) => {
      if (event.button !== 0 || !event.isPrimary) return;
      const direction = resizeEdgeAt(event.clientX, event.clientY);
      if (!direction) return;
      event.preventDefault();
      dragging = direction;
      leafHoldPointer(document.documentElement, event.pointerId);
      resizeDrag(direction, 'start', event);
    });
    document.addEventListener('pointermove', (event) => {
      if (dragging) resizeDrag(dragging, 'move', event);
    });
    const endDrag = (event) => {
      if (!dragging) return;
      resizeDrag(dragging, 'end', event);
      dragging = null;
    };
    document.addEventListener('pointerup', endDrag);
    
    document.addEventListener('pointercancel', endDrag);
    document.addEventListener('lostpointercapture', endDrag);
  }
  
  let shape = '';
  document.addEventListener('mousemove', (event) => {
    const direction = resizeEdgeAt(event.clientX, event.clientY);
    const wanted = direction ? `${direction}-resize` : '';
    if (wanted === shape) return;
    shape = wanted;
    
    document.documentElement.style.cursor = wanted;
  });
}

