const HINT_EDGE = 14;
const HINT_GAP = 10;

const HINT_SIDES = ['right', 'left', 'above', 'below'];

const HINT_TAIL_INSET = 18;

const HINT_SETTINGS = (window.__leafSettings && typeof window.__leafSettings === 'object') ? window.__leafSettings : {};

const HINTS_OFF = !!window.__leafSite;
const hintRegistry = new Map();

let hintLaunches = Number(HINT_SETTINGS.hintLaunches) || 0;
const hintsSeen = new Set(Array.isArray(HINT_SETTINGS.hintsSeen) ? HINT_SETTINGS.hintsSeen.filter((name) => typeof name === 'string') : []);
let hintLastLaunch = Number(HINT_SETTINGS.hintLastLaunch) || 0;

let hintBubble = null;
let hintShowing = null;

let hintWatched = null;

let hintTargetWatch = null;

const hintSheets = new Set();
let hintSuspended = null;


function saveHintState() {
  send({ command: 'setHintState', launches: hintLaunches, seen: [...hintsSeen], lastLaunch: hintLastLaunch });
}


function registerHint(name, target, text) {
  if (HINTS_OFF) return;
  hintRegistry.set(name, { name, target, text });
}


function hintTarget(hint) {
  const element = typeof hint.target === 'function' ? hint.target() : hint.target;
  if (!element || !element.isConnected) return null;
  const rect = element.getBoundingClientRect();
  if (rect.width <= 0 || rect.height <= 0) return null;
  if (rect.right <= 0 || rect.bottom <= 0) return null;
  const app = leafAppRect();
  if (rect.left >= app.right || rect.top >= app.bottom) return null;
  return { element, rect };
}


function hintPlacement(target, size, view) {
  const room = {
    right: view.width - HINT_EDGE - (target.right + HINT_GAP) >= size.width,
    left: target.left - HINT_GAP - size.width >= HINT_EDGE,
    above: target.top - HINT_GAP - size.height >= HINT_EDGE,
    below: view.height - HINT_EDGE - (target.bottom + HINT_GAP) >= size.height,
  };
  
  const side = HINT_SIDES.find((name) => room[name]) || HINT_SIDES[HINT_SIDES.length - 1];
  const clamp = (value, extent, span) => Math.max(HINT_EDGE, Math.min(value, extent - HINT_EDGE - span));
  const sideways = side === 'right' || side === 'left';
  let left;
  let top;
  if (sideways) {
    left = side === 'right' ? target.right + HINT_GAP : target.left - HINT_GAP - size.width;
    top = clamp(target.top + target.height / 2 - size.height / 2, view.height, size.height);
  } else {
    left = clamp(target.left + target.width / 2 - size.width / 2, view.width, size.width);
    top = side === 'above' ? target.top - HINT_GAP - size.height : target.bottom + HINT_GAP;
  }
  const span = sideways ? size.height : size.width;
  const center = sideways ? target.top + target.height / 2 : target.left + target.width / 2;
  const origin = sideways ? top : left;
  const inset = Math.min(HINT_TAIL_INSET, span / 2);
  const tail = Math.max(inset, Math.min(center - origin, span - inset));
  return { side, left: Math.round(left), top: Math.round(top), tail: Math.round(tail) };
}


function hintTargetInApp(rect, app) {
  return {
    left: rect.left - app.left,
    right: rect.right - app.left,
    top: rect.top - app.top,
    bottom: rect.bottom - app.top,
    width: rect.width,
    height: rect.height,
  };
}

function hideHintBubble() {
  if (hintWatched) {
    hintWatched.element.removeEventListener('pointerenter', hintWatched.onEnter);
    hintWatched = null;
  }
  if (!hintBubble) return;
  const bubble = hintBubble;
  hintBubble = null;
  hintShowing = null;
  bubble.classList.remove('is-shown');
  
  window.setTimeout(() => bubble.remove(), 400);
}


function retireHint(name) {
  if (!hintsSeen.has(name)) {
    hintsSeen.add(name);
    saveHintState();
  }
  if (hintShowing === name) hideHintBubble();
  if (hintSuspended === name) hintSuspended = null;
  
  disconnectHintTargetWatch(name);
}


function hintIsMet(name) {
  return hintsSeen.has(name);
}


function suspendHintForSheet(sheet) {
  if (HINTS_OFF || !sheet) return;
  hintSheets.add(sheet);
  if (!hintShowing) return;
  hintSuspended = hintShowing;
  hideHintBubble();
}




function hintSheetsStanding() {
  for (const sheet of [...hintSheets]) {
    if (sheet.hidden || sheet.isConnected === false) hintSheets.delete(sheet);
  }
  return hintSheets.size > 0;
}


function restoreHintAfterSheet(sheet) {
  if (HINTS_OFF) return;
  if (sheet) hintSheets.delete(sheet);
  const name = hintSuspended;
  if (!name || hintSheetsStanding()) return;
  if (hintsSeen.has(name)) {
    hintSuspended = null;
    return;
  }
  const hint = hintRegistry.get(name);
  if (!hint) {
    hintSuspended = null;
    return;
  }
  
  const target = hintTarget(hint);
  if (!target) return;
  hintSuspended = null;
  drawHintBubble(hint, target);
}


function disconnectHintTargetWatch(name) {
  if (!hintTargetWatch) return;
  if (name && hintTargetWatch.name !== name) return;
  hintTargetWatch.observer.disconnect();
  hintTargetWatch = null;
}




function watchHintTarget(name, element) {
  disconnectHintTargetWatch();
  if (typeof ResizeObserver === 'undefined' || !element) return;
  const observer = new ResizeObserver(() => hintTargetChanged(name));
  hintTargetWatch = { name, element, observer };
  observer.observe(element);
}


function hintTargetChanged(name) {
  if (HINTS_OFF || hintsSeen.has(name)) return;
  const hint = hintRegistry.get(name);
  if (!hint) return;
  const there = !!hintTarget(hint);
  
  if (!there && hintShowing === name) {
    hintSuspended = name;
    hideHintBubble();
    return;
  }
  
  if (there && !hintShowing && hintSuspended === name) restoreHintAfterSheet(null);
}

function drawHintBubble(hint, target) {
  hideHintBubble();
  const { element, rect: targetRect } = target;
  const bubble = document.createElement('div');
  bubble.className = 'hint-bubble';
  
  bubble.setAttribute('role', 'status');
  const text = document.createElement('span');
  text.className = 'hint-bubble-text';
  text.textContent = hint.text;
  const tail = document.createElement('span');
  tail.className = 'hint-bubble-tail';
  bubble.appendChild(text);
  bubble.appendChild(tail);
  appSurface.appendChild(bubble);
  const rect = bubble.getBoundingClientRect();
  const app = leafAppRect();
  const placement = hintPlacement(hintTargetInApp(targetRect, app), { width: rect.width, height: rect.height }, { width: app.width, height: app.height });
  bubble.classList.add('is-' + placement.side);
  bubble.style.left = placement.left + 'px';
  bubble.style.top = placement.top + 'px';
  bubble.style.setProperty('--hint-tail', placement.tail + 'px');
  hintBubble = bubble;
  hintShowing = hint.name;
  
  const onEnter = () => retireHint(hint.name);
  hintWatched = { element, onEnter };
  element.addEventListener('pointerenter', onEnter);
  watchHintTarget(hint.name, element);
  
  window.requestAnimationFrame(() => bubble.classList.add('is-shown'));
}


function nextHint() {
  for (const hint of hintRegistry.values()) {
    if (!hintsSeen.has(hint.name)) return hint;
  }
  return null;
}


function hintLaunchIsQuiet(launch) {
  return hintLastLaunch !== 0 && launch < hintLastLaunch + 2;
}


function runHintPass() {
  if (HINTS_OFF) return;
  const hint = nextHint();
  if (!hint) return;
  const target = hintTarget(hint);
  if (!target) return;
  hintLaunches += 1;
  const quiet = hintLaunchIsQuiet(hintLaunches);
  if (!quiet) hintLastLaunch = hintLaunches;
  saveHintState();
  if (!quiet) drawHintBubble(hint, target);
}


window.leafShowHint = (name) => {
  const hint = hintRegistry.get(name);
  if (!hint) return false;
  const target = hintTarget(hint);
  if (!target) return false;
  drawHintBubble(hint, target);
  return true;
};


window.leafResetHints = () => {
  hintsSeen.clear();
  hintLaunches = 0;
  hintLastLaunch = 0;
  hintSheets.clear();
  hintSuspended = null;
  saveHintState();
  hideHintBubble();
  disconnectHintTargetWatch();
  return true;
};






const overflowPanel = document.getElementById('appOverflowPanel');
const appTrailingItems = document.getElementById('appTrailingItems');
const historyActions = document.querySelector('.history-actions');
const appBarLead = document.querySelector('.app-bar-lead');

const windowControls = document.getElementById('windowControls');
const overflowCandidates = [
  {
    el: windowControls,
    home: windowControls && windowControls.parentElement,
    inLead: !!windowControls && windowControls.parentElement === appBarLead,
  },
  { el: document.getElementById('backButton'), home: historyActions, inLead: true },
  { el: document.getElementById('refreshButton'), home: historyActions, inLead: true },
  { el: document.getElementById('forwardButton'), home: historyActions, inLead: true },
  ...Array.from(appActionsItems.children).map((el) => ({ el, home: appActionsItems })),
].filter((entry) => entry.el && entry.home);

const overflowMenuOrder = [
  ...overflowCandidates.filter((entry) => entry.el.id !== 'windowControls'),
  ...overflowCandidates.filter((entry) => entry.el.id === 'windowControls'),
].map((entry) => entry.el);

const overflowHomes = new Map();
for (const { home } of overflowCandidates) {
  if (!overflowHomes.has(home)) overflowHomes.set(home, Array.from(home.children));
}
let refittingAppBar = false;

let overflowChevronUp = false;
function markEmptyActionGroups() {
  for (const group of [historyActions, appActionsItems]) {
    if (group) group.classList.toggle('no-drawn-actions', !Array.from(group.children).some((child) => !child.hidden));
  }
}
function closeOverflowMenu() {
  appTrailing.classList.remove('overflow-open');
  overflowToggle.setAttribute('aria-expanded', 'false');
}

function keyboardInertCopy(el) {
  const copy = el.cloneNode(true);
  const forget = (node) => {
    node.removeAttribute('id');
    for (const child of Array.from(node.children)) forget(child);
  };
  forget(copy);
  copy.setAttribute('aria-hidden', 'true');
  copy.inert = true;
  return copy;
}

function foldIntoPanel({ homes, candidates, panel, menuOrder, fits, skip, chevronUp, setFolded, chevron }) {
  const active = document.activeElement;
  const holdsKeyboard = (el) => !!active && (el === active || el.contains(active));
  
  const held = candidates.find((candidate) => candidate.el.parentElement === panel && holdsKeyboard(candidate.el)) || null;
  const copy = held ? keyboardInertCopy(held.el) : null;
  const measured = (el) => (held && el === held.el ? copy : el);
  const standingHeld = held ? null : candidates.find((candidate) => candidate.el.parentElement !== panel && holdsKeyboard(candidate.el)) || null;
  
  for (const [home, listed] of homes) {
    const children = held ? listed.map(measured) : listed;
    let lastUnlisted = null;
    for (const el of home.children) {
      if (!children.includes(el)) lastUnlisted = el;
    }
    let next = lastUnlisted ? lastUnlisted.nextElementSibling : home.children[0] || null;
    for (const child of children) {
      if (child === next) next = child.nextElementSibling;
      else home.insertBefore(child, next);
    }
  }
  
  const foldedNow = () => panel.children.length - (copy && copy.parentElement ? 1 : 0) > 0;
  for (let index = candidates.length - 1; index >= 0; index -= 1) {
    if (fits(foldedNow())) break;
    const candidate = candidates[index];
    const el = measured(candidate.el);
    
    if (el.hidden || (skip && skip({ ...candidate, el }))) continue;
    
    if (el === copy) {
      copy.remove();
      continue;
    }
    const later = menuOrder.slice(menuOrder.indexOf(candidate.el) + 1);
    panel.insertBefore(el, Array.from(panel.children).find((child) => later.includes(child)) || null);
  }
  
  if (copy && copy.parentElement) {
    copy.replaceWith(held.el);
    held.el.focus({ preventScroll: true });
  }
  const folded = panel.children.length > 0;
  const raisedTheChevron = folded && !chevronUp();
  setFolded(folded);
  
  if (standingHeld && standingHeld.el.parentElement === panel) {
    const target = chevron && chevron.getAttribute('aria-expanded') !== 'true' ? chevron : standingHeld.el;
    target.focus({ preventScroll: true });
  }
  return raisedTheChevron;
}
function foldAppBar() {
  
  const leadIsPinned = appBar.classList.contains('has-rail');
  return foldIntoPanel({
    homes: overflowHomes,
    candidates: overflowCandidates,
    panel: overflowPanel,
    menuOrder: overflowMenuOrder,
    
    fits: () => {
      markEmptyActionGroups();
      return appBar.scrollWidth <= appBar.clientWidth + 1;
    },
    skip: ({ el, inLead }) => el.offsetParent === null || (inLead && leadIsPinned),
    chevronUp: () => overflowChevronUp,
    chevron: overflowToggle,
    setFolded: (folded) => {
      markEmptyActionGroups();
      overflowChevronUp = folded;
      appTrailing.classList.toggle('has-overflow', folded);
      if (!folded) closeOverflowMenu();
    },
  });
}



let appBarLeadOwnWidth = 0;

let appBarLeadPin = null;
function unpinAppBarLead() {
  if (!appBarLead || appBarLeadOwnWidth || appBarLeadPin) return;
  appBarLeadPin = { width: appBarLead.style.width || '', minWidth: appBarLead.style.minWidth || '' };
  appBarLead.style.width = 'auto';
  appBarLead.style.minWidth = '0px';
}
function readAppBarLeadOwnWidth() {
  if (appBarLeadOwnWidth || !appBarLead) return appBarLeadOwnWidth;
  appBarLeadOwnWidth = appBarLead.getBoundingClientRect().width;
  return appBarLeadOwnWidth;
}
function repinAppBarLead() {
  if (!appBarLead || !appBarLeadPin) return;
  appBarLead.style.width = appBarLeadPin.width;
  appBarLead.style.minWidth = appBarLeadPin.minWidth;
  appBarLeadPin = null;
}
function appBarLeadWidth() {
  if (appBarLeadOwnWidth) return appBarLeadOwnWidth;
  if (!appBarLead) return 0;
  unpinAppBarLead();
  const width = readAppBarLeadOwnWidth();
  repinAppBarLead();
  return width;
}
function forgetAppBarLeadWidth() {
  appBarLeadOwnWidth = 0;
}

function floorAppBarLead() {
  if (!appBarLead) return;
  const width = appBarLeadWidth();
  if (width) appBarLead.style.minWidth = `${width}px`;
}
function refitAppBar() {
  
  if (refittingAppBar) return;
  refittingAppBar = true;
  try {
    
    if (foldAppBar()) foldAppBar();
  } finally {
    refittingAppBar = false;
    
    if (!libraryPaneIsMoving()) {
      forgetAppBarLeadWidth();
      floorAppBarLead();
    }
    restTabGroupsAtEnd();
  }
}
