const PAGE_EXPORT_CONTROLS = '.code-copy, .image-lane-corner, .mermaid-tools, .mermaid-view-controls, .mermaid-zoom, .diagram-close, .docs-pager';



const PAGE_EXPORT_WRAPPER_OPEN = '<div class="app-surface"><main class="reader-shell has-document"><div class="reader-layout reader-layout-no-minimap">';
const PAGE_EXPORT_WRAPPER_CLOSE = '</div></main></div>';

const BOOK_EXPORT_KEPT_LINK = /^(https?:|mailto:|#)/i;

function pageExportMarkup(asBook) {
  
  if (readingIsContainedPage()) return asBook ? containedPageBookMarkup() : containedPageExportMarkup();
  const drawn = app ? app.querySelector('.document-body') : null;
  if (!drawn) return '';
  const copy = drawn.cloneNode(true);
  
  copy.removeAttribute('style');
  copy.querySelectorAll(PAGE_EXPORT_CONTROLS).forEach((control) => control.remove());
  drawCodeFencesIn(copy);
  
  copy.querySelectorAll('img').forEach(restoreMissingImage);
  if (!asBook) return PAGE_EXPORT_WRAPPER_OPEN + copy.outerHTML + PAGE_EXPORT_WRAPPER_CLOSE;
  return PAGE_EXPORT_WRAPPER_OPEN + bookExportForm(copy) + PAGE_EXPORT_WRAPPER_CLOSE;
}

function bookExportForm(copy) {
  copy.querySelectorAll('a').forEach((link) => {
    const href = link.getAttribute('href');
    if (href !== null && !BOOK_EXPORT_KEPT_LINK.test(href.trim())) link.removeAttribute('href');
  });
  ['img', 'source'].forEach((tag) => copy.querySelectorAll(tag).forEach((picture) => picture.removeAttribute('srcset')));
  return new XMLSerializer().serializeToString(copy);
}

function containedPageBookMarkup() {
  const clone = containedPageExportDocument(siteFrameDocument());
  const body = clone && clone.querySelector ? clone.querySelector('body') : null;
  if (!body) return '';
  ['script', 'link', 'noscript'].forEach((tag) => body.querySelectorAll(tag).forEach((element) => element.remove()));
  [body, ...body.querySelectorAll('*')].forEach((element) => {
    element.getAttributeNames().filter((name) => /^on/i.test(name)).forEach((name) => element.removeAttribute(name));
  });
  const block = document.createElement('div');
  while (body.firstChild) block.appendChild(body.firstChild);
  return bookExportForm(block);
}

window.leafExportPageHtml = (path, asBook, book) => {
  const markup = pageExportMarkup(asBook === true);
  if (!markup) return;
  
  const sheet = mermaidSheetHolder;
  const root = document.documentElement;
  const theme = root.dataset.leafTheme || '';
  const answer = {
    command: 'exportPageHtml',
    path: String(path),
    markup,
    sheet: sheet ? sheet.textContent || '' : '',
    theme,
    appearance: root.dataset.leafAppearance || '',
    title: (currentState && currentState.document && currentState.document.title) || '',
  };
  if (asBook === true) answer.kept = bookSheetVerdict(markup, book, theme);
  send(answer);
};

function bookSheetVerdict(markup, book, theme) {
  const selectors = book && Array.isArray(book.selectors) ? book.selectors : [];
  let drawn = null;
  try {
    drawn = new DOMParser().parseFromString(String(book.opening) + markup + String(book.closing), 'application/xhtml+xml');
  } catch (_) {
    drawn = null;
  }
  
  if (!drawn || !drawn.documentElement || drawn.getElementsByTagName('parsererror').length) return '1'.repeat(selectors.length);
  drawn.documentElement.setAttribute('data-leaf-theme', theme);
  return selectors
    .map((selector) => {
      try {
        return drawn.querySelector(selector) ? '1' : '0';
      } catch (_) {
        return '1';
      }
    })
    .join('');
}
