let renamePath = null;
let renameSettled = false;

let nameBoxAction = 'rename';

let nameBoxMovesThePane = false;
function fileBaseName(path) {
  const parts = (path || '').split(/[\\/]/);
  return parts[parts.length - 1] || path || '';
}
