const MERMAID_SCALE_SEED = '--lt-primary';
const MERMAID_SCALE_STEPS = 12;
const MERMAID_SCALE_HUE_STEP = 150;

const MERMAID_SCALE_SHAPE = {
  light: { luminance: 0.45, minSaturation: 0.42, maxSaturation: 0.85 },
  dark: { luminance: 0.12, minSaturation: 0.38, maxSaturation: 0.85 },
};






const MERMAID_INK_MAP = {
  taskTextColor: ['--lt-primary'],
  taskTextLightColor: ['--lt-primary'],
  sequenceNumberColor: ['--lt-muted-foreground'],
  errorTextColor: ['--lt-editor-code-background'],
  quadrantPointTextFill: ['--lt-surface-muted', '--lt-surface-sunken'],
};


const MERMAID_INK_CANDIDATES = [
  '--lt-markdown-foreground',
  '--lt-markdown-background',
  '--lt-primary-foreground',
  '--lt-accent-foreground',
  '--lt-success-foreground',
  '--lt-danger-foreground',
];


const MERMAID_GANTT_STATE_INKS = [
  ['taskText', '--lt-primary'],
  ['activeText', '--lt-accent'],
  ['doneText', '--lt-success'],
  ['critText', '--lt-danger'],
  ['activeCritText', '--lt-danger'],
  ['doneCritText', '--lt-danger'],
];
const MERMAID_GANTT_SECTIONS = 4;


const MERMAID_XYCHART_COLOR_MAP = {
  backgroundColor: '--lt-markdown-background',
  titleColor: '--lt-markdown-heading',
  xAxisLabelColor: '--lt-markdown-foreground',
  xAxisTitleColor: '--lt-markdown-foreground',
  xAxisTickColor: '--lt-border-strong',
  xAxisLineColor: '--lt-border-strong',
  yAxisLabelColor: '--lt-markdown-foreground',
  yAxisTitleColor: '--lt-markdown-foreground',
  yAxisTickColor: '--lt-border-strong',
  yAxisLineColor: '--lt-border-strong',
};


const MERMAID_PLOT_TOKENS = ['--lt-primary', '--lt-accent', '--lt-success', '--lt-warning', '--lt-danger', '--lt-done'];

function themeTokenValue(style, token) {
  return (style.getPropertyValue(token) || '').trim();
}

function colorRgb(color) {
  const value = String(color || '').trim();
  const hex = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(value);
  if (hex) {
    const digits = hex[1].length === 3 ? hex[1].replace(/./g, '$&$&') : hex[1];
    const channels = parseInt(digits, 16);
    return [(channels >> 16) & 255, (channels >> 8) & 255, channels & 255, 1];
  }
  const rgb = /^rgb\(\s*(\d+(?:\.\d+)?)\s*,\s*(\d+(?:\.\d+)?)\s*,\s*(\d+(?:\.\d+)?)\s*\)$/i.exec(value);
  const rgba = /^rgba\(\s*(\d+(?:\.\d+)?)\s*,\s*(\d+(?:\.\d+)?)\s*,\s*(\d+(?:\.\d+)?)\s*,\s*(\d+(?:\.\d+)?)\s*\)$/i.exec(value);
  const matched = rgb || rgba;
  if (!matched) return null;
  const channels = matched.slice(1, 4).map(Number);
  const alpha = rgba ? Number(matched[4]) : 1;
  if (channels.some((channel) => channel < 0 || channel > 255) || alpha < 0 || alpha > 1) return null;
  return [...channels, alpha];
}


function colorLuminance(color) {
  const rgb = colorRgb(color);
  if (!rgb) return null;
  const channel = (byte) => {
    const part = byte / 255;
    return part <= 0.03928 ? part / 12.92 : Math.pow((part + 0.055) / 1.055, 2.4);
  };
  return 0.2126 * channel(rgb[0]) + 0.7152 * channel(rgb[1]) + 0.0722 * channel(rgb[2]);
}

function colorContrast(a, b) {
  const first = colorLuminance(a);
  const second = colorLuminance(b);
  if (first == null || second == null) return null;
  return (Math.max(first, second) + 0.05) / (Math.min(first, second) + 0.05);
}


function inkOn(style, fills) {
  if (!fills.length) return '';
  let best = '';
  let bestRatio = 0;
  for (const token of MERMAID_INK_CANDIDATES) {
    const ink = themeTokenValue(style, token);
    if (!ink) continue;
    let worst = Infinity;
    for (const fill of fills) {
      const ratio = colorContrast(fill, ink);
      if (ratio == null) {
        worst = 0;
        break;
      }
      worst = Math.min(worst, ratio);
    }
    if (worst > bestRatio) {
      best = ink;
      bestRatio = worst;
    }
  }
  return best;
}


function paintChartValueLabels(root) {
  if (!root || !root.querySelectorAll) return;
  const style = window.getComputedStyle(document.documentElement);
  const axisLabel = root.querySelectorAll('g.left-axis text')[0] || root.querySelectorAll('g.bottom-axis text')[0];
  const axisSize = Number.parseFloat(axisLabel && axisLabel.getAttribute('font-size')) || 14;
  for (const group of root.querySelectorAll('g.plot > g')) {
    if (!/(?:^|\s)bar-plot-\d+(?:\s|$)/.test(group.getAttribute('class') || '')) continue;
    const fills = Array.from(group.querySelectorAll('rect'))
      .map((bar) => bar.getAttribute('fill'))
      .filter(Boolean);
    const ink = inkOn(style, fills);
    for (const label of group.querySelectorAll('text')) {
      if (ink) label.setAttribute('fill', ink);
      const size = Number.parseFloat(label.getAttribute('font-size'));
      if (size > axisSize) label.setAttribute('font-size', axisSize + 'px');
    }
  }
}


function standBarSeriesSideBySide(root) {
  if (!root || !root.querySelectorAll) return;
  for (const plot of root.querySelectorAll('g.plot')) {
    if (plot.dataset.barSeriesStood) continue;
    const series = Array.from(plot.children).filter((group) => /(?:^|\s)bar-plot-\d+(?:\s|$)/.test(group.getAttribute('class') || ''));
    if (series.length < 2) continue;
    const bars = series.flatMap((group) => Array.from(group.querySelectorAll('rect')));
    const dimensions = bars.map((bar) => ({
      width: Number.parseFloat(bar.getAttribute('width')),
      height: Number.parseFloat(bar.getAttribute('height')),
    }));
    if (!bars.length || dimensions.some(({ width, height }) => !(width > 0) || !(height > 0))) continue;
    const allEqual = (name) => dimensions.every((one) => one[name] === dimensions[0][name]);
    const widthsEqual = allEqual('width');
    const heightsEqual = allEqual('height');
    let axis;
    if (widthsEqual && !heightsEqual) axis = { position: 'x', size: 'width' };
    else if (heightsEqual && !widthsEqual) axis = { position: 'y', size: 'height' };
    else if (widthsEqual && heightsEqual) axis = root.querySelectorAll('g.top-axis').length ? { position: 'y', size: 'height' } : { position: 'x', size: 'width' };
    else continue;
    series.forEach((group, at) => {
      const firstBar = group.querySelectorAll('rect')[0];
      const step = Number.parseFloat(firstBar && firstBar.getAttribute(axis.size)) / series.length;
      for (const bar of group.querySelectorAll('rect')) {
        const full = Number.parseFloat(bar.getAttribute(axis.size));
        const size = full / series.length;
        const position = Number.parseFloat(bar.getAttribute(axis.position));
        if (!Number.isFinite(position)) continue;
        bar.setAttribute(axis.size, size);
        bar.setAttribute(axis.position, position + at * size);
      }
      for (const label of group.querySelectorAll('text')) {
        const position = Number.parseFloat(label.getAttribute(axis.position));
        if (Number.isFinite(position) && Number.isFinite(step)) label.setAttribute(axis.position, position + at * step);
        const size = Number.parseFloat(label.getAttribute('font-size'));
        if (Number.isFinite(size)) label.setAttribute('font-size', size / series.length + 'px');
      }
    });
    plot.dataset.barSeriesStood = 'true';
  }
}


function readableInk(style, fillTokens) {
  return inkOn(style, fillTokens.map((token) => themeTokenValue(style, token)).filter(Boolean));
}

function colorChannels(color) {
  const rgb = colorRgb(color);
  return rgb ? rgb.slice(0, 3) : null;
}


function colorHueSaturation(channels) {
  const [r, g, b] = channels.map((byte) => byte / 255);
  const high = Math.max(r, g, b);
  const low = Math.min(r, g, b);
  const span = high - low;
  const lightness = (high + low) / 2;
  if (!span) return [0, 0];
  const saturation = span / (1 - Math.abs(2 * lightness - 1));
  let hue;
  if (high === r) hue = ((g - b) / span) % 6;
  else if (high === g) hue = (b - r) / span + 2;
  else hue = (r - g) / span + 4;
  return [((hue * 60) + 360) % 360, Math.min(1, saturation)];
}

function hslColor(hue, saturation, lightness) {
  const chroma = (1 - Math.abs(2 * lightness - 1)) * saturation;
  const section = ((hue % 360) + 360) % 360 / 60;
  const second = chroma * (1 - Math.abs((section % 2) - 1));
  const base = [
    [chroma, second, 0], [second, chroma, 0], [0, chroma, second],
    [0, second, chroma], [second, 0, chroma], [chroma, 0, second],
  ][Math.floor(section) % 6];
  const offset = lightness - chroma / 2;
  return '#' + base
    .map((part) => Math.round((part + offset) * 255).toString(16).padStart(2, '0'))
    .join('');
}


function colorAtLuminance(hue, saturation, luminance) {
  let low = 0;
  let high = 1;
  let color = hslColor(hue, saturation, 0.5);
  for (let pass = 0; pass < 12; pass += 1) {
    const middle = (low + high) / 2;
    color = hslColor(hue, saturation, middle);
    if (colorLuminance(color) < luminance) low = middle;
    else high = middle;
  }
  return color;
}


function mermaidCategoricalScale(style, darkMode) {
  const seed = colorChannels(themeTokenValue(style, MERMAID_SCALE_SEED));
  if (!seed) return [];
  const shape = darkMode ? MERMAID_SCALE_SHAPE.dark : MERMAID_SCALE_SHAPE.light;
  const [hue, saturation] = colorHueSaturation(seed);
  const spread = Math.min(shape.maxSaturation, Math.max(shape.minSaturation, saturation));
  const scale = [];
  for (let step = 0; step < MERMAID_SCALE_STEPS; step += 1) {
    scale.push(colorAtLuminance(hue + step * MERMAID_SCALE_HUE_STEP, spread, shape.luminance));
  }
  return scale;
}


function mermaidSeriesPalette(style) {
  const seed = colorChannels(themeTokenValue(style, MERMAID_SCALE_SEED));
  const background = themeTokenValue(style, '--lt-markdown-background');
  const backgroundLuminance = colorLuminance(background);
  if (!seed || backgroundLuminance == null) return [];
  const shape = backgroundLuminance > 0.18 ? MERMAID_SCALE_SHAPE.light : MERMAID_SCALE_SHAPE.dark;
  const [hue, saturation] = colorHueSaturation(seed);
  const spread = Math.min(shape.maxSaturation, Math.max(shape.minSaturation, saturation));
  const luminance = backgroundLuminance > 0.18
    ? Math.max(0, (backgroundLuminance + 0.05) / 3.3 - 0.05)
    : Math.min(1, 3.3 * (backgroundLuminance + 0.05) - 0.05);
  return Array.from({ length: MERMAID_PLOT_TOKENS.length }, (_, step) => (
    colorAtLuminance(hue + step * MERMAID_SCALE_HUE_STEP, spread, luminance)
  ));
}


const MERMAID_C4_RELATION_COLOR = '#444444';

function mermaidC4RelationCss(style) {
  const ink = themeTokenValue(style, '--lt-muted-foreground');
  if (!ink) return '';
  return [
    'text[fill="' + MERMAID_C4_RELATION_COLOR + '"] { fill: ' + ink + ' !important; }',
    'line[stroke="' + MERMAID_C4_RELATION_COLOR + '"] { stroke: ' + ink + ' !important; }',
  ].join('\n');
}


function mermaidSubgraphTitleCss() {
  return '.cluster-label div { white-space: nowrap !important; width: max-content !important; max-width: none !important; }';
}


function mermaidGanttStateCss(style) {
  const rules = [];
  for (const [selector, fillToken] of MERMAID_GANTT_STATE_INKS) {
    const ink = readableInk(style, [fillToken]);
    if (!ink) continue;
    const selectors = [];
    for (let section = 0; section < MERMAID_GANTT_SECTIONS; section += 1) {
      selectors.push('.' + selector + section);
    }
    rules.push(selectors.join(', ') + ' { fill: ' + ink + ' !important; }');
  }
  return rules.join('\n');
}


function mermaidThemeVariables() {
  const style = window.getComputedStyle(document.documentElement);
  const variables = { darkMode: document.documentElement.dataset.theme === 'dark' };
  for (const [name, token] of Object.entries(MERMAID_COLOR_MAP)) {
    const value = themeTokenValue(style, token);
    if (value) variables[name] = value;
  }
  for (const [name, fillTokens] of Object.entries(MERMAID_INK_MAP)) {
    const value = readableInk(style, fillTokens);
    if (value) variables[name] = value;
  }
  const xyChart = {};
  for (const [name, token] of Object.entries(MERMAID_XYCHART_COLOR_MAP)) {
    const value = themeTokenValue(style, token);
    if (value) xyChart[name] = value;
  }
  const plot = mermaidSeriesPalette(style);
  if (!plot.length) plot.push(...MERMAID_PLOT_TOKENS.map((token) => themeTokenValue(style, token)).filter(Boolean));
  if (plot.length) xyChart.plotColorPalette = plot.join(', ');
  if (Object.keys(xyChart).length) variables.xyChart = xyChart;

  
  const scale = mermaidCategoricalScale(style, variables.darkMode);
  scale.forEach((color, index) => {
    variables['cScale' + index] = color;
    variables['cScaleLabel' + index] = inkOn(style, [color]);
    if (index < 8) {
      variables['git' + index] = color;
      variables['gitBranchLabel' + index] = inkOn(style, [color]);
      variables['fillType' + index] = color;
    }
  });
  if (scale.length) {
    
    variables.pieSectionTextColor = inkOn(style, scale);
    
    variables.pieOpacity = '1';
  }

  return variables;
}


function mermaidFontFamily() {
  const style = window.getComputedStyle(document.documentElement);
  return themeTokenValue(style, '--reading-font') || "'Noto Sans', sans-serif";
}


function mermaidRuntimeConfig(options) {
  const htmlLabels = !options || options.htmlLabels !== false;
  const style = window.getComputedStyle(document.documentElement);
  const fontFamily = (options && options.fontFamily) || mermaidFontFamily();
  const subgraphTitleGap = parseFloat(themeTokenValue(style, '--lt-space-8')) || 0;
  const themeVariables = mermaidThemeVariables();
  themeVariables.fontFamily = fontFamily;
  return {
    startOnLoad: false,
    securityLevel: 'strict',
    htmlLabels,
    flowchart: { htmlLabels, subGraphTitleMargin: { top: subgraphTitleGap, bottom: subgraphTitleGap } },
    
    themeCSS: [mermaidGanttStateCss(style), mermaidC4RelationCss(style), mermaidSubgraphTitleCss()]
      .filter(Boolean)
      .join('\n'),
    
    theme: document.documentElement.dataset.theme === 'dark' ? 'dark' : 'default',
    fontFamily,
    themeVariables,
  };
}


async function chartPlotsFromSource(mermaid, source) {
  if (!source || !/\bxychart\b/.test(source) || !mermaid || !mermaid.mermaidAPI) return null;
  try {
    const diagram = await mermaid.mermaidAPI.getDiagramFromText(source);
    const db = diagram && diagram.db;
    if (!db || typeof db.getXYChartData !== 'function') return null;
    const plots = db.getXYChartData().plots;
    return Array.isArray(plots) ? plots : null;
  } catch (error) {
    return null;
  }
}


function labelBarSeriesFromOwnData(root, plots) {
  if (!root || !root.querySelectorAll || !Array.isArray(plots)) return;
  for (const group of root.querySelectorAll('g.plot > g')) {
    const named = /(?:^|\s)bar-plot-(\d+)(?:\s|$)/.exec(group.getAttribute('class') || '');
    if (!named) continue;
    const plot = plots[Number(named[1])];
    if (!plot || plot.type !== 'bar' || !Array.isArray(plot.data)) continue;
    const labels = group.querySelectorAll('text');
    if (labels.length !== plot.data.length) continue;
    plot.data.forEach((point, at) => {
      const value = Array.isArray(point) ? point[1] : undefined;
      if (value != null) labels[at].textContent = String(value);
    });
  }
}
let mermaidLoadPromise = null;
let katexLoadPromise = null;

function loadMermaid() {
  if (window.mermaid) {
    return Promise.resolve(window.mermaid);
  }
  if (mermaidLoadPromise) {
    return mermaidLoadPromise;
  }
  mermaidLoadPromise = new Promise((resolve, reject) => {
    const script = document.createElement('script');
    script.src = MERMAID_SCRIPT_URL;
    
    script.crossOrigin = 'anonymous';
    script.async = true;
    script.onload = () => {
      if (window.mermaid) {
        resolve(window.mermaid);
        return;
      }
      reject(new Error('Mermaid runtime loaded without exposing window.mermaid'));
    };
    script.onerror = () => reject(new Error('Mermaid runtime failed to load'));
    document.head.appendChild(script);
  });
  return mermaidLoadPromise;
}


let mermaidIconsRegistered = false;
function registerMermaidIcons(mermaid) {
  if (mermaidIconsRegistered || typeof mermaid.registerIconPacks !== 'function') return;
  mermaidIconsRegistered = true;
  mermaid.registerIconPacks([{ name: LEAF_MERMAID_ICON_PREFIX, icons: LEAF_MERMAID_ICONS }]);
}


const MERMAID_FALLBACK_ICON = LEAF_MERMAID_ICON_PREFIX + ':missing-image';

function mermaidHasIcon(name) {
  const at = (name || '').indexOf(':');
  if (at < 0) return false;
  return (
    name.slice(0, at) === LEAF_MERMAID_ICON_PREFIX &&
    Object.prototype.hasOwnProperty.call(LEAF_MERMAID_ICONS.icons, name.slice(at + 1))
  );
}


const mermaidPictureAnswers = new Map();
function mermaidPictureDraws(url) {
  let answer = mermaidPictureAnswers.get(url);
  if (!answer) {
    answer = new Promise((resolve) => {
      const probe = new Image();
      
      probe.onload = () => (probe.decode ? probe.decode().then(() => resolve(true), () => resolve(false)) : resolve(true));
      probe.onerror = () => resolve(false);
      probe.src = url;
    });
    mermaidPictureAnswers.set(url, answer);
  }
  return answer;
}


function mermaidRewriteTyped(source, rewrite) {
  let out = '';
  let rest = source;
  for (;;) {
    const open = rest.indexOf('@{');
    if (open < 0) return out + rest;
    out += rest.slice(0, open + 2);
    const body = rest.slice(open + 2);
    let close = -1;
    let quoted = false;
    for (let at = 0; at < body.length; at += 1) {
      const char = body[at];
      if (char === '"') quoted = !quoted;
      else if (char === '}' && !quoted) {
        close = at;
        break;
      }
    }
    if (close < 0) return out + body;
    out += mermaidRewriteTypedBody(body.slice(0, close), rewrite) + '}';
    rest = body.slice(close + 1);
  }
}

const MERMAID_TYPED_KEY_RE = /^(\s*)([A-Za-z_][\w-]*)\s*:\s*([\s\S]*?)(\s*)$/;
function mermaidRewriteTypedBody(body, rewrite) {
  const parts = [];
  let start = 0;
  let quoted = false;
  for (let at = 0; at <= body.length; at += 1) {
    const char = body[at];
    if (char === '"') quoted = !quoted;
    else if ((at === body.length || char === ',') && !quoted) {
      parts.push(body.slice(start, at));
      start = at + 1;
    }
  }
  return parts
    .map((part) => {
      const named = MERMAID_TYPED_KEY_RE.exec(part);
      if (!named) return part;
      const value = named[3].replace(/^"([\s\S]*)"$/, '$1');
      const swap = rewrite(named[2], value);
      
      return swap == null ? part : named[1] + swap + named[4];
    })
    .join(',');
}


async function mermaidDrawableSource(source) {
  if (!source || source.indexOf('@{') < 0) return source;
  const pictures = [];
  mermaidRewriteTyped(source, (key, value) => {
    if (key === 'img' && value) pictures.push(value);
    return null;
  });
  const dead = new Set();
  if (pictures.length) {
    const draws = await Promise.all(pictures.map(mermaidPictureDraws));
    pictures.forEach((url, at) => {
      if (!draws[at]) dead.add(url);
    });
  }
  return mermaidRewriteTyped(source, (key, value) => {
    if (key === 'icon') return mermaidHasIcon(value) ? null : 'icon: "' + MERMAID_FALLBACK_ICON + '"';
    
    if (key === 'img' && dead.has(value)) return 'icon: "' + MERMAID_FALLBACK_ICON + '"';
    return null;
  });
}


const mermaidRenderCache = new Map();
const MERMAID_CACHE_CAP = 200;

function mermaidCacheKey(source) {
  const root = document.documentElement.dataset;
  return (root.themeFamily || '') + '\n' + (root.theme || '') + '\n' + source;
}

function mermaidHeightKey(source) {
  const body = app.querySelector('.document-body');
  const width = body ? Math.round(body.getBoundingClientRect().width) : 0;
  return width + '\n' + mermaidCacheKey(source);
}

const mermaidDrawnHeights = new Map();

function mermaidDocumentPastMemory() {
  const body = app.querySelector('.document-body');
  return !!body && body.querySelectorAll('pre.mermaid').length > MERMAID_CACHE_CAP;
}

const MERMAID_NEAR_SCREENS = 1;
function mermaidViewHeight() {
  return app.clientHeight || window.innerHeight || 800;
}

function mermaidIsHeld(diagram) {
  return !!diagram.closest('.is-held-below');
}

function mermaidIsNearReader(diagram) {
  if (mermaidIsHeld(diagram)) return false;
  const rect = diagram.getBoundingClientRect();
  const height = mermaidViewHeight();
  const margin = height * MERMAID_NEAR_SCREENS;
  return rect.bottom >= -margin && rect.top <= height + margin;
}

function markMermaidWait(diagram, near) {
  diagram.dataset.diagramWait = near ? 'near' : 'far';
  
  drawMermaidPaintAlways(diagram);
  const known = mermaidDrawnHeights.get(mermaidHeightKey(diagram.__mermaidSource || diagram.textContent));
  
  if (known) {
    diagram.style.height = `${known}px`;
    diagram.style.minHeight = '0px';
  } else {
    diagram.style.removeProperty('height');
    diagram.style.removeProperty('min-height');
  }
}
function renderMermaidDiagrams() {
  
  const body = app.querySelector('.document-body');
  if (body !== mermaidWatchedBody) {
    forgetMermaidWatch();
    mermaidWatchedBody = body;
  }
  
  const candidates = Array.from(app.querySelectorAll('pre.mermaid:not([data-processed="true"]):not([data-mermaid-render="failed"]):not([data-diagram-stage])'));
  if (!candidates.length) {
    return;
  }
  const near = [];
  candidates.forEach((diagram) => {
    
    diagram.__mermaidSource = diagram.textContent;
    const isNear = mermaidIsNearReader(diagram);
    markMermaidWait(diagram, isNear);
    if (isNear) near.push(diagram);
  });
  watchMermaidDiagrams(candidates);
  drawMermaidDiagrams(near);
  mermaidNoteColumnWidth();
  scheduleMermaidWarmPass();
}





const MERMAID_WARM_SETTLE_MS = 400;
let mermaidWarmTimer = 0;

function mermaidWarmCandidates() {
  const body = app.querySelector('.document-body');
  if (!body) return [];
  
  if (mermaidDocumentPastMemory()) return [];
  const waiting = Array.from(body.querySelectorAll('pre.mermaid:not([data-processed="true"]):not([data-mermaid-render="failed"]):not([data-diagram-stage])'));
  return waiting.filter((diagram) => diagram.__mermaidSource != null
    && !mermaidIsHeld(diagram)
    && !mermaidDrawnHeights.has(mermaidHeightKey(diagram.__mermaidSource)));
}
function scheduleMermaidWarmPass() {
  markMinimapWarming();
  if (mermaidWarmTimer) return;
  mermaidWarmTimer = columnTimer(() => {
    mermaidWarmTimer = 0;
    
    if (readerScrolling) return;
    
    if (mermaidExportDrawing) return;
    const queue = mermaidWarmCandidates();
    if (queue.length) drawMermaidDiagrams(queue, true);
  }, MERMAID_WARM_SETTLE_MS);
}

function markMinimapWarming() {
  
  const minimap = currentMinimap();
  if (!minimap) return;
  if (readingHasHeldBlocks() || mermaidWarmCandidates().length) minimap.classList.add('is-loading');
  else minimap.classList.remove('is-loading');
}


let mermaidExportDrawing = 0;

let mermaidExportHolding = false;

function mermaidWaitingForExport() {
  const body = app ? app.querySelector('.document-body') : null;
  if (!body) return [];
  return Array.from(body.querySelectorAll('pre.mermaid')).filter((diagram) => {
    if (diagram.dataset.processed === 'true' || diagram.dataset.mermaidRender === 'failed' || diagram.dataset.diagramStage != null) return false;
    if (diagram.__mermaidSource == null) diagram.__mermaidSource = diagram.textContent;
    return true;
  });
}

const MERMAID_EXPORT_STALLED_ROUNDS = 3;
async function drawEveryMermaidDiagram() {
  mermaidExportDrawing += 1;
  mermaidExportHolding = true;
  try {
    let waiting = mermaidWaitingForExport();
    let stalled = 0;
    while (waiting.length) {
      await drawMermaidDiagrams(waiting);
      const left = mermaidWaitingForExport();
      stalled = left.length >= waiting.length ? stalled + 1 : 0;
      if (stalled >= MERMAID_EXPORT_STALLED_ROUNDS) return;
      waiting = left;
    }
  } finally {
    mermaidExportDrawing -= 1;
  }
}


function fillMermaidClone(preview) {
  for (const box of preview.querySelectorAll('pre.mermaid:not([data-processed="true"]):not([data-mermaid-render="failed"])')) {
    const drawing = mermaidRenderCache.get(mermaidCacheKey(box.textContent));
    if (!drawing) continue;
    box.innerHTML = drawing;
    ensureMermaidSheets(box);
    box.dataset.processed = 'true';
    delete box.dataset.diagramWait;
  }
}

let mermaidColumnWidth = -1;
function mermaidNoteColumnWidth() {
  const body = app.querySelector('.document-body');
  mermaidColumnWidth = body ? Math.round(body.getBoundingClientRect().width) : 0;
}
function mermaidColumnWidthChanged() {
  const body = app.querySelector('.document-body');
  const width = body ? Math.round(body.getBoundingClientRect().width) : 0;
  if (width === mermaidColumnWidth) return;
  mermaidColumnWidth = width;
  if (!body) return;
  for (const diagram of body.querySelectorAll('pre.mermaid:not([data-processed="true"]):not([data-mermaid-render="failed"])')) {
    if (diagram.__mermaidSource != null) markMermaidWait(diagram, diagram.dataset.diagramWait !== 'far');
  }
  scheduleMermaidWarmPass();
}
window.addEventListener('resize', mermaidColumnWidthChanged);


function drawMermaidDiagrams(candidates, warming) {
  
  candidates = candidates.filter((diagram) => !mermaidIsHeld(diagram));
  if (!candidates.length) {
    return;
  }
  const diagrams = [];
  let restored = false;
  candidates.forEach((diagram) => {
    const cached = mermaidRenderCache.get(mermaidCacheKey(diagram.__mermaidSource));
    if (cached) {
      diagram.innerHTML = cached;
      
      ensureMermaidSheets(diagram);
      diagram.dataset.processed = 'true';
      finishMermaidDiagram(diagram);
      addMermaidControls(diagram);
      restored = true;
      return;
    }
    diagrams.push(diagram);
  });
  if (restored) {
    mermaidPageTextChanged();
  }
  if (!diagrams.length) {
    return;
  }
  
  diagrams.sort((a, b) => mermaidReaderDistance(a) - mermaidReaderDistance(b));
  mermaidRenderGeneration += 1;
  return drawMermaidBatches(diagrams, mermaidRenderGeneration, warming);
}


const MERMAID_XLINK_NS = 'http://www.w3.org/1999/xlink';
function claimMermaidLinks(diagram) {
  for (const link of diagram.querySelectorAll('a')) {
    if (link.hasAttribute('href')) continue;
    const target = link.getAttributeNS(MERMAID_XLINK_NS, 'href');
    if (target) link.setAttribute('href', target);
  }
}



const MERMAID_SHEET_ID = 'leaf-mermaid-sheets';
const MERMAID_SHEET_CLASS = 'lt-mmd-';

const MERMAID_SHEET_MARK = String.fromCharCode(0);

const mermaidSheetClasses = new Map();
const mermaidSheetTexts = new Map();

const mermaidLiveSheets = new Set();
const mermaidSheetFrames = new Set();
let mermaidSheetHolder = null;
function mermaidSheetElement() {
  if (!mermaidSheetHolder) {
    mermaidSheetHolder = document.createElement('style');
    mermaidSheetHolder.id = MERMAID_SHEET_ID;
    document.head.appendChild(mermaidSheetHolder);
  }
  return mermaidSheetHolder;
}

function splitMermaidFrames(text) {
  let rules = '';
  const frames = [];
  let at = 0;
  for (;;) {
    const start = text.indexOf('@keyframes', at);
    if (start < 0) {
      rules += text.slice(at);
      return { rules, frames };
    }
    rules += text.slice(at, start);
    let cut = text.indexOf('{', start);
    if (cut < 0) {
      rules += text.slice(start);
      return { rules, frames };
    }
    let depth = 0;
    for (; cut < text.length; cut += 1) {
      if (text[cut] === '{') depth += 1;
      else if (text[cut] === '}') {
        depth -= 1;
        if (!depth) {
          cut += 1;
          break;
        }
      }
    }
    frames.push(text.slice(start, cut));
    at = cut;
  }
}

function keepMermaidSheet(cls) {
  if (mermaidLiveSheets.has(cls)) return;
  mermaidLiveSheets.add(cls);
  mermaidSheetElement().textContent += mermaidSheetTexts.get(cls) || '';
}

function ensureMermaidSheets(node) {
  const svg = node && typeof node.querySelector === 'function' ? node.querySelector('svg') : null;
  const names = svg && svg.getAttribute ? String(svg.getAttribute('class') || '').split(/\s+/) : [];
  for (const name of names) if (mermaidSheetTexts.has(name)) keepMermaidSheet(name);
}

function shareMermaidSheet(diagram) {
  const svg = diagram.querySelector('svg');
  const style = svg ? svg.querySelector('style') : null;
  if (!svg || !style) return;
  const split = splitMermaidFrames(style.textContent || '');
  for (const frame of split.frames) {
    if (mermaidSheetFrames.has(frame)) continue;
    mermaidSheetFrames.add(frame);
    mermaidSheetElement().textContent += frame;
  }
  const id = svg.id;
  const normalized = id ? split.rules.split('#' + id).join(MERMAID_SHEET_MARK) : split.rules;
  let cls = mermaidSheetClasses.get(normalized);
  if (!cls) {
    
    cls = MERMAID_SHEET_CLASS + mermaidSheetClasses.size;
    mermaidSheetClasses.set(normalized, cls);
    mermaidSheetTexts.set(cls, normalized.split(MERMAID_SHEET_MARK).join('.' + cls));
  }
  keepMermaidSheet(cls);
  svg.classList.add(cls);
  style.remove();
}

function forgetMermaidSheets() {
  if (!mermaidLiveSheets.size) return;
  mermaidLiveSheets.clear();
  mermaidSheetElement().textContent = Array.from(mermaidSheetFrames).join('');
}


function skipMermaidPaintOffScreen(diagram, height) {
  
  const around = window.getComputedStyle(diagram);
  const edges = ['padding-top', 'padding-bottom', 'border-top-width', 'border-bottom-width']
    .reduce((sum, name) => sum + (Number.parseFloat(around.getPropertyValue(name)) || 0), 0);
  diagram.style.containIntrinsicSize = `auto ${Math.max(0, Math.round(height - edges))}px`;
  diagram.style.contentVisibility = 'auto';
}
function drawMermaidPaintAlways(diagram) {
  diagram.style.removeProperty('content-visibility');
  diagram.style.removeProperty('contain-intrinsic-size');
}

function finishMermaidDiagram(diagram) {
  claimMermaidLinks(diagram);
  standBarSeriesSideBySide(diagram);
  paintChartValueLabels(diagram);
  delete diagram.dataset.diagramWait;
  
  diagram.style.removeProperty('height');
  diagram.style.removeProperty('min-height');
  drawMermaidPaintAlways(diagram);
  if (mermaidViewObserver) mermaidViewObserver.unobserve(diagram);
  if (diagram.__mermaidSource == null) return;
  const height = Math.round(diagram.getBoundingClientRect().height);
  if (!height) return;
  if (mermaidDrawnHeights.size >= MERMAID_CACHE_CAP) mermaidDrawnHeights.clear();
  mermaidDrawnHeights.set(mermaidHeightKey(diagram.__mermaidSource), height);
  skipMermaidPaintOffScreen(diagram, height);
  watchMermaidForRecycling(diagram);
}


const MERMAID_FAR_SCREENS = 3;
let mermaidRecycleObserver = null;
let mermaidLeavingView = new Set();
function watchMermaidForRecycling(diagram) {
  if (typeof IntersectionObserver === 'undefined') return;
  
  if (!mermaidDocumentPastMemory()) return;
  if (!mermaidRecycleObserver) {
    mermaidRecycleObserver = new IntersectionObserver((entries) => {
      for (const entry of entries) {
        if (entry.isIntersecting) mermaidLeavingView.delete(entry.target);
        else mermaidLeavingView.add(entry.target);
      }
      if (mermaidLeavingView.size) scheduleMermaidPass();
    }, { root: app, rootMargin: `${MERMAID_FAR_SCREENS * 100}% 0px` });
  }
  mermaidRecycleObserver.observe(diagram);
}

function mermaidMayRecycle(diagram) {
  
  if (mermaidExportDrawing || mermaidExportHolding) return false;
  
  if (!mermaidDocumentPastMemory()) return false;
  if (!diagram.isConnected || diagram.dataset.processed !== 'true') return false;
  
  if (diagram.dataset.editingSource === 'true') return false;
  if (diagram.classList.contains('is-moved') || diagram.classList.contains('is-panning')) return false;
  const overlay = diagramOverlayElement();
  if (overlay && overlay.__diagramBlock === diagram) return false;
  if (diagram.__mermaidSource == null) return false;
  
  return mermaidRenderCache.has(mermaidCacheKey(diagram.__mermaidSource))
    && mermaidDrawnHeights.has(mermaidHeightKey(diagram.__mermaidSource));
}

function recycleMermaidDiagram(diagram) {
  if (!mermaidMayRecycle(diagram)) return false;
  if (mermaidRecycleObserver) mermaidRecycleObserver.unobserve(diagram);
  diagram.textContent = diagram.__mermaidSource;
  delete diagram.dataset.processed;
  markMermaidWait(diagram, false);
  if (mermaidViewObserver) mermaidViewObserver.observe(diagram);
  return true;
}


function mermaidPageTextChanged() {
  readerAnchorBlocks = null;
  forgetRenderedText();
  refreshFind();
}


let mermaidViewObserver = null;
let mermaidWatchedBody = null;
let mermaidWaitingNearby = new Set();
let mermaidDrainTimer = 0;
function watchMermaidDiagrams(candidates) {
  if (typeof IntersectionObserver === 'undefined') {
    
    drawMermaidDiagrams(candidates);
    return;
  }
  if (!mermaidViewObserver) {
    mermaidViewObserver = new IntersectionObserver(inThisColumn((entries) => {
      for (const entry of entries) {
        const diagram = entry.target;
        if (diagram.dataset.processed === 'true' || diagram.dataset.mermaidRender === 'failed') {
          mermaidViewObserver.unobserve(diagram);
          continue;
        }
        markMermaidWait(diagram, entry.isIntersecting);
        if (entry.isIntersecting) mermaidWaitingNearby.add(diagram);
        else mermaidWaitingNearby.delete(diagram);
      }
      if (mermaidWaitingNearby.size) scheduleMermaidPass();
    }), { root: app, rootMargin: `${MERMAID_NEAR_SCREENS * 100}% 0px` });
  }
  for (const diagram of candidates) mermaidViewObserver.observe(diagram);
}

function scheduleMermaidPass() {
  if (mermaidDrainTimer) return;
  mermaidDrainTimer = columnTimer(() => {
    mermaidDrainTimer = 0;
    
    if (readerScrolling) return;
    
    if (mermaidExportDrawing) return;
    
    if (!mermaidExportHolding) {
      for (const diagram of mermaidLeavingView) recycleMermaidDiagram(diagram);
      mermaidLeavingView.clear();
    }
    const queue = Array.from(mermaidWaitingNearby).filter((diagram) => diagram.isConnected
      && diagram.dataset.processed !== 'true'
      && diagram.dataset.mermaidRender !== 'failed');
    mermaidWaitingNearby.clear();
    drawMermaidDiagrams(queue);
  }, READER_SCROLL_SETTLE_MS);
}

function readerScrollSettled() {
  
  mermaidExportHolding = false;
  if (mermaidWaitingNearby.size || mermaidLeavingView.size) scheduleMermaidPass();
  scheduleMermaidWarmPass();
}

function forgetMermaidWatch() {
  
  mermaidExportHolding = false;
  if (mermaidViewObserver) {
    mermaidViewObserver.disconnect();
    mermaidViewObserver = null;
  }
  if (mermaidRecycleObserver) {
    mermaidRecycleObserver.disconnect();
    mermaidRecycleObserver = null;
  }
  mermaidWaitingNearby.clear();
  mermaidLeavingView.clear();
  if (mermaidDrainTimer) {
    window.clearTimeout(mermaidDrainTimer);
    mermaidDrainTimer = 0;
  }
  if (mermaidWarmTimer) {
    window.clearTimeout(mermaidWarmTimer);
    mermaidWarmTimer = 0;
  }
}


function mermaidReaderDistance(diagram) {
  const rect = diagram.getBoundingClientRect();
  const middle = mermaidViewHeight() / 2;
  return Math.abs(rect.top + rect.height / 2 - middle);
}


function mermaidBlocksAboveReader(batch) {
  const topEdge = app.getBoundingClientRect().top;
  const above = [];
  for (const diagram of batch) {
    const rect = diagram.getBoundingClientRect();
    if (rect.bottom <= topEdge) above.push({ diagram, height: rect.height });
  }
  return above;
}

function mermaidRepayGrowthAbove(above) {
  if (!above.length) return;
  let gain = 0;
  for (const entry of above) {
    if (!entry.diagram.isConnected) continue;
    gain += entry.diagram.getBoundingClientRect().height - entry.height;
  }
  if (Math.abs(gain) < 0.5) return;
  setReaderScrollTop(app.scrollTop + gain);
}


const MERMAID_BATCH_SIZE = 3;

const MERMAID_WARM_BATCH_SIZE = 1;
const MERMAID_WARM_REST_MS = 50;

let mermaidRenderGeneration = 0;

function drawMermaidBatches(diagrams, generation, warming) {
  return loadMermaid()
    .then(inThisColumn(async (mermaid) => {
      
      if (document.fonts && document.fonts.ready) await document.fonts.ready;
      if (generation !== mermaidRenderGeneration) return;
      
      registerMermaidIcons(mermaid);
      mermaid.initialize(mermaidRuntimeConfig());
      
      pauseMinimapPreview();
      try {
        const size = warming ? MERMAID_WARM_BATCH_SIZE : MERMAID_BATCH_SIZE;
        for (let at = 0; at < diagrams.length; at += size) {
          if (generation !== mermaidRenderGeneration) return;
          
          if (warming && readerScrolling) return;
          const batch = diagrams.slice(at, at + size).filter((diagram) => diagram.isConnected);
          if (!batch.length) continue;
          
          const above = mermaidBlocksAboveReader(batch);
          
          for (const diagram of batch) {
            const drawable = await mermaidDrawableSource(diagram.__mermaidSource);
            if (drawable != null && drawable !== diagram.textContent) diagram.textContent = drawable;
            
            diagram.__mermaidDrawnSource = diagram.textContent;
          }
          if (generation !== mermaidRenderGeneration) return;
          try {
            await mermaid.run({ nodes: batch });
          } catch (error) {
            
            console.error(error);
            for (const diagram of batch) {
              if (diagram.querySelector('.error-icon') || !diagram.querySelector('svg')) await markMermaidFailed(mermaid, diagram);
            }
          }
          for (const diagram of batch) {
            const drawnSource = diagram.__mermaidDrawnSource;
            delete diagram.__mermaidDrawnSource;
            if (diagram.dataset.mermaidRender === 'failed') {
              
              delete diagram.dataset.diagramWait;
              if (mermaidViewObserver) mermaidViewObserver.unobserve(diagram);
              continue;
            }
            if (diagram.__mermaidSource == null) continue;
            if (mermaidRenderCache.size >= MERMAID_CACHE_CAP) mermaidRenderCache.clear();
            
            shareMermaidSheet(diagram);
            
            labelBarSeriesFromOwnData(diagram, await chartPlotsFromSource(mermaid, drawnSource));
            mermaidRenderCache.set(mermaidCacheKey(diagram.__mermaidSource), diagram.innerHTML);
            finishMermaidDiagram(diagram);
            addMermaidControls(diagram);
          }
          mermaidRepayGrowthAbove(above);
          
          readerAnchorBlocks = null;
          
          if (warming) await new Promise((resolve) => window.requestAnimationFrame(() => window.setTimeout(resolve, MERMAID_WARM_REST_MS)));
          else await new Promise((resolve) => window.setTimeout(resolve, 0));
        }
      } finally {
        resumeMinimapPreview();
        
        mermaidPageTextChanged();
        
        scheduleMermaidWarmPass();
      }
    }))
    .catch((error) => {
      console.error(error);
    });
}


function addMermaidControls(diagram) {
  addMermaidViewControls(diagram);
  addMermaidEditButtons(diagram);
}

function addMermaidEditButtons(diagram) {
  if (currentDocumentFormat !== 'markdown' || !readerEditingAllowed()) return;
  const { start, end } = rangeOf(diagram, 'block');
  if (!Number.isFinite(start) || !Number.isFinite(end)) return;
  if (diagram.querySelector('.mermaid-tools')) return;
  const tools = document.createElement('div');
  tools.className = 'mermaid-tools';
  tools.appendChild(mermaidToolButton('source', 'Edit the Mermaid text of this diagram', `<span class="lt-icon lt-icon-code-view"></span>`));
  tools.appendChild(mermaidToolButton('sheet', 'Open in the flowchart editor, to draw it', `<span class="lt-icon lt-icon-workflow"></span>`));
  diagram.appendChild(tools);
}

function mermaidToolButton(tool, label, icon) {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'mermaid-tool';
  button.dataset.mermaidTool = tool;
  button.title = label;
  button.setAttribute('aria-label', label);
  button.innerHTML = icon;
  return button;
}


const MERMAID_ZOOM_BUTTONS = [
  ['out', 'Zoom out — or Ctrl and the wheel', `<span class="lt-icon lt-icon-zoom-out"></span>`],
  ['fit', 'Whole diagram, back where it started — or double-click it', `<span class="lt-icon lt-icon-fit"></span>`],
  ['in', 'Zoom in — or Ctrl and the wheel. Drag the diagram to move it', `<span class="lt-icon lt-icon-zoom-in"></span>`],
];

const MERMAID_FULL_BUTTON = ['full', 'Open it on the whole window', `<span class="lt-icon lt-icon-expand"></span>`];

function mermaidZoomGroup(buttons, label) {
  const group = document.createElement('div');
  group.className = 'mermaid-zoom';
  group.setAttribute('role', 'group');
  group.setAttribute('aria-label', label);
  for (const [step, title, icon] of buttons) {
    const button = document.createElement('button');
    button.type = 'button';
    button.dataset.mermaidZoom = step;
    button.title = title;
    button.setAttribute('aria-label', title);
    button.innerHTML = icon;
    group.appendChild(button);
  }
  return group;
}

function mermaidExportButton() {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'mermaid-export';
  const label = 'Save this diagram as a file';
  button.title = label;
  button.setAttribute('aria-label', label);
  button.innerHTML = `<span class="lt-icon lt-icon-export"></span>`;
  return button;
}


function addMermaidViewControls(diagram) {
  if (diagram.querySelector('.mermaid-view-controls')) return;
  const row = document.createElement('div');
  row.className = 'mermaid-view-controls';
  row.appendChild(mermaidExportButton());
  row.appendChild(mermaidZoomGroup(MERMAID_ZOOM_BUTTONS.concat([MERMAID_FULL_BUTTON]), 'Diagram view'));
  diagram.appendChild(row);
}


function openMermaidExportMenu(button) {
  const overlay = button.closest('.diagram-overlay');
  const block = overlay ? overlay.__diagramBlock : button.closest('pre.mermaid');
  const source = block ? block.__mermaidSource : null;
  if (!source) return;
  beginDiagramExport(source, button, overlay || appSurface);
}




const MERMAID_ZOOM_MIN = 0.5;
const MERMAID_ZOOM_MAX = 8;


function mermaidView(diagram) {
  return diagram.__mermaidView || { zoom: 1, x: 0, y: 0 };
}


const MERMAID_PAN_KEEP = 48;


function mermaidNatural(diagram, svg) {
  if (!diagram.__mermaidNatural) {
    const drawn = svg.getBoundingClientRect();
    diagram.__mermaidNatural = {
      width: drawn.width,
      height: drawn.height,
      boxHeight: diagram.getBoundingClientRect().height,
      attrWidth: svg.getAttribute('width'),
      attrHeight: svg.getAttribute('height'),
      maxWidth: svg.style.maxWidth,
    };
  }
  return diagram.__mermaidNatural;
}


function setMermaidView(diagram, next) {
  
  const svg = diagram.querySelector(':scope > svg');
  if (!svg) return;
  const natural = mermaidNatural(diagram, svg);
  const zoom = Math.max(MERMAID_ZOOM_MIN, Math.min(MERMAID_ZOOM_MAX, next.zoom));
  const width = natural.width * zoom;
  const height = natural.height * zoom;
  const roomX = Math.max(0, (width + diagram.clientWidth) / 2 - MERMAID_PAN_KEEP);
  const roomY = Math.max(0, (height + natural.boxHeight) / 2 - MERMAID_PAN_KEEP);
  const view = {
    zoom,
    x: Math.max(-roomX, Math.min(roomX, next.x)),
    y: Math.max(-roomY, Math.min(roomY, next.y)),
  };
  diagram.__mermaidView = view;
  if (view.zoom === 1 && view.x === 0 && view.y === 0) {
    resetMermaidView(diagram, svg, natural);
    return;
  }
  
  diagram.classList.add('is-moved');
  diagram.style.setProperty('--mermaid-box-height', natural.boxHeight + 'px');
  diagram.style.setProperty('--mermaid-pan-x', view.x + 'px');
  diagram.style.setProperty('--mermaid-pan-y', view.y + 'px');
  svg.setAttribute('width', String(Math.max(1, Math.round(width))));
  svg.setAttribute('height', String(Math.max(1, Math.round(height))));
  svg.style.maxWidth = 'none';
}


function resetMermaidView(diagram, svg, natural) {
  diagram.classList.remove('is-moved');
  diagram.style.removeProperty('--mermaid-box-height');
  diagram.style.removeProperty('--mermaid-pan-x');
  diagram.style.removeProperty('--mermaid-pan-y');
  if (natural.attrWidth == null) svg.removeAttribute('width');
  else svg.setAttribute('width', natural.attrWidth);
  if (natural.attrHeight == null) svg.removeAttribute('height');
  else svg.setAttribute('height', natural.attrHeight);
  svg.style.maxWidth = natural.maxWidth;
}


function zoomMermaidAt(diagram, factor, clientX, clientY) {
  const view = mermaidView(diagram);
  const zoom = Math.max(MERMAID_ZOOM_MIN, Math.min(MERMAID_ZOOM_MAX, view.zoom * factor));
  const box = diagram.getBoundingClientRect();
  const atX = clientX - (box.left + box.width / 2);
  const atY = clientY - (box.top + box.height / 2);
  const scale = zoom / view.zoom;
  setMermaidView(diagram, {
    zoom,
    x: atX - (atX - view.x) * scale,
    y: atY - (atY - view.y) * scale,
  });
}

function mermaidCenterZoom(diagram, factor) {
  const box = diagram.getBoundingClientRect();
  zoomMermaidAt(diagram, factor, box.left + box.width / 2, box.top + box.height / 2);
}


function mermaidDiagramFor(target) {
  if (!target || !target.closest) return null;
  const diagram = target.closest('pre.mermaid[data-processed="true"]');
  if (!diagram || diagram.dataset.editingSource === 'true') return null;
  return diagram;
}


let mermaidPan = null;
if (app) {
  onColumn(
    'pointerdown',
    (event) => {
      const control = event.target && event.target.closest ? event.target.closest('.mermaid-tool, .mermaid-zoom button, .mermaid-export, .diagram-close, .image-lane-corner, .code-copy') : null;
      if (control) event.stopPropagation();
    },
    true,
  );
  
  onColumn('pointerdown', (event) => {
    if (event.button !== 0 && event.button !== 1) return;
    const diagram = mermaidDiagramFor(event.target);
    if (!diagram) return;
    if (event.target.closest('.mermaid-tools, .mermaid-view-controls, .mermaid-zoom, .diagram-close, a')) return;
    
    if (document.activeElement && document.activeElement.isContentEditable) document.activeElement.blur();
    event.preventDefault();
    mermaidPan = { diagram, pointer: event.pointerId, x: event.clientX, y: event.clientY, from: mermaidView(diagram) };
    leafHoldPointer(diagram, event.pointerId);
    diagram.classList.add('is-panning');
  });
  onColumn('pointermove', (event) => {
    if (!mermaidPan || event.pointerId !== mermaidPan.pointer) return;
    setMermaidView(mermaidPan.diagram, {
      zoom: mermaidPan.from.zoom,
      x: mermaidPan.from.x + (event.clientX - mermaidPan.x),
      y: mermaidPan.from.y + (event.clientY - mermaidPan.y),
    });
  });
  const endMermaidPan = () => {
    if (!mermaidPan) return;
    mermaidPan.diagram.classList.remove('is-panning');
    mermaidPan = null;
  };
  onColumn('pointerup', endMermaidPan);
  onColumn('pointercancel', endMermaidPan);
  
  onColumn(
    'wheel',
    (event) => {
      if (!event.ctrlKey && !event.metaKey) return;
      const diagram = mermaidDiagramFor(event.target);
      if (!diagram) return;
      event.preventDefault();
      zoomMermaidAt(diagram, event.deltaY < 0 ? 1.1 : 1 / 1.1, event.clientX, event.clientY);
    },
    { passive: false },
  );
  onColumn(
    'wheel',
    (event) => {
      if ((!event.ctrlKey && !event.metaKey) || event.altKey || event.shiftKey || !event.deltaY) return;
      if (mermaidDiagramFor(event.target)) return;
      const lane = event.target && event.target.closest ? event.target.closest('.table-lane') : null;
      const table = lane && lane.querySelector(':scope > table');
      if (!table || table.scrollWidth <= table.clientWidth) return;
      const end = table.scrollWidth - table.clientWidth;
      table.scrollLeft = Math.max(0, Math.min(end, table.scrollLeft + event.deltaY));
      event.preventDefault();
    },
    { passive: false },
  );
  onColumn('click', (event) => {
    if (!event.target || !event.target.closest) return;
    const codeButton = event.target.closest('.code-copy');
    if (codeButton) {
      event.preventDefault();
      const block = codeButton.closest('pre');
      const code = block && block.querySelector('code');
      if (code) copyCodeBlock(codeButton, code.textContent || '');
      return;
    }
    const zoomButton = event.target.closest('.mermaid-zoom button');
    if (zoomButton) {
      event.preventDefault();
      const diagram = zoomButton.closest('pre.mermaid');
      if (!diagram) return;
      const step = zoomButton.dataset.mermaidZoom;
      if (step === 'full') openDiagramOverlay(diagram, zoomButton);
      else if (step === 'fit') setMermaidView(diagram, { zoom: 1, x: 0, y: 0 });
      else mermaidCenterZoom(diagram, step === 'in' ? 1.25 : 1 / 1.25);
      return;
    }
    const exportButton = event.target.closest('.mermaid-export');
    if (exportButton) {
      event.preventDefault();
      openMermaidExportMenu(exportButton);
      return;
    }
    const tool = event.target.closest('.mermaid-tool');
    if (!tool) return;
    event.preventDefault();
    const diagram = tool.closest('pre.mermaid');
    if (!diagram) return;
    if (tool.dataset.mermaidTool === 'source') startBlockSourceEdit(diagram);
    else openMermaidBlockSheet(diagram);
  });
  
  onColumn('dblclick', (event) => {
    const diagram = mermaidDiagramFor(event.target);
    if (!diagram || event.target.closest('.mermaid-tools, .mermaid-view-controls, .mermaid-zoom, .diagram-close, a')) return;
    setMermaidView(diagram, { zoom: 1, x: 0, y: 0 });
  });
  
  onColumn('auxclick', (event) => {
    if (event.button === 1 && mermaidDiagramFor(event.target)) event.preventDefault();
  });
}


function repaintMermaidDiagrams() {
  const diagrams = Array.from(app.querySelectorAll('pre.mermaid:not([data-diagram-stage])'));
  
  forgetMermaidSheets();
  let any = false;
  for (const diagram of diagrams) {
    if (diagram.__mermaidSource == null) continue;
    if (diagram.dataset.editingSource === 'true') continue;
    diagram.textContent = diagram.__mermaidSource;
    delete diagram.dataset.processed;
    delete diagram.dataset.mermaidRender;
    any = true;
  }
  if (any) renderMermaidDiagrams();
  return any;
}


let mermaidFontRepaintDone = false;
function repaintMermaidDiagramsForFonts() {
  if (mermaidFontRepaintDone) return;
  if (repaintMermaidDiagrams()) mermaidFontRepaintDone = true;
}
if (document.fonts && typeof document.fonts.addEventListener === 'function') {
  document.fonts.addEventListener('loadingdone', repaintMermaidDiagramsForFonts);
}




if (typeof MutationObserver === 'function') {
  new MutationObserver(inThisColumn((records) => {
    const root = document.documentElement;
    if (!records.some((record) => root.getAttribute(record.attributeName) !== record.oldValue)) return;
    mermaidFontRepaintDone = false;
    repaintMermaidDiagrams();
    
    repaintDiagramOverlay();
  })).observe(document.documentElement, {
    attributes: true,
    attributeOldValue: true,
    attributeFilter: ['data-theme', 'data-leaf-theme'],
  });
}

function loadKatex() {
  if (window.katex) {
    return Promise.resolve(window.katex);
  }
  if (katexLoadPromise) {
    return katexLoadPromise;
  }
  katexLoadPromise = new Promise((resolve, reject) => {
    const script = document.createElement('script');
    script.src = KATEX_SCRIPT_URL;
    
    script.crossOrigin = 'anonymous';
    script.async = true;
    script.onload = () => {
      if (window.katex) {
        resolve(window.katex);
        return;
      }
      reject(new Error('KaTeX runtime loaded without exposing window.katex'));
    };
    script.onerror = () => reject(new Error('KaTeX runtime failed to load'));
    document.head.appendChild(script);
  });
  return katexLoadPromise;
}

const katexRenderCache = new Map();
const KATEX_CACHE_CAP = 1000;
function renderMathElements() {
  const nodes = Array.from(app.querySelectorAll('.math:not([data-math-rendered])'));
  if (!nodes.length) {
    return;
  }
  const pending = [];
  nodes.forEach((node) => {
    const key = (node.classList.contains('math-display') ? 'D\n' : 'I\n') + node.textContent;
    const cached = katexRenderCache.get(key);
    if (cached != null) {
      node.innerHTML = cached;
      node.dataset.mathRendered = 'true';
      return;
    }
    pending.push({ node, key });
  });
  if (!pending.length) {
    return;
  }
  loadKatex()
    .then((katex) => {
      pending.forEach(({ node, key }) => {
        try {
          katex.render(node.textContent, node, {
            displayMode: node.classList.contains('math-display'),
            throwOnError: false,
          });
          if (katexRenderCache.size >= KATEX_CACHE_CAP) katexRenderCache.clear();
          katexRenderCache.set(key, node.innerHTML);
        } catch (error) {
          console.error(error);
        }
        node.dataset.mathRendered = 'true';
      });
    })
    .catch((error) => {
      console.error(error);
    });
}
let wideTableResizeObserver;
function syncTableLaneState(table) {
  const lane = table && table.closest ? table.closest('.table-lane') : null;
  const bay = lane && lane.parentElement;
  if (!lane || !bay) return;
  const allowsCards = !table.classList.contains('no-cards');
  const isCards = table.classList.contains('is-cards');
  const isCellCard = table.classList.contains('is-cell-card');
  for (const wrapper of [lane, bay]) {
    wrapper.classList.toggle('table-allows-cards', allowsCards);
    wrapper.classList.toggle('table-is-cards', isCards);
    wrapper.classList.toggle('table-is-cell-card', isCellCard);
  }
}
function markCellCardTable(table) {
  const headings = table.querySelectorAll(':scope > thead > tr > th');
  const body = table.tBodies[0];
  const rows = body ? Array.from(body.rows) : [];
  const isCellCard = headings.length === 1 && rows.length <= 1 && rows.every((row) => row.children.length === 1);
  table.classList.toggle('is-cell-card', isCellCard);
  table.classList.toggle('is-figure-card', isCellCard && rows.length === 1);
  if (isCellCard) table.classList.add('no-cards');
}

function laneWideTables(root = app) {
  const body = root.querySelector('.document-body');
  if (!body) return;
  for (const table of Array.from(body.children)) {
    if (table.tagName !== 'TABLE' || table.classList.contains('data-table')) continue;
    const bay = document.createElement('div');
    bay.className = 'table-bay';
    const lane = document.createElement('div');
    lane.className = 'table-lane';
    table.replaceWith(bay);
    bay.appendChild(lane);
    lane.appendChild(table);
    markCellCardTable(table);
    syncTableLaneState(table);
    addTableSizingGrips(lane);
  }
  measureWideTables(root);
}


function laneWantsCards(lane) {
  return window.getComputedStyle(lane).getPropertyValue('--reader-table-cards').trim() === '1';
}


function measureWideTables(root = app) {
  if (wideTableResizeObserver) wideTableResizeObserver.disconnect();
  const lanes = Array.from(root.querySelectorAll('.table-lane'));
  const decide = (changed) => {
    const pairs = [];
    for (const lane of changed) {
      const table = lane.querySelector('table');
      if (!table) continue;
      if (table.classList.contains('is-cell-card')) continue;
      
      if (table.dataset.lensLayout && table.dataset.lensLayout !== 'grid') continue;
      
      if (table.classList.contains('is-reader-sized')) continue;
      table.classList.remove('is-cards');
      table.classList.add('no-cards');
      syncTableLaneState(table);
      pairs.push({ lane, table });
    }
    
    const cards = pairs.map(({ lane, table }) => laneWantsCards(lane) && table.scrollWidth > lane.clientWidth + 2);
    pairs.forEach(({ table }, at) => {
      table.classList.toggle('is-cards', cards[at]);
      syncTableLaneState(table);
    });
  };
  decide(lanes);
  if (typeof ResizeObserver !== 'undefined') {
    
    const changed = new Set();
    let queued = 0;
    const observer = new ResizeObserver((entries) => {
      for (const entry of entries) changed.add(entry.target);
      if (queued) return;
      queued = requestAnimationFrame(() => {
        queued = 0;
        const moved = Array.from(changed);
        changed.clear();
        if (wideTableResizeObserver !== observer) return;
        decide(moved);
      });
    });
    wideTableResizeObserver = observer;
    lanes.forEach((lane) => observer.observe(lane));
  }
  
  if (document.fonts?.ready) {
    document.fonts.ready.then(() => decide(lanes));
  }
}

function laneWidePictures(root = app) {
  const body = root.querySelector('.document-body');
  if (!body) return;
  for (const block of Array.from(body.children)) laneWidePicture(block);
}

function laneWidePicture(block) {
  if (block.tagName !== 'P') return;
  const pictures = Array.from(block.children).filter((child) => child.tagName === 'IMG');
  
  const alone =
    pictures.length === 1 && pictures[0].dataset.imageMissing !== 'true' && !(block.textContent || '').trim();
  block.classList.toggle('image-lane', alone);
}

function markLinksThatGoNowhere(root = app) {
  const body = root.querySelector('.document-body');
  if (body) markLinksThatGoNowhereIn(body);
}

function markLinksThatGoNowhereIn(scope) {
  for (const link of scope.querySelectorAll('a')) {
    
    if (link.getAttribute('href') || link.getAttribute('name') || link.getAttribute('id')) continue;
    if (!(link.textContent || '').trim()) continue;
    link.classList.add('link-goes-nowhere');
  }
}
function decorateBlockquoteLines(root = app) {
  root.querySelectorAll('blockquote p').forEach((paragraph) => {
    if (blockquoteIsAlert(paragraph.closest('blockquote'))) return;
    if (paragraph.querySelector('.blockquote-line')) return;
    const children = Array.from(paragraph.childNodes);
    if (!children.some((node) => node.nodeName === 'BR')) return;
    const fragment = document.createDocumentFragment();
    let line = document.createElement('span');
    line.className = 'blockquote-line';
    children.forEach((node) => {
      if (node.nodeName === 'BR') {
        fragment.appendChild(line);
        line = document.createElement('span');
        line.className = 'blockquote-line';
        return;
      }
      line.appendChild(node);
    });
    fragment.appendChild(line);
    paragraph.replaceChildren(fragment);
    paragraph.classList.add('blockquote-lines');
  });
}

const NOTE_CARD_SWATCH = /^#(?:[0-9a-fA-F]{6}|[0-9a-fA-F]{3})(?=\s|$)/;

function decorateNoteCards(root = app) {
  for (const card of root.querySelectorAll('.document-body .note-card')) {
    for (const paragraph of card.children) {
      if (paragraph.tagName !== 'P') continue;
      let code = null;
      let alone = true;
      for (const node of paragraph.childNodes) {
        if (node.nodeType === 3 && !node.nodeValue.trim()) continue;
        if (node.tagName === 'CODE' && !code) code = node;
        else alone = false;
      }
      if (!alone || !code) continue;
      const match = NOTE_CARD_SWATCH.exec(code.textContent);
      if (!match) continue;
      card.classList.add('is-swatch-card');
      card.style.setProperty('--note-card-swatch', match[0]);
      break;
    }
  }
}

const CODE_COPY_ICON = '<span class="lt-icon code-copy-mark code-copy-copy lt-icon-copy"></span><span class="lt-icon code-copy-mark code-copy-check lt-icon-check"></span>';

function decorateCodeBlocks() {
  app.querySelectorAll('.document-body pre:not(.mermaid)').forEach((pre) => {
    if (pre.querySelector(':scope > .code-copy')) return;
    const code = pre.querySelector('code');
    if (!code) return;
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'code-copy';
    button.innerHTML = CODE_COPY_ICON;
    setCodeCopyLabel(button, 'Copy code');
    pre.appendChild(button);
  });
}


const CODE_FENCE_RUNS = /^\d+,\d+(;\d+,\d+)*$/;
const CODE_FENCE_CLASS_LIST = /^syn-[a-z]+( syn-[a-z]+)*$/;

const codeFenceTables = new WeakMap();

function codeFenceTable(pre, code) {
  if (codeFenceTables.has(pre)) return codeFenceTables.get(pre);
  const runs = pre.getAttribute('data-runs') || '';
  const lists = (pre.getAttribute('data-syn') || '').split('|');
  let table = null;
  const whole = code.childNodes.length === 1 && code.firstChild.nodeType === 3;
  if (whole && CODE_FENCE_RUNS.test(runs) && lists.every((list) => CODE_FENCE_CLASS_LIST.test(list))) {
    const text = code.firstChild.nodeValue;
    const pieces = [];
    let at = 0;
    let fits = true;
    for (const pair of runs.split(';')) {
      const comma = pair.indexOf(',');
      const index = Number(pair.slice(0, comma));
      const length = Number(pair.slice(comma + 1));
      if (index > lists.length || length === 0 || at + length > text.length) {
        fits = false;
        break;
      }
      pieces.push(index, at, length);
      at += length;
    }
    
    if (fits && at === text.length) {
      let left = 0;
      for (let i = 0; i < pieces.length; i += 3) if (pieces[i]) left += 1;
      table = { lists, pieces, left, lineStarts: null };
    }
  }
  codeFenceTables.set(pre, table);
  return table;
}

function codeFenceLineStarts(table, text) {
  if (table.lineStarts) return table.lineStarts;
  const starts = [0];
  for (let i = 0; i < text.length; i += 1) if (text.charCodeAt(i) === 10) starts.push(i + 1);
  table.lineStarts = starts;
  return starts;
}

function spliceCodeFenceRuns(node, base, table, from, to) {
  const { lists, pieces } = table;
  const text = node.nodeValue;
  const out = document.createDocumentFragment();
  let cursor = 0;
  let drew = 0;
  for (let i = 0; i < pieces.length; i += 3) {
    const index = pieces[i];
    const at = pieces[i + 1];
    const length = pieces[i + 2];
    if (!index) continue;
    const end = at + length;
    if (end <= from || at >= to) continue;
    
    if (at < base || end > base + text.length) continue;
    if (at - base > cursor) out.appendChild(document.createTextNode(text.slice(cursor, at - base)));
    const span = document.createElement('span');
    span.className = lists[index - 1];
    span.textContent = text.substr(at - base, length);
    out.appendChild(span);
    cursor = end - base;
    drew += 1;
  }
  if (!drew) return 0;
  if (cursor < text.length) out.appendChild(document.createTextNode(text.slice(cursor)));
  node.replaceWith(out);
  return drew;
}

function drawCodeFence(pre, stretch) {
  if (!pre || !pre.hasAttribute('data-runs')) return false;
  
  if (pre.dataset.editingSource === 'true') return false;
  const code = pre.firstElementChild;
  if (!code || code.tagName !== 'CODE') return false;
  const table = codeFenceTable(pre, code);
  if (!table) {
    pre.removeAttribute('data-runs');
    pre.removeAttribute('data-syn');
    return false;
  }
  const from = stretch ? stretch.from : 0;
  const to = stretch ? stretch.to : code.textContent.length;
  let drew = 0;
  let base = 0;
  
  for (const node of Array.from(code.childNodes)) {
    const length = node.textContent.length;
    
    if (node.nodeType === 3 && base < to && base + length > from) {
      drew += spliceCodeFenceRuns(node, base, table, Math.max(from, base), Math.min(to, base + length));
    }
    base += length;
  }
  table.left -= drew;
  if (table.left <= 0) {
    pre.removeAttribute('data-runs');
    pre.removeAttribute('data-syn');
  }
  return drew > 0;
}

function drawCodeFencesIn(root) {
  if (!root || !root.querySelectorAll) return 0;
  let drew = 0;
  for (const pre of root.querySelectorAll('pre[data-runs]')) {
    const code = pre.firstElementChild;
    
    if (code && code.tagName === 'CODE' && (code.childNodes.length !== 1 || code.firstChild.nodeType !== 3)) {
      code.textContent = code.textContent;
      codeFenceTables.delete(pre);
    }
    if (drawCodeFence(pre)) drew += 1;
  }
  return drew;
}

function codeFencePageTextChanged() {
  forgetRenderedText();
  refreshFind({ keepCurrent: true });
}
function drawEveryCodeFence() {
  if (drawCodeFencesIn(app.querySelector('.document-body'))) codeFencePageTextChanged();
}

function codeFenceStretchNear(pre, code, codeBox, top, bottom) {
  if (codeBox.top >= top && codeBox.bottom <= bottom) return null;
  const table = codeFenceTable(pre, code);
  if (!table) return null;
  const text = code.textContent;
  const starts = codeFenceLineStarts(table, text);
  const height = codeBox.height / starts.length;
  if (!(height > 0)) return null;
  const first = Math.max(0, Math.floor((top - codeBox.top) / height));
  const last = Math.min(starts.length - 1, Math.ceil((bottom - codeBox.top) / height));
  if (first > last) return { from: 0, to: 0 };
  return { from: starts[first], to: last + 1 < starts.length ? starts[last + 1] : text.length };
}

function drawCodeFencesNearReader() {
  const body = app.querySelector('.document-body');
  if (!body) return;
  const fences = body.querySelectorAll('pre[data-runs]');
  if (!fences.length) return;
  const view = app.getBoundingClientRect();
  
  if (!view.height) return;
  const near = [];
  for (const pre of fences) {
    const box = pre.getBoundingClientRect();
    
    if (!box.height) continue;
    if (box.top > view.bottom + view.height) break;
    if (box.bottom >= view.top - view.height) {
      const code = pre.firstElementChild;
      near.push([pre, code, code && code.getBoundingClientRect ? code.getBoundingClientRect() : box]);
    }
  }
  const top = view.top - view.height;
  const bottom = view.bottom + view.height;
  let drew = 0;
  for (const [pre, code, codeBox] of near) {
    if (drawCodeFence(pre, code ? codeFenceStretchNear(pre, code, codeBox, top, bottom) : null)) drew += 1;
  }
  if (drew) codeFencePageTextChanged();
}

let codeFenceScrollFrame = 0;
function scheduleCodeFencePass() {
  if (codeFenceScrollFrame) return;
  codeFenceScrollFrame = columnFrame(() => {
    codeFenceScrollFrame = 0;
    drawCodeFencesNearReader();
  });
}

let codeFenceObserver = null;
function watchCodeFences() {
  if (codeFenceObserver) codeFenceObserver.disconnect();
  const body = app.querySelector('.document-body');
  if (!body) return;
  const fences = body.querySelectorAll('pre[data-runs]');
  if (!fences.length) return;
  if (typeof IntersectionObserver === 'undefined') {
    drawEveryCodeFence();
    return;
  }
  if (!codeFenceObserver) {
    codeFenceObserver = new IntersectionObserver(inThisColumn((entries) => {
      
      if (entries.some((entry) => entry.isIntersecting)) drawCodeFencesNearReader();
      for (const entry of entries) if (!entry.target.hasAttribute('data-runs')) codeFenceObserver.unobserve(entry.target);
    }), { root: app, rootMargin: '100% 0px' });
  }
  for (const pre of fences) codeFenceObserver.observe(pre);
}

function documentOutlineHeadings(body) {
  if (!body) return [];
  return Array.from(body.querySelectorAll('h1, h2, h3, h4, h5, h6')).filter(
    (h) => !h.closest('.footnotes') && !h.closest('.tei-front')
  );
}

function readOutlineHeadingText(h) {
  const clone = h.cloneNode(true);
  clone.querySelectorAll('.footnote-ref').forEach((n) => n.remove());
  return (clone.textContent || '').replace(/\s+/g, ' ').trim();
}

function stampOutlineHeadingIds(headings, taken) {
  headings.forEach((h, i) => { if (!h.id) { let at = i + 1; while (taken.has('section-' + at)) at += 1; h.id = 'section-' + at; taken.add(h.id); } });
}

function collectDocumentOutlineRows(body) {
  const headings = documentOutlineHeadings(body);
  if (headings.length < 2) return [];
  stampOutlineHeadingIds(headings, new Set(Array.from(body.querySelectorAll('[id]'), (n) => n.id)));
  return headings.map((h) => ({ level: Number(h.tagName.slice(1)) || 1, text: readOutlineHeadingText(h), id: h.id }));
}

function publishDocumentOutline() {
  const body = readingDocumentRoot();
  setDocumentOutlineRows(body ? collectDocumentOutlineRows(body) : []);
  scheduleLibraryOutline();
}

const LOCAL_IMAGE_SRC_PREFIXES = ['leaf-image://', 'http://leaf-image.', 'https://leaf-image.'];

function isLocalImageSrc(src) {
  return LOCAL_IMAGE_SRC_PREFIXES.some((prefix) => src.startsWith(prefix));
}

function stampLocalImages(root = app) {
  if (!root) return;
  root.querySelectorAll('img[src]').forEach((img) => {
    
    restoreMissingImage(img);
    
    const src = img.getAttribute('src') || '';
    if (!isLocalImageSrc(src)) return;
    const base = src.split('?')[0];
    const stamped = `${base}?leaf-epoch=${localImageEpoch}`;
    if (img.getAttribute('src') !== stamped) img.setAttribute('src', stamped);
  });
}

function readingDrawsLocalPicture(root = app) {
  if (!root) return false;
  
  for (const img of root.querySelectorAll('img[src]')) {
    if (isLocalImageSrc(img.getAttribute('src') || '')) return true;
    if (isLocalImageSrc((img.dataset && img.dataset.imageMissingSrc) || '')) return true;
  }
  return false;
}

window.leafRefreshImages = () => {
  
  if (!readingIsContainedPage() && !minimapPreviewDocument() && !readingDrawsLocalPicture()) return;
  localImageEpoch += 1;
  stampLocalImages();
  
  stampContainedPageImages(siteFrameDocument(), localImageEpoch);
  stampContainedPageImages(minimapPreviewDocument(), localImageEpoch);
  
  refreshContainedPageStylesheets(siteFrameDocument(), localImageEpoch);
  refreshContainedPageStylesheets(minimapPreviewDocument(), localImageEpoch);
  
  laneWidePictures();
  bindImageSheet();
  scheduleMinimapPreviewUpdate();
};

const MISSING_IMAGE_SIZE = 40;
const TRANSPARENT_PIXEL =
  'data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7';

function markMissingImage(img) {
  if (!(img instanceof HTMLImageElement) || img.dataset.imageMissing === 'true') return;
  img.dataset.imageMissing = 'true';
  img.dataset.imageMissingAlt = img.alt || '';
  img.dataset.imageMissingSrc = img.getAttribute('src') || '';
  if (img.alt && !img.title) img.title = img.alt;
  img.alt = '';
  img.width = MISSING_IMAGE_SIZE;
  img.height = MISSING_IMAGE_SIZE;
  img.classList.add('lt-icon', 'lt-icon-missing-image');
  img.src = TRANSPARENT_PIXEL;
  
  const block = img.parentElement;
  if (!block || !block.classList.contains('image-lane')) return;
  block.classList.remove('image-lane');
  const corner = block.querySelector(':scope > .image-lane-corner');
  if (corner) corner.remove();
}

function restoreMissingImage(img) {
  if (img.dataset.imageMissing !== 'true') return;
  const src = img.dataset.imageMissingSrc || '';
  img.alt = img.dataset.imageMissingAlt || '';
  img.removeAttribute('width');
  img.removeAttribute('height');
  img.classList.remove('lt-icon', 'lt-icon-missing-image');
  delete img.dataset.imageMissing;
  delete img.dataset.imageMissingAlt;
  delete img.dataset.imageMissingSrc;
  if (src) img.setAttribute('src', src);
}

if (app) {
  onColumn('error', (event) => {
    if (isLocalImageSrc(event.target.getAttribute?.('src') || '')) localImagesNeedRefresh = true;
    markMissingImage(event.target);
  }, true);
}
function setCodeCopyLabel(button, label) {
  button.setAttribute('aria-label', label);
  button.title = label;
}

function copyCodeBlock(button, text) {
  const ok = () => flashCodeCopied(button);
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(ok, () => { if (legacyCopy(text)) ok(); });
  } else if (legacyCopy(text)) {
    ok();
  }
}

function copyPlainText(text) {
  if (!text) return;
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(() => {}, () => { legacyCopy(text); });
  } else {
    legacyCopy(text);
  }
}
function legacyCopy(text) {
  const area = document.createElement('textarea');
  area.value = text;
  area.setAttribute('aria-hidden', 'true');
  area.style.position = 'fixed';
  area.style.top = '-1000px';
  area.style.opacity = '0';
  appSurface.appendChild(area);
  
  const selection = window.getSelection();
  const held = [];
  if (selection) {
    for (let index = 0; index < selection.rangeCount; index += 1) held.push(selection.getRangeAt(index).cloneRange());
  }
  area.select();
  let copied = false;
  try {
    copied = document.execCommand('copy');
  } catch (error) {
    copied = false;
  }
  
  area.remove();
  if (selection && held.length) {
    selection.removeAllRanges();
    for (const range of held) selection.addRange(range);
  }
  return copied;
}

function flashCodeCopied(button) {
  button.classList.add('is-copied');
  setCodeCopyLabel(button, 'Copied');
  window.clearTimeout(button.__copiedTimer);
  button.__copiedTimer = window.setTimeout(() => {
    button.classList.remove('is-copied');
    setCodeCopyLabel(button, 'Copy code');
  }, 1400);
}

function applyFrontmatterAsks(root) {
  const table = root.querySelector('.frontmatter');
  if (!table) return;
  const body = root.querySelector('.document-body');
  const asked = (table.dataset.leafDocClasses || '').split(/\s+/).filter(Boolean);
  if (body) body.classList.add(...asked);
  
  const unread = table.dataset.leafUnread || '';
  if (unread && window.leafShowNotice) window.leafShowNotice(`Some of this note's fields were not read: ${unread}`);
}





const MERMAID_STOP_LINE_RE = /\bon line (\d+)/;


const MERMAID_FAILURE_CAUSES = [
  {
    
    reads: (line) => /[[({]\s*["']\s*`/.test(line),
    says: 'a label cannot start with a backtick',
    draws: (line) => line.replace(/`/g, ''),
  },
  {
    
    reads: (line) => /[[(]\s*\//.test(line),
    says: 'a label starting with a slash has to be quoted, or it is read as a shape',
    draws: (line) => line.replace(/\[\s*\/([^\]]*)\]/g, '["/$1"]'),
  },
  {
    
    reads: (line) => /\[[^\]"']*[()][^\]]*\]/.test(line),
    says: 'a label with brackets in it has to be quoted',
    draws: (line) => line.replace(/\[([^\]"']*[()][^\]]*)\]/g, '["$1"]'),
  },
  {
    
    reads: (line) => line.indexOf('\\"') >= 0,
    says: 'a quote inside a quoted label has to be written as &quot;',
    draws: (line) => line.replace(/\\"/g, '&quot;'),
  },
  {
    
    reads: (line) => /:.*;/.test(line),
    says: 'a semicolon ends the line, so a message cannot hold one',
    draws: (line) => line.replace(/;/g, ' —'),
  },
  {
    
    reads: (line) => /(^|\s)(click|end|graph|subgraph|style|classDef|class|linkStyle|direction|href|call)\s*(--|==|-\.|\[|\()/.test(line),
    says: 'that name is a word the renderer keeps for itself, so it cannot name a box',
    draws: null,
  },
];


function mermaidFailureNote(source, message) {
  const lines = String(source == null ? '' : source).split('\n');
  const found = MERMAID_STOP_LINE_RE.exec(message || '');
  const at = found ? Number(found[1]) : 0;
  const line = at >= 1 && at <= lines.length ? lines[at - 1] : '';
  const cause = line ? MERMAID_FAILURE_CAUSES.find((one) => one.reads(line)) : null;
  const drawn = cause && cause.draws ? cause.draws(line) : '';
  return { at, says: cause ? cause.says : '', draws: drawn && drawn !== line ? drawn.trim() : '' };
}


function mermaidFailureSentence(note) {
  if (!note.at) return 'This drawing could not be finished.';
  if (!note.says) return `The drawing stopped at line ${note.at}.`;
  return `The drawing stopped at line ${note.at}: ${note.says}.`;
}


function showMermaidFailure(diagram, source, message) {
  const doc = diagram.ownerDocument || document;
  const note = mermaidFailureNote(source, message);
  
  const text = String(source == null ? '' : source).replace(/\r?\n$/, '');
  const box = doc.createElement('div');
  box.className = 'diagram-failed';
  const head = doc.createElement('div');
  head.className = 'diagram-failed-head';
  head.textContent = 'This diagram could not be drawn';
  box.appendChild(head);
  const why = doc.createElement('div');
  why.className = 'diagram-failed-why';
  why.textContent = mermaidFailureSentence(note);
  box.appendChild(why);
  const listing = doc.createElement('div');
  listing.className = 'diagram-failed-source';
  text.split('\n').forEach((line, at) => {
    const row = doc.createElement('div');
    row.className = at + 1 === note.at ? 'diagram-failed-line is-stopped' : 'diagram-failed-line';
    row.dataset.diagramLine = String(at + 1);
    row.textContent = line;
    listing.appendChild(row);
  });
  box.appendChild(listing);
  if (note.draws) {
    const fix = doc.createElement('div');
    fix.className = 'diagram-failed-fix';
    const lead = doc.createElement('span');
    lead.textContent = 'This draws: ';
    const spelling = doc.createElement('code');
    spelling.textContent = note.draws;
    fix.appendChild(lead);
    fix.appendChild(spelling);
    box.appendChild(fix);
  }
  diagram.textContent = '';
  diagram.appendChild(box);
}


function mermaidKeptItsDrawing(diagram) {
  const drawn = diagram.querySelector('svg[aria-roledescription]:not([aria-roledescription="error"])');
  if (!drawn) return false;
  for (const bomb of diagram.querySelectorAll('svg[aria-roledescription="error"]')) {
    let own = bomb;
    while (own.parentElement && own.parentElement !== diagram) own = own.parentElement;
    if (own.parentElement === diagram && own !== drawn) own.remove();
  }
  
  diagram.dataset.processed = 'true';
  return true;
}


async function mermaidStopMessage(mermaid, source) {
  try {
    await mermaid.parse(source);
  } catch (error) {
    return (error && error.message) || '';
  }
  return '';
}


async function markMermaidFailed(mermaid, diagram) {
  if (mermaidKeptItsDrawing(diagram)) return;
  const source = diagram.__mermaidSource != null ? diagram.__mermaidSource : diagram.textContent;
  diagram.dataset.mermaidRender = 'failed';
  showMermaidFailure(diagram, source, await mermaidStopMessage(mermaid, source));
}



const TABLE_COLUMN_FLOOR = 32;


let sizedTableShapes = new Map();

let sizedTableDocument = null;


function tableSizingHeadCells(table) {
  const rows = [...table.querySelectorAll(':scope > thead > tr'), ...table.querySelectorAll(':scope > tbody > tr')];
  for (const row of rows) {
    const cells = Array.from(row.querySelectorAll(':scope > td, :scope > th'));
    if (cells.length && cells.every((cell) => (parseInt(cell.getAttribute('colspan'), 10) || 1) === 1)) return cells;
  }
  return [];
}


function tableSizingBodyRows(table) {
  return Array.from(table.querySelectorAll(':scope > tbody > tr'));
}


function tableSizingCellColumn(cell) {
  const row = cell && cell.parentElement;
  if (!row) return -1;
  let column = 0;
  for (const one of Array.from(row.querySelectorAll(':scope > td, :scope > th'))) {
    column += one.colSpan;
    if (one === cell) return column - 1;
  }
  return -1;
}


function tableSizingWidths(cells) {
  return cells.map((cell) => cell.getBoundingClientRect().width);
}


function pinTableColumnWidths(cells, widths) {
  cells.forEach((cell, at) => {
    const px = widths[at] == null ? '' : Math.round(widths[at]) + 'px';
    cell.style.width = px;
    cell.style.minWidth = px;
    cell.style.maxWidth = px;
  });
}


function pinTableRowHeights(rows, heights) {
  rows.forEach((row, at) => {
    row.style.height = heights[at] == null ? '' : Math.round(heights[at]) + 'px';
  });
}


function tableSizingShape(table) {
  return {
    columns: tableSizingHeadCells(table).map((cell) => (cell.style.width ? parseFloat(cell.style.width) : null)),
    rows: tableSizingBodyRows(table).map((row) => (row.style.height ? parseFloat(row.style.height) : null)),
  };
}

function tableSizingShapeHasSize(shape) {
  return [...shape.columns, ...shape.rows].some((one) => one != null);
}


function rememberTableSizing(table, shape = tableSizingShape(table)) {
  const identity = tableIdentity(table);
  if (!identity) return;
  if (tableSizingShapeHasSize(shape)) sizedTableShapes.set(identity.ordinal, { ...shape, headings: identity.headings });
  else sizedTableShapes.delete(identity.ordinal);
}


function repinSizedTables(path) {
  if (path !== sizedTableDocument) {
    sizedTableDocument = path;
    sizedTableShapes = new Map();
    return;
  }
  if (!sizedTableShapes.size) return;
  const tables = app.querySelectorAll('.table-lane table');
  tables.forEach((table, ordinal) => {
    const held = sizedTableShapes.get(ordinal);
    if (!held) return;
    const identity = tableIdentity(table, ordinal);
    if (!sameTableLensHeadings(held.headings, identity.headings)) return;
    const cells = tableSizingHeadCells(table);
    const rows = tableSizingBodyRows(table);
    
    if (cells.length !== held.columns.length || rows.length !== held.rows.length) return;
    pinTableColumnWidths(cells, held.columns);
    pinTableRowHeights(rows, held.rows);
    table.classList.add('is-reader-sized');
  });
  for (const ordinal of sizedTableShapes.keys()) if (ordinal >= tables.length) sizedTableShapes.delete(ordinal);
}


function addTableSizingGrips(lane) {
  for (const table of Array.from(lane.querySelectorAll('table'))) addTableGrips(table);
}


function addTableGrips(table) {
  
  const last = tableSizingHeadCells(table).length - 1;
  
  const addColumnGrip = (cell, column) => {
    if (column >= last) return;
    const grip = document.createElement('span');
    grip.className = 'table-sizer table-sizer-column';
    cell.appendChild(grip);
  };
  
  Array.from(table.querySelectorAll(':scope > thead > tr')).forEach((row) => {
    let column = 0;
    Array.from(row.querySelectorAll(':scope > td, :scope > th')).forEach((cell) => {
      column += cell.colSpan;
      addColumnGrip(cell, column - 1);
    });
  });
  tableSizingBodyRows(table).forEach((row) => {
    let column = 0;
    Array.from(row.querySelectorAll(':scope > td, :scope > th')).forEach((cell) => {
      column += cell.colSpan;
      const rowGrip = document.createElement('span');
      rowGrip.className = 'table-sizer table-sizer-row';
      cell.appendChild(rowGrip);
      
      addColumnGrip(cell, column - 1);
    });
  });
}


function isTableSizingGrip(el) {
  return !!(el && el.classList && el.classList.contains('table-sizer'));
}

let tableSizeDrag = null;


function applyPendingTableSize() {
  if (!tableSizeDrag) return;
  tableSizeDrag.frame = 0;
  if (tableSizeDrag.pending == null) return;
  const sizes = tableSizeDrag.sizes.slice();
  sizes[tableSizeDrag.at] = tableSizeDrag.pending;
  if (tableSizeDrag.kind === 'row') pinTableRowHeights(tableSizeDrag.parts, sizes);
  else pinTableColumnWidths(tableSizeDrag.parts, sizes);
  if (!tableSizeDrag.marked) {
    tableSizeDrag.table.classList.add('is-reader-sized');
    tableSizeDrag.marked = true;
  }
}


function endTableSizeDrag(flushPending) {
  if (!tableSizeDrag) return;
  const { frame, table } = tableSizeDrag;
  if (flushPending) applyPendingTableSize();
  if (frame) cancelAnimationFrame(frame);
  leafReleasePointer(tableSizeDrag.grip, tableSizeDrag.pointerId);
  tableSizeDrag = null;
  document.body.classList.remove('table-resizing', 'is-row');
  rememberTableSizing(table);
}


function tableSizingGripUnder(target) {
  const grip = target && target.closest ? target.closest('.table-sizer') : null;
  if (!grip) return null;
  const cell = grip.parentElement;
  const table = cell && cell.closest ? cell.closest('table') : null;
  if (!table) return null;
  const row = grip.classList.contains('table-sizer-row');
  const parts = row ? tableSizingBodyRows(table) : tableSizingHeadCells(table);
  
  const at = row ? parts.indexOf(cell.parentElement) : tableSizingCellColumn(cell);
  return at < 0 ? null : { grip, cell, table, parts, at, kind: row ? 'row' : 'column' };
}


function tableRowContentHeight(row) {
  const given = row.style.height;
  row.style.height = '';
  const natural = row.getBoundingClientRect().height;
  row.style.height = given;
  return natural;
}

document.addEventListener('pointerdown', (event) => {
  if (event.button !== 0) return;
  const aimed = tableSizingGripUnder(event.target);
  if (!aimed) return;
  event.preventDefault();
  const row = aimed.kind === 'row';
  tableSizeDrag = {
    pointerId: event.pointerId,
    kind: aimed.kind,
    grip: aimed.grip,
    table: aimed.table,
    parts: aimed.parts,
    at: aimed.at,
    
    sizes: row ? tableSizingShape(aimed.table).rows : tableSizingWidths(aimed.parts),
    base: row ? aimed.parts[aimed.at].getBoundingClientRect().height : aimed.parts[aimed.at].getBoundingClientRect().width,
    floor: row ? tableRowContentHeight(aimed.parts[aimed.at]) : TABLE_COLUMN_FLOOR,
    from: row ? event.clientY : event.clientX,
    frame: 0,
    pending: null,
    marked: false,
  };
  leafHoldPointer(aimed.grip, event.pointerId);
  document.body.classList.add('table-resizing');
  if (row) document.body.classList.add('is-row');
});

document.addEventListener('pointermove', (event) => {
  if (!tableSizeDrag || event.pointerId !== tableSizeDrag.pointerId) return;
  const along = tableSizeDrag.kind === 'row' ? event.clientY : event.clientX;
  const reached = tableSizeDrag.base + (along - tableSizeDrag.from);
  tableSizeDrag.pending = Math.max(tableSizeDrag.floor, reached);
  if (!tableSizeDrag.frame) tableSizeDrag.frame = requestAnimationFrame(applyPendingTableSize);
});

document.addEventListener('pointerup', (event) => {
  if (!tableSizeDrag || event.pointerId !== tableSizeDrag.pointerId) return;
  endTableSizeDrag(true);
});


document.addEventListener('pointercancel', (event) => {
  if (!tableSizeDrag || event.pointerId !== tableSizeDrag.pointerId) return;
  endTableSizeDrag(true);
});


document.addEventListener('dblclick', (event) => {
  const aimed = tableSizingGripUnder(event.target);
  if (!aimed) return;
  event.preventDefault();
  const shape = tableSizingShape(aimed.table);
  const sizes = aimed.kind === 'row' ? shape.rows : shape.columns;
  sizes[aimed.at] = null;
  if (aimed.kind === 'row') pinTableRowHeights(aimed.parts, sizes);
  else pinTableColumnWidths(aimed.parts, sizes);
  aimed.table.classList.toggle('is-reader-sized', tableSizingShapeHasSize(shape));
  rememberTableSizing(aimed.table, shape);
});

function tableSheetOverlayElement() {
  return app ? app.querySelector('.table-sheet-overlay') : null;
}

function closeTableSheet() {
  const overlay = tableSheetOverlayElement();
  if (!overlay) return;
  
  dismissGlossary();
  const opener = overlay.__tableSheetOpener;
  const scrim = overlay.__tableSheetScrim;
  overlay.remove();
  if (scrim) scrim.remove();
  leafFocusForKeyboard(opener);
  
  restoreHintAfterSheet(overlay);
}


function clearReadingLaneLayout(copy) {
  tableSizingHeadCells(copy).forEach((cell) => {
    cell.style.width = '';
    cell.style.minWidth = '';
    cell.style.maxWidth = '';
  });
  tableSizingBodyRows(copy).forEach((row) => {
    row.style.height = '';
  });
  copy.classList.remove('is-reader-sized');
  if (!copy.dataset.lensLayout) copy.classList.remove('is-cards');
  copy.querySelectorAll('.table-sizer').forEach((grip) => grip.remove());
}

function tableSheetGrid(table) {
  const grid = document.createElement('div');
  
  grid.className = 'table-sheet-grid document-body';
  const copy = table.cloneNode(true);
  copy.classList.add('table-sheet-table');
  clearReadingLaneLayout(copy);
  copy.removeAttribute('contenteditable');
  copy.querySelectorAll('[contenteditable], [id]').forEach((element) => {
    element.removeAttribute('contenteditable');
    element.removeAttribute('id');
  });
  grid.appendChild(copy);
  return grid;
}

function scrollTableSheetHorizontally(event) {
  if ((!event.ctrlKey && !event.metaKey) || event.altKey || event.shiftKey || !event.deltaY) return;
  const grid = event.currentTarget;
  if (!grid || grid.scrollWidth <= grid.clientWidth) return;
  const end = grid.scrollWidth - grid.clientWidth;
  grid.scrollLeft = Math.max(0, Math.min(end, grid.scrollLeft + event.deltaY));
  event.preventDefault();
}

function openTableSheet(table, opener) {
  if (!app || !table || !tableWysiwygSafe(table)) return;
  closeTableSheet();
  const scrim = document.createElement('div');
  scrim.className = 'lt-backdrop';
  scrim.addEventListener('click', closeTableSheet);
  const overlay = document.createElement('section');
  overlay.className = 'table-sheet-overlay';
  overlay.setAttribute('role', 'dialog');
  overlay.setAttribute('aria-label', 'Table, full window');
  overlay.__tableSheetOpener = opener || null;
  overlay.__tableSheetScrim = scrim;
  const head = document.createElement('header');
  head.className = 'table-sheet-head';
  const title = document.createElement('h2');
  title.className = 'table-sheet-title';
  title.textContent = 'Table';
  const close = document.createElement('button');
  close.type = 'button';
  close.className = 'leaf-sheet-close table-sheet-close';
  close.title = 'Close — or press Escape';
  close.setAttribute('aria-label', 'Close the full-window table');
  close.innerHTML = `<span class="lt-icon lt-icon-close"></span>`;
  close.addEventListener('click', closeTableSheet);
  head.append(title, close);
  const grid = tableSheetGrid(table);
  grid.addEventListener('wheel', scrollTableSheetHorizontally, { passive: false });
  overlay.append(head, grid);
  app.append(scrim, overlay);
  
  suspendHintForSheet(overlay);
  if (window.__leafFrameless || window.__leafMacFrame) dragWindowFrom(head);
  window.requestAnimationFrame(() => {
    scrim.classList.add('open');
    overlay.classList.add('open');
  });
}

function bindTableSheet() {
  if (!app || currentDocumentFormat !== 'markdown') return;
  app.querySelectorAll('.table-lane > table[data-block-kind="table"]').forEach((table) => {
    if (!tableWysiwygSafe(table)) return;
    
    const row = tableLensRow(table.parentElement);
    const ends = row && row.querySelector(':scope > .table-lens-ends');
    if (!ends || ends.children.length) return;
    const opener = document.createElement('button');
    opener.type = 'button';
    opener.className = 'table-sheet-open';
    opener.title = 'Open table on the whole window';
    opener.setAttribute('aria-label', 'Open table on the whole window');
    opener.innerHTML = `<span class="lt-icon lt-icon-expand"></span>`;
    opener.addEventListener('click', (event) => {
      event.preventDefault();
      event.stopPropagation();
      openTableSheet(table, opener);
    });
    
    const copy = document.createElement('button');
    copy.type = 'button';
    copy.className = 'table-copy-csv';
    copy.title = 'Copy table as CSV';
    copy.setAttribute('aria-label', 'Copy table as CSV');
    copy.innerHTML = `<span class="lt-icon lt-icon-copy"></span>`;
    copy.addEventListener('click', (event) => {
      event.preventDefault();
      event.stopPropagation();
      copyPlainText(tableDomToCsv(table));
      leafToast('Table copied as CSV.');
    });
    ends.append(copy, opener);
  });
}


function csvCell(cell) {
  const words = String(cell && cell.textContent ? cell.textContent : '').trim();
  if (!/[",\n\r]/.test(words)) return words;
  return `"${words.replace(/"/g, '""')}"`;
}


function tableDomToCsv(table) {
  const rows = [];
  const head = table.querySelector(':scope > thead > tr');
  if (head) rows.push(Array.from(head.children).map(csvCell).join(','));
  table.querySelectorAll(':scope > tbody > tr').forEach((row) => {
    rows.push(Array.from(row.children).map(csvCell).join(','));
  });
  return rows.join('\n');
}

function onTableSheetKey(event) {
  if (event.key !== 'Escape' || !tableSheetOverlayElement()) return;
  
  if (!glossarySheet.hidden) return;
  event.preventDefault();
  event.stopPropagation();
  closeTableSheet();
}
document.addEventListener('keydown', onTableSheetKey, true);

function imageSheetOverlayElement() {
  return app ? app.querySelector('.image-sheet-overlay') : null;
}

function closeImageSheet() {
  const overlay = imageSheetOverlayElement();
  if (!overlay) return;
  const opener = overlay.__imageSheetOpener;
  const scrim = overlay.__imageSheetScrim;
  overlay.remove();
  if (scrim) scrim.remove();
  leafFocusForKeyboard(opener);
  
  restoreHintAfterSheet(overlay);
}


function openImageSheet(picture, opener) {
  if (!app || !picture || picture.dataset.imageMissing === 'true') return;
  closeImageSheet();
  const scrim = document.createElement('div');
  scrim.className = 'lt-backdrop';
  scrim.addEventListener('click', closeImageSheet);
  const overlay = document.createElement('section');
  overlay.className = 'image-sheet-overlay';
  overlay.setAttribute('role', 'dialog');
  
  overlay.setAttribute('aria-label', picture.alt ? `${picture.alt} — full window` : 'Picture, full window');
  overlay.__imageSheetOpener = opener || null;
  overlay.__imageSheetScrim = scrim;
  const shown = document.createElement('img');
  shown.className = 'image-sheet-picture';
  shown.alt = picture.alt || '';
  
  shown.src = picture.currentSrc || picture.src;
  
  const corner = document.createElement('div');
  corner.className = 'image-sheet-corner';
  const close = document.createElement('button');
  close.type = 'button';
  close.className = 'leaf-sheet-close image-sheet-close';
  close.title = 'Close — or press Escape';
  close.setAttribute('aria-label', 'Close the full-window picture');
  close.innerHTML = `<span class="lt-icon lt-icon-close"></span>`;
  close.addEventListener('click', closeImageSheet);
  corner.appendChild(close);
  
  overlay.addEventListener('click', (event) => {
    if (event.target !== shown) closeImageSheet();
  });
  overlay.append(shown, corner);
  app.append(scrim, overlay);
  
  suspendHintForSheet(overlay);
  window.requestAnimationFrame(() => {
    scrim.classList.add('open');
    overlay.classList.add('open');
  });
}




const PICTURE_EXPORTS = [
  { id: 'png', endings: ['png'], label: 'PNG', hint: 'The picture, to paste anywhere' },
  { id: 'webp', endings: ['webp'], label: 'WebP', hint: 'The same picture, about half the file' },
  { id: 'jpg', endings: ['jpg', 'jpeg'], label: 'JPEG', hint: 'For anything that will not take a WebP' },
  { id: 'pdf', endings: ['pdf'], label: 'PDF', hint: 'The picture on a page of its own' },
  
  { id: 'md', endings: ['md', 'markdown', 'mdown'], label: 'Markdown', hint: 'A document with the picture in an imgs folder beside it' },
];


const pictureExportsWaiting = new Map();
let pictureExportToken = 0;


function exportPicture(picture, format) {
  if (!picture) return;
  closeFlowMenu();
  pictureExportToken += 1;
  pictureExportsWaiting.set(pictureExportToken, picture);
  const ask = { command: 'pickPicturePath', token: pictureExportToken, source: picture.getAttribute('src') || '' };
  if (format) ask.format = format;
  send(ask);
}


function openPictureExportMenu(x, y, picture, host) {
  openFlowMenuWith(
    x,
    y,
    PICTURE_EXPORTS.map((kind) => ({
      label: kind.label,
      hint: kind.hint,
      run: () => exportPicture(picture, kind.id),
    })),
    host,
  );
}


function beginPictureExport(picture, button) {
  if (!picture) return;
  if (!isMacPlatform) {
    exportPicture(picture);
    return;
  }
  const spot = button.getBoundingClientRect();
  openPictureExportMenu(spot.left, spot.bottom + 6, picture, appSurface);
}


window.leafPicturePathPicked = (token, path) => {
  const picture = pictureExportsWaiting.get(token);
  if (picture === undefined) return;
  pictureExportsWaiting.delete(token);
  const text = String(path);
  const dot = text.lastIndexOf('.');
  const kind = dot < 0 ? '' : text.slice(dot + 1).toLowerCase();
  
  const row = PICTURE_EXPORTS.find((one) => one.endings.includes(kind));
  if (!row) {
    const names = PICTURE_EXPORTS.map((one) => one.label).join(', ');
    leafToast('A picture is written as ' + names + '. Nothing was written.', 'error');
    return;
  }
  exportPictureAs(row.id, picture, path);
};


const picturePrint = document.getElementById('picturePrint');


let picturePrinting = false;


function clearPicturePrint() {
  if (picturePrint) picturePrint.innerHTML = '';
  document.body.classList.remove('leaf-paper-picture');
  if (!picturePrinting) return;
  picturePrinting = false;
  if (window.leafHoldAppearance) window.leafHoldAppearance(false);
}


window.leafPicturePrinted = () => clearPicturePrint();




function printPictureAsPdf(picture, path) {
  if (!picturePrint) throw new Error('This window cannot print a picture.');
  const box = picture.getBoundingClientRect();
  const width = Math.max(Math.round(picture.naturalWidth || box.width), 1);
  const height = Math.max(Math.round(picture.naturalHeight || box.height), 1);
  const shown = document.createElement('img');
  shown.alt = picture.alt || '';
  shown.width = width;
  shown.height = height;
  
  shown.src = picture.currentSrc || picture.src;
  picturePrint.innerHTML = '';
  picturePrint.appendChild(shown);
  document.body.classList.add('leaf-paper-picture');
  
  picturePrinting = true;
  if (window.leafHoldAppearance) window.leafHoldAppearance(true);
  send({ command: 'printPicturePdf', path, width, height });
}




const PICTURE_WEBP_LIMIT = 16383;


function pictureSourceEnding(picture) {
  const src = (picture.getAttribute('src') || '').split(/[?#]/)[0];
  const dot = src.lastIndexOf('.');
  return dot < 0 ? '' : src.slice(dot + 1).toLowerCase();
}




function pictureCanvas(picture, background) {
  return new Promise((resolve, reject) => {
    const asked = new Image();
    asked.crossOrigin = 'anonymous';
    asked.onload = () => {
      const canvas = document.createElement('canvas');
      canvas.width = Math.max(1, asked.naturalWidth || picture.naturalWidth || 1);
      canvas.height = Math.max(1, asked.naturalHeight || picture.naturalHeight || 1);
      const ink = canvas.getContext('2d');
      if (!ink) {
        reject(new Error('This window cannot make a picture.'));
        return;
      }
      
      if (background) {
        ink.fillStyle = background;
        ink.fillRect(0, 0, canvas.width, canvas.height);
      }
      ink.drawImage(asked, 0, 0, canvas.width, canvas.height);
      resolve(canvas);
    };
    asked.onerror = () => reject(new Error('That picture could not be read, so nothing was written.'));
    asked.src = picture.currentSrc || picture.src;
  });
}


const PICTURE_JPEG_QUALITY = 0.92;

const MAX_CLIPBOARD_PNG_BYTES = 128 * 1024 * 1024;


async function pictureExportCanvas(picture, type) {
  
  const canvas = await pictureCanvas(picture, type === 'image/jpeg' ? leafExportBackground() : null);
  if (type === 'image/webp' && (canvas.width > PICTURE_WEBP_LIMIT || canvas.height > PICTURE_WEBP_LIMIT)) {
    throw new Error('This picture is too big for WebP to hold. Export it as PNG instead.');
  }
  return canvas;
}


function pictureTypeRefused(type) {
  return new Error('This window cannot write ' + type.slice(6).toUpperCase() + '. Export it as PNG instead.');
}


async function pictureFile(picture, type) {
  const canvas = await pictureExportCanvas(picture, type);
  const file = await new Promise((resolve) =>
    type === 'image/jpeg' ? canvas.toBlob(resolve, type, PICTURE_JPEG_QUALITY) : canvas.toBlob(resolve, type)
  );
  
  if (!file || file.type !== type) throw pictureTypeRefused(type);
  return file;
}


async function pictureFileBase64(picture, type) {
  const canvas = await pictureExportCanvas(picture, type);
  const url = type === 'image/jpeg' ? canvas.toDataURL(type, PICTURE_JPEG_QUALITY) : canvas.toDataURL(type);
  if (url.indexOf('data:' + type + ';') !== 0 && url.indexOf('data:' + type + ',') !== 0) {
    throw pictureTypeRefused(type);
  }
  return url.slice(url.indexOf(',') + 1);
}


async function postPictureExport(picture, kind, type, path, source) {
  const file = await pictureFile(picture, type);
  if (file.size > MAX_CLIPBOARD_PNG_BYTES) throw new Error('That picture is too big to export.');
  
  if (!window.__leafPictureExportEndpoint) throw new Error('That picture could not be exported.');
  const query =
    'format=' + encodeURIComponent(kind) + '&source=' + encodeURIComponent(source) + '&target=' + encodeURIComponent(path);
  const response = await fetch(window.__leafPictureExportEndpoint + '?' + query, {
    method: 'POST',
    headers: { 'Content-Type': type },
    body: file,
  });
  if (!response.ok) throw new Error('That picture could not be exported.');
}


async function copyPicture(picture) {
  try {
    if (window.__leafPictureClipboardEndpoint) {
      const canvas = await pictureCanvas(picture, null);
      const png = await new Promise((resolve) => canvas.toBlob(resolve, 'image/png'));
      if (!png) throw new Error('That picture could not be copied.');
      if (png.size > MAX_CLIPBOARD_PNG_BYTES) throw new Error('That picture is too big to copy.');
      const response = await fetch(window.__leafPictureClipboardEndpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'image/png' },
        body: png,
      });
      if (!response.ok) throw new Error('That picture could not be copied.');
      return;
    }
    send({ command: 'copyImage', data: await pictureFileBase64(picture, 'image/png') });
  } catch (error) {
    leafToast((error && error.message) || 'That picture could not be copied.', 'error');
  }
}


async function exportPictureAs(kind, picture, path) {
  try {
    if (kind === 'pdf') {
      printPictureAsPdf(picture, path);
      return;
    }
    const row = PICTURE_EXPORTS.find((one) => one.id === kind);
    if (kind === 'png' || kind === 'webp' || kind === 'jpg') {
      const source = picture.getAttribute('src') || '';
      
      if (row.endings.includes(pictureSourceEnding(picture))) {
        send({ command: 'exportPicture', format: kind, path, source });
        return;
      }
      
      await postPictureExport(picture, kind, kind === 'jpg' ? 'image/jpeg' : 'image/' + kind, path, source);
      return;
    }
    if (kind === 'md') {
      
      send({
        command: 'exportPicture',
        format: 'md',
        path,
        source: picture.getAttribute('src') || '',
        alt: picture.alt || '',
      });
    }
  } catch (error) {
    leafToast((error && error.message) || 'That picture could not be exported.', 'error');
  }
}


function bindImageSheet(root = app) {
  if (!root) return;
  
  const lanes = '.reader-layout > .document-body > p.image-lane';
  
  const blocks = root.matches && root.matches(lanes) ? [root] : root.querySelectorAll(lanes);
  blocks.forEach((block) => {
    if (block.querySelector(':scope > .image-lane-corner')) return;
    const picture = block.querySelector(':scope > img');
    if (!picture || picture.dataset.imageMissing === 'true') return;
    
    const corner = document.createElement('div');
    corner.className = 'image-lane-corner';
    const opener = document.createElement('button');
    opener.type = 'button';
    opener.className = 'image-sheet-open';
    opener.title = 'Open picture on the whole window';
    opener.setAttribute('aria-label', 'Open picture on the whole window');
    opener.innerHTML = `<span class="lt-icon lt-icon-expand"></span>`;
    corner.appendChild(opener);
    
    if (isLocalImageSrc(picture.getAttribute('src') || '')) {
      const save = document.createElement('button');
      save.type = 'button';
      save.className = 'image-export-open';
      save.title = 'Export this picture';
      save.setAttribute('aria-label', 'Export this picture');
      save.innerHTML = `<span class="lt-icon lt-icon-export"></span>`;
      corner.appendChild(save);
    }
    block.appendChild(corner);
  });
}

if (app) {
  onColumn('click', (event) => {
    if (!event.target || !event.target.closest) return;
    const control = event.target.closest('.image-sheet-open, .image-export-open');
    if (!control) return;
    const corner = control.closest('.image-lane-corner');
    const block = corner && corner.parentElement;
    const picture = block && block.querySelector(':scope > img');
    if (!picture) return;
    event.preventDefault();
    event.stopPropagation();
    if (control.classList.contains('image-export-open')) beginPictureExport(picture, control);
    else openImageSheet(picture, control);
  });
}

function onImageSheetKey(event) {
  if (event.key !== 'Escape' || !imageSheetOverlayElement()) return;
  event.preventDefault();
  event.stopPropagation();
  closeImageSheet();
}
document.addEventListener('keydown', onImageSheetKey, true);

let packagedPictureObserver = null;

const packagedPicturesAsked = new Set();

const packagedPicturesMinted = new Map();

function packagedPictureTags(root) {
  return root ? root.querySelectorAll('[data-leaf-picture]') : [];
}

function fillPackagedPicture(tag, address) {
  
  if (tag.localName === 'image') tag.setAttribute('href', address);
  else tag.setAttribute('src', address);
}

function askForPackagedPicture(member) {
  if (!member || packagedPicturesAsked.has(member)) return;
  packagedPicturesAsked.add(member);
  send({ command: 'packagedPicture', member });
}

function watchPackagedPictures() {
  if (packagedPictureObserver) packagedPictureObserver.disconnect();
  const body = app ? app.querySelector('.document-body') : null;
  const tags = Array.from(packagedPictureTags(body)).filter((tag) => !tag.hasAttribute('src') && !tag.hasAttribute('href'));
  const waiting = [];
  for (const tag of tags) {
    const minted = packagedPicturesMinted.get(tag.getAttribute('data-leaf-picture'));
    if (minted) fillPackagedPicture(tag, minted);
    else waiting.push(tag);
  }
  if (!waiting.length) return;
  if (typeof IntersectionObserver === 'undefined') {
    for (const tag of waiting) askForPackagedPicture(tag.getAttribute('data-leaf-picture'));
    return;
  }
  if (!packagedPictureObserver) {
    
    packagedPictureObserver = new IntersectionObserver((entries) => {
      for (const entry of entries) {
        if (!entry.isIntersecting) continue;
        packagedPictureObserver.unobserve(entry.target);
        askForPackagedPicture(entry.target.getAttribute('data-leaf-picture'));
      }
    }, { root: app, rootMargin: '100% 0px' });
  }
  for (const tag of waiting) packagedPictureObserver.observe(tag);
}


window.leafPictureMinted = (member, address) => {
  if (!member || !address) return;
  packagedPicturesMinted.set(member, address);
  for (const root of [app, readerMinimap]) {
    for (const tag of packagedPictureTags(root)) {
      if (tag.getAttribute('data-leaf-picture') === member) fillPackagedPicture(tag, address);
    }
  }
};


window.leafForgetMintedPictures = () => {
  packagedPicturesAsked.clear();
  packagedPicturesMinted.clear();
  if (packagedPictureObserver) packagedPictureObserver.disconnect();
};





function diagramOverlayElement() {
  return app ? app.querySelector('.diagram-overlay') : null;
}

function openDiagramOverlay(diagram, opener) {
  if (!app || !diagram || diagram.__mermaidSource == null) return;
  closeDiagramOverlay();
  const scrim = document.createElement('div');
  scrim.className = 'lt-backdrop';
  scrim.addEventListener('click', closeDiagramOverlay);
  const overlay = document.createElement('div');
  overlay.className = 'diagram-overlay';
  overlay.setAttribute('role', 'dialog');
  overlay.setAttribute('aria-label', 'Diagram, full window');
  
  overlay.__diagramOpener = opener || null;
  overlay.__diagramScrim = scrim;
  
  overlay.__diagramBlock = diagram;
  const stage = document.createElement('pre');
  stage.className = 'mermaid diagram-stage';
  
  stage.dataset.diagramStage = 'true';
  stage.__mermaidSource = diagram.__mermaidSource;
  overlay.appendChild(stage);
  app.appendChild(scrim);
  app.appendChild(overlay);
  
  suspendHintForSheet(overlay);
  window.requestAnimationFrame(() => {
    scrim.classList.add('open');
    overlay.classList.add('open');
  });
  drawDiagramStage(stage);
}

function closeDiagramOverlay() {
  if (!app) return;
  const overlay = diagramOverlayElement();
  if (!overlay) return;
  overlay.remove();
  if (overlay.__diagramScrim) overlay.__diagramScrim.remove();
  leafFocusForKeyboard(overlay.__diagramOpener);
  
  restoreHintAfterSheet(overlay);
}


function onDiagramOverlayKey(event) {
  if (event.key !== 'Escape' || !diagramOverlayElement()) return;
  event.preventDefault();
  event.stopPropagation();
  closeDiagramOverlay();
}
document.addEventListener('keydown', onDiagramOverlayKey, true);


function drawDiagramStage(stage) {
  const source = stage.__mermaidSource;
  if (source == null) return;
  
  stage.__mermaidNatural = null;
  stage.__mermaidView = null;
  stage.classList.remove('is-moved');
  stage.style.removeProperty('--mermaid-box-height');
  stage.style.removeProperty('--mermaid-pan-x');
  stage.style.removeProperty('--mermaid-pan-y');
  stage.textContent = source;
  delete stage.dataset.processed;
  delete stage.dataset.mermaidRender;
  loadMermaid()
    .then(async (mermaid) => {
      if (!stage.isConnected) return;
      if (document.fonts && document.fonts.ready) await document.fonts.ready;
      if (!stage.isConnected) return;
      mermaid.initialize(mermaidRuntimeConfig());
      try {
        await mermaid.run({ nodes: [stage] });
      } catch (error) {
        console.error(error);
        await markMermaidFailed(mermaid, stage);
      }
    })
    .catch((error) => {
      console.error(error);
    })
    .then(() => {
      addDiagramStageControls(stage);
    });
}


function addDiagramStageControls(stage) {
  if (!stage.isConnected || stage.querySelector('.mermaid-view-controls')) return;
  const close = document.createElement('button');
  close.type = 'button';
  close.className = 'leaf-sheet-close diagram-close';
  close.title = 'Close — or press Escape';
  close.setAttribute('aria-label', 'Close the full-window diagram');
  close.innerHTML = `<span class="lt-icon lt-icon-close"></span>`;
  close.addEventListener('click', closeDiagramOverlay);
  stage.appendChild(close);
  
  const row = document.createElement('div');
  row.className = 'mermaid-view-controls';
  row.appendChild(mermaidExportButton());
  row.appendChild(mermaidZoomGroup(MERMAID_ZOOM_BUTTONS, 'Zoom'));
  stage.appendChild(row);
  addDiagramStageTools(stage);
}


function addDiagramStageTools(stage) {
  const overlay = stage.parentElement;
  const block = overlay ? overlay.__diagramBlock : null;
  if (!block || currentDocumentFormat !== 'markdown' || !readerEditingAllowed()) return;
  const { start, end } = rangeOf(block, 'block');
  if (!Number.isFinite(start) || !Number.isFinite(end)) return;
  const tools = document.createElement('div');
  tools.className = 'mermaid-tools';
  tools.appendChild(mermaidToolButton('source', 'Edit the Mermaid text of this diagram', `<span class="lt-icon lt-icon-code-view"></span>`));
  tools.appendChild(mermaidToolButton('sheet', 'Open in the flowchart editor, to draw it', `<span class="lt-icon lt-icon-workflow"></span>`));
  tools.addEventListener('click', (event) => {
    const tool = event.target && event.target.closest ? event.target.closest('.mermaid-tool') : null;
    if (!tool) return;
    event.preventDefault();
    event.stopPropagation();
    closeDiagramOverlay();
    if (tool.dataset.mermaidTool === 'source') startBlockSourceEdit(block);
    else openMermaidBlockSheet(block);
  });
  stage.appendChild(tools);
}


function repaintDiagramOverlay() {
  const overlay = diagramOverlayElement();
  const stage = overlay ? overlay.querySelector('.diagram-stage') : null;
  if (stage) drawDiagramStage(stage);
}



const MONACO_FONT_SIZE = 14;
